window.QDATA = {"domains": [{"id": "databricks-intelligence-platform", "name": "Databricks Intelligence Platform", "namePt": "Plataforma Databricks", "weight": 6, "folder": "01-databricks-intelligence-platform"}, {"id": "data-ingestion-and-loading", "name": "Data Ingestion and Loading", "namePt": "Ingestão e Carga de Dados", "weight": 21, "folder": "02-data-ingestion-and-loading"}, {"id": "data-transformation-and-modeling", "name": "Data Transformation and Modeling", "namePt": "Transformação e Modelagem", "weight": 22, "folder": "03-data-transformation-and-modeling"}, {"id": "working-with-lakeflow-jobs", "name": "Working with Lakeflow Jobs", "namePt": "Lakeflow Jobs", "weight": 16, "folder": "04-working-with-lakeflow-jobs"}, {"id": "implementing-cicd", "name": "Implementing CI/CD", "namePt": "CI/CD", "weight": 10, "folder": "05-implementing-cicd"}, {"id": "troubleshooting-monitoring-and-optimization", "name": "Troubleshooting, Monitoring, and Optimization", "namePt": "Troubleshooting, Monitoramento e Otimização", "weight": 10, "folder": "06-troubleshooting-monitoring-and-optimization"}, {"id": "governance-and-security", "name": "Governance and Security", "namePt": "Governança e Segurança", "weight": 15, "folder": "07-governance-and-security"}], "banks": [{"id": "praticas", "label": "Questões práticas", "kind": "practice", "count": 145}, {"id": "simulado-1", "label": "Simulado 1", "kind": "mock", "count": 45}, {"id": "simulado-2", "label": "Simulado 2", "kind": "mock", "count": 45}], "questions": [{"id": "01-databricks-intelligence-platform-q001", "bank": "praticas", "n": 1, "domain": "databricks-intelligence-platform", "title": "Lakehouse as a Unified Source of Truth", "difficulty": "medium", "question": "A leader in data organization is frustrated because the reports from the data analysis team differ from those of the data engineering team. How might a data lakehouse resolve this issue?", "choices": {"A": "Both teams would utilize the same source of truth for their tasks", "B": "Each team would maintain separate copies of data optimized for their specific workloads", "C": "The data lakehouse would automatically reconcile differences between team reports", "D": "A dedicated ETL pipeline would synchronize data between team-specific databases"}, "answer": "A", "short": "Both teams would utilize the same source of truth for their tasks.", "explanation": "A data lakehouse provides a single, unified platform where all teams access the same underlying data, eliminating discrepancies caused by siloed data systems or separate copies of data maintained by different teams.", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q002", "bank": "praticas", "n": 2, "domain": "databricks-intelligence-platform", "title": "Control Plane Components", "difficulty": "easy", "question": "Which option is entirely hosted within the control plane of the classic Databricks architecture?", "choices": {"A": "Worker nodes and executor processes", "B": "The Databricks web application", "C": "Customer-managed cloud storage buckets", "D": "Driver nodes and cluster compute resources"}, "answer": "B", "short": "The Databricks web application.", "explanation": "The control plane hosts the Databricks web UI, REST APIs, notebook server, and cluster manager — all infrastructure managed by Databricks. Worker nodes and driver nodes reside in the customer's data plane (their cloud account).", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q003", "bank": "praticas", "n": 3, "domain": "databricks-intelligence-platform", "title": "Delta Lake Advantage for Workloads", "difficulty": "easy", "question": "Which of the following advantages associated with the Databricks Lakehouse Platform is offered by Delta Lake?", "choices": {"A": "The ability to run SQL queries without requiring a compute cluster", "B": "Automatic migration of legacy Hive tables to cloud-native formats", "C": "The ability to support both batch and streaming workloads", "D": "Built-in machine learning model training on raw data files"}, "answer": "C", "short": "The ability to support both batch and streaming workloads.", "explanation": "Delta Lake's transaction log and Structured Streaming integration allow the same Delta tables to be read and written by both batch jobs and streaming pipelines, eliminating the need for separate storage systems for each workload type.", "lesson": "01-databricks-intelligence-platform/04-delta-lake-fundamentals", "related": null}, {"id": "01-databricks-intelligence-platform-q004", "bank": "praticas", "n": 4, "domain": "databricks-intelligence-platform", "title": "Delta Table Storage Organization", "difficulty": "easy", "question": "What describes how a Delta table is organized for storage?", "choices": {"A": "Delta tables are stored as CSV files with a separate JSON manifest tracking schema changes", "B": "Delta tables are stored as a single monolithic binary file containing all rows and metadata", "C": "Delta tables are stored exclusively in the Databricks control plane with pointers to cloud storage", "D": "Delta tables are stored in a collection of files that contain data, history, metadata, and other attributes"}, "answer": "D", "short": "Delta tables are stored in a collection of files that contain data, history, metadata, and other attributes.", "explanation": "Data is stored in Parquet files, and the `_delta_log` directory contains JSON transaction log files and checkpoint files that track all changes, schema, and table properties.", "lesson": "01-databricks-intelligence-platform/04-delta-lake-fundamentals", "related": null}, {"id": "01-databricks-intelligence-platform-q005", "bank": "praticas", "n": 5, "domain": "databricks-intelligence-platform", "title": "VACUUM and Time Travel", "difficulty": "medium", "question": "A data engineer discovered an error while updating a table daily and needs to use Delta time travel to revert the table to a version from three days ago. However, when they try to access the older version, the data files are absent. What explains the absence of the data files?", "choices": {"A": "The VACUUM command was run on the table", "B": "The OPTIMIZE command was run, which compacted and removed older file versions", "C": "The table was converted from Parquet to Delta, erasing its version history", "D": "The Delta transaction log automatically purges entries older than 24 hours"}, "answer": "A", "short": "The VACUUM command was run on the table.", "explanation": "`VACUUM` permanently deletes data files that are outside the retention threshold (default 7 days). Once vacuumed, older versions cannot be restored via time travel because the underlying Parquet files no longer exist.", "lesson": "01-databricks-intelligence-platform/05-time-travel-versioning", "related": null}, {"id": "01-databricks-intelligence-platform-q006", "bank": "praticas", "n": 6, "domain": "databricks-intelligence-platform", "title": "Data Quality Feature of a Lakehouse", "difficulty": "easy", "question": "Which feature of a data lakehouse enhances data quality compared to a traditional data lake?", "choices": {"A": "Native support for unstructured binary file formats", "B": "A data lakehouse supports ACID-compliant transactions", "C": "Automatic data replication across multiple cloud regions", "D": "Built-in data visualization and dashboarding tools"}, "answer": "B", "short": "A data lakehouse supports ACID-compliant transactions.", "explanation": "Traditional data lakes lack transactional guarantees, which can lead to partial writes, inconsistent reads, and data corruption. ACID transactions in Delta Lake ensure atomicity, consistency, isolation, and durability for all operations.", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q007", "bank": "praticas", "n": 7, "domain": "databricks-intelligence-platform", "title": "Gold vs Silver Table Relationship", "difficulty": "easy", "question": "What best explains the connection between Gold tables and Silver tables?", "choices": {"A": "Gold tables store raw data while Silver tables store transformed data", "B": "Gold tables are temporary views derived from permanent Silver tables", "C": "Gold tables are more likely to contain aggregations than Silver tables", "D": "Gold tables and Silver tables always share the same schema and row count"}, "answer": "C", "short": "Gold tables are more likely to contain aggregations than Silver tables.", "explanation": "Gold tables represent business-level aggregates and metrics built for consumption in dashboards and reports. Silver tables contain cleaned and enriched data, but are typically at row-level granularity without the summarizations found in Gold.", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q008", "bank": "praticas", "n": 8, "domain": "databricks-intelligence-platform", "title": "Bronze vs Raw Data Relationship", "difficulty": "easy", "question": "What characterizes the connection between Bronze tables and raw data?", "choices": {"A": "Bronze tables contain only validated and schema-enforced records from source systems", "B": "Bronze tables are external tables pointing directly to raw source files without any transformation", "C": "Bronze tables store aggregated summaries of raw data for downstream consumption", "D": "Bronze tables contain raw data with a schema applied"}, "answer": "D", "short": "Bronze tables contain raw data with a schema applied.", "explanation": "Bronze is the first layer in the medallion architecture. Data is ingested from source systems with minimal transformation, but is captured in a structured Delta table format with metadata columns added (e.g., ingestion timestamp, source file).", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q009", "bank": "praticas", "n": 9, "domain": "databricks-intelligence-platform", "title": "Open-Source Technology Advantage", "difficulty": "easy", "question": "What is one advantage of the Databricks Lakehouse Platform utilizing open-source technologies?", "choices": {"A": "Avoiding vendor lock-in", "B": "Eliminating the need for cloud infrastructure providers", "C": "Guaranteeing backward compatibility with all legacy data systems", "D": "Providing free unlimited compute resources for open-source users"}, "answer": "A", "short": "Avoiding vendor lock-in.", "explanation": "By building on open standards and formats — Delta Lake (open format), Apache Spark, MLflow — organizations retain the ability to move data and workloads across clouds and platforms without being tied to proprietary, closed formats.", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q010", "bank": "praticas", "n": 10, "domain": "databricks-intelligence-platform", "title": "Delta Lake Underlying File Format", "difficulty": "easy", "question": "Which file formats are primarily used to store data from Delta Lake tables?", "choices": {"A": "Avro", "B": "Parquet", "C": "CSV", "D": "ORC"}, "answer": "B", "short": "Parquet.", "explanation": "Delta Lake stores all data in Parquet files, an open columnar format that provides efficient compression and predicate pushdown. The `_delta_log` directory stores transaction metadata as JSON and Parquet checkpoint files, but data itself is always Parquet.", "lesson": "01-databricks-intelligence-platform/04-delta-lake-fundamentals", "related": null}, {"id": "01-databricks-intelligence-platform-q011", "bank": "praticas", "n": 11, "domain": "databricks-intelligence-platform", "title": "Customer Cloud Account Contents", "difficulty": "easy", "question": "What is stored in the cloud account of the Databricks customer?", "choices": {"A": "The Databricks web application and REST APIs", "B": "Cluster management metadata and job configurations", "C": "Data", "D": "Notebook source code and revision history"}, "answer": "C", "short": "Data.", "explanation": "The customer's cloud account (AWS S3, Azure ADLS, GCP GCS) stores the actual data files. Databricks infrastructure — including the web application, cluster management metadata, repos, and notebooks — is managed in the Databricks-controlled plane, not the customer's account.", "lesson": "01-databricks-intelligence-platform/02-databricks-workspace", "related": null}, {"id": "01-databricks-intelligence-platform-q012", "bank": "praticas", "n": 12, "domain": "databricks-intelligence-platform", "title": "Streamlining Data Architectures", "difficulty": "medium", "question": "What methods can help streamline and integrate distinct data architectures tailored for particular applications?", "choices": {"A": "Building custom ETL pipelines between each pair of data systems", "B": "Deploying separate data warehouses for each business unit", "C": "Using a message queue to synchronize data between independent databases", "D": "A data lakehouse"}, "answer": "D", "short": "A data lakehouse.", "explanation": "The lakehouse architecture unifies the flexibility of a data lake (support for unstructured data, low-cost storage, ML workloads) with the reliability and governance of a data warehouse (ACID transactions, SQL support, schema enforcement) into a single platform.", "lesson": "01-databricks-intelligence-platform/01-lakehouse-architecture", "related": null}, {"id": "01-databricks-intelligence-platform-q013", "bank": "praticas", "n": 13, "domain": "databricks-intelligence-platform", "title": "When to Use Cluster Pools", "difficulty": "medium", "question": "When would a data team use cluster pools?", "choices": {"A": "When an automated report needs to be refreshed as quickly as possible", "B": "When clusters need to share data between concurrent jobs", "C": "When reducing cloud storage costs for intermediate data is the priority", "D": "When enforcing uniform cluster configurations across all team members"}, "answer": "A", "short": "When an automated report needs to be refreshed as quickly as possible.", "explanation": "Cluster pools maintain a set of pre-warmed, idle VM instances that can be assigned to clusters immediately on startup. This eliminates the VM provisioning delay (which can take several minutes), reducing cluster startup time to seconds for time-sensitive jobs.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q014", "bank": "praticas", "n": 14, "domain": "databricks-intelligence-platform", "title": "SQL Warehouse Scaling for Concurrent Queries", "difficulty": "medium", "question": "A data analysis team's Databricks SQL queries perform poorly when multiple members execute small queries simultaneously on an always-on SQL warehouse. All queries use the same endpoint. What strategy improves performance?", "choices": {"A": "Switch from a Pro to a Classic SQL warehouse type", "B": "Increase the maximum bound of the SQL warehouse's scaling range", "C": "Increase the size (T-shirt size) of each individual cluster in the endpoint", "D": "Enable query result caching on the SQL warehouse"}, "answer": "B", "short": "Increase the maximum bound of the SQL warehouse's scaling range.", "explanation": "A SQL warehouse (warehouse) can auto-scale by adding more clusters when concurrent query load increases. Raising the maximum cluster count allows the endpoint to serve more parallel queries simultaneously, reducing wait times during peak concurrent usage.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q015", "bank": "praticas", "n": 15, "domain": "databricks-intelligence-platform", "title": "Reducing SQL Warehouse Cost on a Daily Dashboard", "difficulty": "medium", "question": "A data engineer sets a Databricks SQL dashboard to refresh daily and wants the related SQL warehouse to run only when needed. What strategy reduces the overall running time of the SQL warehouse?", "choices": {"A": "Downgrade the SQL warehouse to a smaller cluster size", "B": "Configure the SQL warehouse to start only during business hours", "C": "Turn on the Auto Stop feature for the SQL warehouse", "D": "Switch the dashboard to use a shared all-purpose cluster instead"}, "answer": "C", "short": "Turn on the Auto Stop feature for the SQL warehouse.", "explanation": "Auto Stop automatically terminates the SQL warehouse after a configurable idle period. After the dashboard refresh completes, the endpoint shuts down automatically — avoiding continuous compute charges during the long idle period between daily refreshes.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q016", "bank": "praticas", "n": 16, "domain": "databricks-intelligence-platform", "title": "Faster Cluster Startup for Nightly Jobs", "difficulty": "easy", "question": "A data engineer manages a nightly job with several tasks that run slowly due to long cluster startup times. What action improves cluster startup time?", "choices": {"A": "Increase the driver node memory allocation", "B": "Switch to a single-node cluster to avoid worker provisioning", "C": "Enable autoscaling with a higher maximum worker count", "D": "Use clusters from a cluster pool"}, "answer": "D", "short": "Use clusters from a cluster pool.", "explanation": "Cluster pools pre-provision and maintain idle instances that are immediately available for cluster creation. Tasks using pool-backed clusters skip the VM provisioning step, reducing startup from several minutes to a few seconds.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q017", "bank": "praticas", "n": 17, "domain": "databricks-intelligence-platform", "title": "Minimizing SQL Warehouse Runtime on an Hourly Dashboard", "difficulty": "medium", "question": "A data engineer has an hourly Databricks SQL dashboard whose underlying data is managed by an automated Databricks Job. How can they minimize the total running time of the SQL warehouse during the dashboard's hourly refresh?", "choices": {"A": "Turn on the Auto Stop feature for the SQL warehouse", "B": "Use a shared all-purpose cluster instead of a SQL warehouse", "C": "Pre-compute dashboard results in the Databricks Job and cache them", "D": "Reduce the SQL warehouse cluster size to the smallest available"}, "answer": "A", "short": "Turn on the Auto Stop feature for the SQL warehouse.", "explanation": "Auto Stop shuts down the SQL warehouse after a defined idle period following the last query. Since the dashboard only needs the endpoint during the brief refresh window each hour, Auto Stop ensures the endpoint is off for the remaining idle time between refreshes.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q018", "bank": "praticas", "n": 18, "domain": "databricks-intelligence-platform", "title": "When to Use a Single-Node Cluster", "difficulty": "medium", "question": "What scenario would prompt a data engineer to use a single-node cluster?", "choices": {"A": "When running a distributed join across tables with billions of rows", "B": "When working interactively with a small amount of data", "C": "When deploying a production Lakeflow Declarative Pipelines pipeline with multiple streaming sources", "D": "When maximizing parallelism for a large-scale ETL workload"}, "answer": "B", "short": "When working interactively with a small amount of data.", "explanation": "Single-node clusters run both the driver and executor on the same machine, making them suitable for development, exploratory data analysis on small datasets, and libraries that do not support distributed execution (e.g., some scikit-learn workflows). They are not appropriate for large-scale production jobs.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q019", "bank": "praticas", "n": 19, "domain": "databricks-intelligence-platform", "title": "Using SQL in a Python Notebook Cell", "difficulty": "easy", "question": "A data engineer is working in a Python notebook on Databricks but needs to use SQL for one specific cell. They prefer that all other cells remain Python. How can they incorporate SQL into only that cell?", "choices": {"A": "Change the notebook's default language to SQL and then switch back", "B": "Wrap the SQL query in `spark.sql()` and assign it to a variable", "C": "Add `%sql` to the first line of the cell", "D": "Import the `sql` module and call `sql.execute()`"}, "answer": "C", "short": "Add `%sql` to the first line of the cell.", "explanation": "Databricks magic commands (`%sql`, `%python`, `%scala`, `%r`) override the cell language for that individual cell only. All other cells continue using the notebook's default language. This allows mixing languages within a single notebook without changing the global setting.", "lesson": "01-databricks-intelligence-platform/02-databricks-workspace", "related": null}, {"id": "01-databricks-intelligence-platform-q020", "bank": "praticas", "n": 20, "domain": "databricks-intelligence-platform", "title": "Compute for Concurrent Ad Hoc SQL *(2026 blueprint)*", "difficulty": "medium", "question": "Throughout the day, dozens of business analysts run short, ad hoc SQL queries against curated Gold tables. The team wants fast startup, good performance as concurrency rises, and no paying for a large cluster that sits idle overnight. Which compute should they use?", "choices": {"A": "An all-purpose cluster with a fixed 20 workers, shared by all analysts", "B": "A single-node cluster per analyst", "C": "A jobs compute cluster created for each query", "D": "A serverless SQL warehouse with autoscaling (maximum clusters raised) and auto stop"}, "answer": "D", "short": "A serverless SQL warehouse with autoscaling (maximum clusters raised) and auto stop.", "explanation": "Serverless SQL warehouses start in about 2–6 seconds, scale out by adding clusters as queries queue, and auto stop after idle time (10 minutes by default). A fixed all-purpose cluster pays for peak capacity all day. Jobs compute exists only for scheduled job runs. Single-node clusters don't share capacity or scale for concurrency ([SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types)).", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "01-databricks-intelligence-platform-q021", "bank": "praticas", "n": 21, "domain": "databricks-intelligence-platform", "title": "Characteristics of Serverless Compute *(2026 blueprint)*", "difficulty": "easy", "question": "Which statement about serverless compute for notebooks and jobs is correct?", "choices": {"A": "Serverless workloads always run on the latest runtime version, and compute is managed by Databricks", "B": "Serverless compute supports setting any Spark configuration and custom init scripts", "C": "You choose the Databricks Runtime version and instance types for each serverless job", "D": "Serverless compute is available only in workspaces that use the legacy Hive metastore"}, "answer": "A", "short": "Serverless workloads always run on the latest runtime version, and compute is managed by Databricks.", "explanation": "Serverless is versionless and Databricks-managed, so you don't pick runtimes or instance types. Only a short list of Spark properties can be set (for example `spark.sql.shuffle.partitions`), and dependencies are managed with environments. Workspaces without Unity Catalog must upgrade before they can use serverless ([Connect to serverless compute](https://docs.databricks.com/aws/en/compute/serverless/), [Spark configuration](https://docs.databricks.com/aws/en/spark/conf)).", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "02-data-ingestion-and-loading-q001", "bank": "praticas", "n": 22, "domain": "data-ingestion-and-loading", "title": "JDBC Format for SQLite", "difficulty": "easy", "question": "A data engineer needs to create a table in Databricks using data from the organization's SQLite database. They set up a JDBC connection. Which format string correctly identifies the JDBC data source?", "choices": {"A": "`\"sqlite\"`", "B": "`\"jdbc\"`", "C": "`\"database\"`", "D": "`\"odbc\"`"}, "answer": "B", "short": "`\"jdbc\"`", "explanation": "This is the format string used with Spark's DataFrameReader to connect to any JDBC-compatible database (including SQLite, MySQL, PostgreSQL). It is specified as `.format(\"jdbc\")` in the DataFrameReader chain, followed by `.option()` calls for the connection URL, driver, and table name.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q002", "bank": "praticas", "n": 23, "domain": "data-ingestion-and-loading", "title": "Parquet Advantage Over CSV", "difficulty": "medium", "question": "What advantage does creating an external table using Parquet have over CSV in a `CREATE TABLE AS SELECT` statement?", "choices": {"A": "Parquet files are human-readable and can be edited with a text editor", "B": "Parquet files support row-level locking for concurrent writes", "C": "Parquet files have a well-defined schema", "D": "Parquet files are smaller because they use row-based compression"}, "answer": "C", "short": "Parquet files have a well-defined schema.", "explanation": "Unlike CSV (a schema-less text format requiring manual type inference), Parquet embeds column names and data types directly in the file metadata. This enables schema enforcement, efficient columnar reads, and predicate pushdown without a separate schema definition.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q003", "bank": "praticas", "n": 24, "domain": "data-ingestion-and-loading", "title": "COPY INTO Idempotency", "difficulty": "medium", "question": "Every day, a data engineer runs a command to transfer the previous day's sales data into a `transactions` table. Today, after running the command, the record count remains unchanged. Why were no new records copied?", "choices": {"A": "The table's schema rejected the incoming data due to a type mismatch", "B": "The transaction log was full and could not accept new entries", "C": "The COPY INTO command only works with streaming sources, not batch files", "D": "The previous day's file has already been copied into the table"}, "answer": "D", "short": "The previous day's file has already been copied into the table.", "explanation": "`COPY INTO` is idempotent — it maintains an internal record of which files have already been loaded. On subsequent runs, it automatically skips previously processed files, preventing duplicate ingestion. This makes it safe to rerun without creating duplicates.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q004", "bank": "praticas", "n": 25, "domain": "data-ingestion-and-loading", "title": "Spark Offset Tracking Methods", "difficulty": "easy", "question": "To reliably monitor the precise progress of processing and manage failures through restarting or reprocessing, which two methods does Spark use to log the offset range of the data processed in each trigger?", "choices": {"A": "Checkpointing and Write-ahead Logs (WAL)", "B": "Transaction logs and Delta Lake versioning", "C": "Spark event logs and executor heartbeats", "D": "Watermarking and session windows"}, "answer": "A", "short": "Checkpointing and Write-ahead Logs (WAL).", "explanation": "The checkpoint saves the streaming query's progress (including offsets) to a durable location in cloud storage, while the WAL records each trigger's offset range before the batch is processed. Together, they enable exactly-once semantics and recovery after cluster failure.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q005", "bank": "praticas", "n": 26, "domain": "data-ingestion-and-loading", "title": "Auto Loader Underlying Technology", "difficulty": "easy", "question": "Which tool does Auto Loader use to incrementally process data?", "choices": {"A": "Apache Kafka consumer groups", "B": "Spark Structured Streaming", "C": "COPY INTO with file tracking", "D": "Delta Lake Change Data Feed"}, "answer": "B", "short": "Spark Structured Streaming.", "explanation": "Auto Loader is built on top of Structured Streaming and uses it to incrementally discover and ingest new files as they arrive in cloud storage. It maintains a checkpoint to ensure exactly-once processing and scales automatically with file volume.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q006", "bank": "praticas", "n": 27, "domain": "data-ingestion-and-loading", "title": "Micro-Batch Trigger Every 5 Seconds", "difficulty": "medium", "question": "A data engineer sets up a Structured Streaming job to read from a table, process the data, and subsequently write it to a new table in real-time. The code block is shown below:\n\n```python\n(spark.table(\"sales\")\n  .withColumn(\"avg_price\", col(\"sales\") / col(\"units\"))\n  .writeStream\n  .option(\"checkpointLocation\", checkpointPath)\n  .outputMode(\"append\")\n  ._____\n  .table(\"new_sales\"))\n```\n\nIf the data engineer aims to run a micro-batch query that processes data every 5 seconds, which line of code should be used to complete the blank?", "choices": {"A": "`.trigger(interval=\"5 seconds\")`", "B": "`.trigger(continuous=\"5 seconds\")`", "C": "`.trigger(processingTime=\"5 seconds\")`", "D": "`.trigger(microBatch=\"5 seconds\")`"}, "answer": "C", "short": "`.trigger(processingTime=\"5 seconds\")`", "explanation": "This fixed-interval trigger causes Spark to kick off a new micro-batch every 5 seconds, processing all data that arrived since the last batch. If processing takes longer than the interval, the next batch starts immediately after completion.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q007", "bank": "praticas", "n": 28, "domain": "data-ingestion-and-loading", "title": "Auto Loader for New File Detection", "difficulty": "medium", "question": "A data engineer's source system produces files in a shared directory that accumulate over time. The engineer must recognize which files are new since the last pipeline execution and ingest only those during each run. Which tool addresses this?", "choices": {"A": "COPY INTO with manual file listing", "B": "Spark batch read with timestamp filtering", "C": "Delta Lake MERGE with file metadata", "D": "Auto Loader"}, "answer": "D", "short": "Auto Loader.", "explanation": "Auto Loader uses file notification (cloud storage events) or directory listing to detect new files incrementally. It maintains a checkpoint recording which files have been processed, so only unprocessed files are ingested on each pipeline run — without requiring manual file tracking.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q008", "bank": "praticas", "n": 29, "domain": "data-ingestion-and-loading", "title": "Writing to a Path vs a Table", "difficulty": "medium", "question": "What is wrong with the following code?\n\n```python\ndf = spark.read.json(\"data/\")\ndf.write.save(\"output\", format=\"delta\")\n```", "choices": {"A": "The code saves files to a path but does not register the output as a named Delta table in the metastore", "B": "The `spark.read.json()` method cannot be used with Delta format output", "C": "The `.save()` method requires a checkpoint location for Delta format writes", "D": "The code is missing a schema definition, which is required for JSON reads"}, "answer": "A", "short": "The code saves files to a path but does not register the output as a named Delta table in the metastore. To create a queryable Delta table accessible via SQL, use `.write.format(\"delta\").saveAsTable(\"table_name\")` instead.", "explanation": "> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q009", "bank": "praticas", "n": 30, "domain": "data-ingestion-and-loading", "title": "CREATE TABLE from CSV Keyword", "difficulty": "easy", "question": "A data engineer needs to create a table in Databricks using data from a CSV file. They run a `CREATE TABLE` command that already specifies the CSV path and format in the statement body. Which additional line of code completes the blank?", "choices": {"A": "`USING DELTA`", "B": "No additional line is needed", "C": "`FORMAT_OPTIONS('header' = 'true')`", "D": "`STORED AS TEXTFILE`"}, "answer": "B", "short": "No additional line is needed.", "explanation": "When a `CREATE TABLE` statement already contains `USING CSV LOCATION '/path/to/csv'`, the format and location are fully specified within the command body itself. No extra keyword is required to complete the statement.\n\n> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q010", "bank": "praticas", "n": 31, "domain": "data-ingestion-and-loading", "title": "Process All Available Data Trigger", "difficulty": "medium", "question": "A data engineer sets up a Structured Streaming job to read from a table and write results to a new table. The code block is shown below:\n\n```python\n(spark.table(\"transactions\")\n  .withColumn(\"total\", col(\"price\") * col(\"qty\"))\n  .writeStream\n  .option(\"checkpointLocation\", checkpointPath)\n  .outputMode(\"append\")\n  ._____\n  .table(\"transactions_gold\"))\n```\n\nIf the data engineer intends for the query to process all available data across as many batches as needed and then stop, which line of code should be used to complete the blank?", "choices": {"A": "`.trigger(once=True)`", "B": "`.trigger(processingTime=\"0 seconds\")`", "C": "`.trigger(availableNow=True)`", "D": "`.trigger(continuous=\"1 second\")`"}, "answer": "C", "short": "`.trigger(availableNow=True)`", "explanation": "This trigger processes all data that has arrived since the last checkpoint across one or more micro-batches, then shuts down automatically. It combines the efficiency of micro-batching (processing incrementally) with the convenience of a batch job (terminates when done).", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q011", "bank": "praticas", "n": 32, "domain": "data-ingestion-and-loading", "title": "Auto Loader JSON String Inference", "difficulty": "medium", "question": "A data engineer creates a pipeline to ingest JSON data via Auto Loader with no type inference or schema hints specified. After examining the data, all columns in the target table are of string type, even for fields containing only float or boolean values. Why does Auto Loader infer all columns as string type?", "choices": {"A": "Auto Loader defaults to string type to prevent data loss during schema evolution", "B": "The checkpoint metadata overrides column types to string for safety", "C": "The Delta table's schema enforcement converts all incoming types to strings", "D": "JSON data is a text-based format"}, "answer": "D", "short": "JSON data is a text-based format.", "explanation": "Without enabling schema inference (`cloudFiles.inferColumnTypes = true`), Auto Loader reads all JSON field values as strings by default. JSON itself does not enforce strict data types at the format level, so without explicit type hints, the safest default is to represent all values as strings.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q012", "bank": "praticas", "n": 33, "domain": "data-ingestion-and-loading", "title": "Auto Loader Compatible Workloads", "difficulty": "easy", "question": "What type of workloads are consistently compatible with Auto Loader?", "choices": {"A": "Both streaming and batch workloads", "B": "Only batch workloads with scheduled triggers", "C": "Only streaming workloads with continuous triggers", "D": "Only interactive notebook workloads"}, "answer": "A", "short": "Both streaming and batch workloads.", "explanation": "Auto Loader natively supports Structured Streaming for continuous incremental ingestion. It also supports triggered batch execution using `.trigger(availableNow=True)` to process all new files at once and then stop. This flexibility makes it suitable for both real-time and scheduled batch pipelines.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q013", "bank": "praticas", "n": 34, "domain": "data-ingestion-and-loading", "title": "spark.read to spark.readStream", "difficulty": "easy", "question": "A data engineer utilizes this code block within a batch ingestion pipeline to read from a Delta table:\n\n```python\ndf = (spark.read\n      .format(\"delta\")\n      .schema(schema)\n      .load(\"/delta/transactions\"))\n```\n\nWhat single change must be made for this code block to work correctly when the `transactions` table acts as a streaming source?", "choices": {"A": "Replace `.format(\"delta\")` with `.format(\"deltaStream\")`", "B": "Replace `spark.read` with `spark.readStream`", "C": "Add `.option(\"streaming\", \"true\")` to the reader chain", "D": "Replace `.load(\"/delta/transactions\")` with `.stream(\"/delta/transactions\")`"}, "answer": "B", "short": "Replace `spark.read` with `spark.readStream`.", "explanation": "This single change converts the static batch read into an incremental streaming read that consumes new records appended to the Delta table since the last checkpoint. All subsequent transformations on the resulting DataFrame remain unchanged.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q014", "bank": "praticas", "n": 35, "domain": "data-ingestion-and-loading", "title": "Streaming DataFrame Write API Error", "difficulty": "medium", "question": "Why will the following code fail?\n\n```python\ndf = spark.readStream.format(\"delta\").load(\"dbfs:/delta/events\")\ndf.write.csv(\"output\")\n```", "choices": {"A": "A checkpoint location must be specified before calling `.write`", "B": "The `.csv(\"output\")` method is not supported for Delta format reads", "C": "`df.write` must be `df.writeStream`", "D": "The `readStream` API cannot read from Delta format tables"}, "answer": "C", "short": "`df.write` must be `df.writeStream`.", "explanation": "A streaming DataFrame created with `readStream` must be written using the `writeStream` API. Using the batch `.write` API on a streaming DataFrame raises an `AnalysisException: Queries with streaming sources must be executed with writeStream.start()`.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q015", "bank": "praticas", "n": 36, "domain": "data-ingestion-and-loading", "title": "Missing Checkpoint in Streaming Write", "difficulty": "medium", "question": "What is missing from this streaming write?\n\n```python\ndf.writeStream.format(\"delta\").start(\"output\")\n```", "choices": {"A": "An output mode specification (append, complete, or update)", "B": "A schema definition for the output Delta table", "C": "A trigger interval for micro-batch processing", "D": "A checkpoint location is missing"}, "answer": "D", "short": "A checkpoint location is missing.", "explanation": "Structured Streaming requires `.option(\"checkpointLocation\", \"/path/to/checkpoint\")` to track query progress and enable fault-tolerance. Without a checkpoint, the query cannot recover from failures or track which data has been processed, and Spark will raise an error on startup.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q016", "bank": "praticas", "n": 37, "domain": "data-ingestion-and-loading", "title": "Ingesting a SaaS Source With Least Overhead *(2026 blueprint)*", "difficulty": "easy", "question": "Sales leadership wants Salesforce accounts and opportunities in Unity Catalog, refreshed hourly. The data team has no capacity to write or maintain custom API code. Which approach fits best?", "choices": {"A": "The Lakeflow Connect managed Salesforce connector with an hourly schedule", "B": "A notebook that calls the Salesforce REST API, scheduled hourly with Lakeflow Jobs", "C": "Auto Loader reading Salesforce export files from a volume", "D": "A JDBC read of the Salesforce database every hour"}, "answer": "A", "short": "The Lakeflow Connect managed Salesforce connector with an hourly schedule.", "explanation": "Managed connectors are fully managed ingestion pipelines for popular SaaS apps and databases. They run on serverless compute, write to UC streaming tables, ingest incrementally, and Lakeflow Connect creates a job for each schedule. Databricks recommends starting with the most managed layer. Custom REST code adds maintenance, and Auto Loader needs files that someone else would have to export ([Lakeflow Connect](https://docs.databricks.com/aws/en/ingestion/overview)).", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "02-data-ingestion-and-loading-q017", "bank": "praticas", "n": 38, "domain": "data-ingestion-and-loading", "title": "Components of a Managed Database Connector *(2026 blueprint)*", "difficulty": "medium", "question": "A team configures a Lakeflow Connect managed connector to replicate a SQL Server database with change data capture. Which component exists only for database connectors, and runs continuously to stage changes?", "choices": {"A": "The Unity Catalog connection", "B": "The ingestion gateway", "C": "The destination streaming tables", "D": "The Lakeflow Jobs schedule"}, "answer": "B", "short": "The ingestion gateway.", "explanation": "Database connectors include \"an ingestion gateway and staging storage to support continuous change capture\". The gateway runs as a continuous task in its own job. Every managed connector uses a UC **connection** (credentials), an **ingestion pipeline**, and **streaming tables** as destinations ([connector concepts](https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/)).", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "02-data-ingestion-and-loading-q018", "bank": "praticas", "n": 39, "domain": "data-ingestion-and-loading", "title": "Standard vs Managed Connectors *(2026 blueprint)*", "difficulty": "medium", "question": "Which source is a typical case for a Lakeflow Connect **standard** (customizable) connector rather than a managed connector?", "choices": {"A": "Workday reports for an HR dashboard", "B": "HubSpot CRM objects", "C": "Events from an Apache Kafka topic that need custom parsing in Structured Streaming", "D": "A MySQL database replicated with CDC"}, "answer": "C", "short": "Events from an Apache Kafka topic that need custom parsing in Structured Streaming.", "explanation": "Standard connectors are the customizable SQL and Spark ingestion paths for cloud object storage (Auto Loader, `read_files`), message buses (Kafka, Kinesis, Pub/Sub), and SFTP. Managed connectors cover SaaS apps (Workday, HubSpot, Salesforce) and databases (MySQL, PostgreSQL, SQL Server) with no ingestion code ([Ingest with SQL and Spark APIs](https://docs.databricks.com/aws/en/ingestion/)).", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "02-data-ingestion-and-loading-q019", "bank": "praticas", "n": 40, "domain": "data-ingestion-and-loading", "title": "Auto Loader Schema Evolution Without Failures *(2026 blueprint)*", "difficulty": "hard", "question": "An Auto Loader stream lands vendor JSON in a Bronze table whose schema downstream teams depend on. New fields occasionally appear. The stream must never stop because of them, the table schema must not change, and the unexpected values must be kept for review. Which setting meets this?", "choices": {"A": "`cloudFiles.schemaEvolutionMode = \"addNewColumns\"`", "B": "`cloudFiles.inferColumnTypes = \"true\"`", "C": "`cloudFiles.schemaEvolutionMode = \"failOnNewColumns\"`", "D": "`cloudFiles.schemaEvolutionMode = \"rescue\"`"}, "answer": "D", "short": "`cloudFiles.schemaEvolutionMode = \"rescue\"`.", "explanation": "In `rescue` mode the schema never evolves and the stream doesn't fail. New columns are written to the `_rescued_data` column. `addNewColumns` evolves the schema and stops the stream with `UnknownFieldException` until it's restarted. `failOnNewColumns` stops until someone fixes the schema. `inferColumnTypes` only affects type inference ([schema inference and evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)).", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q020", "bank": "praticas", "n": 41, "domain": "data-ingestion-and-loading", "title": "Auto Loader File Discovery Mode *(2026 blueprint)*", "difficulty": "medium", "question": "An Auto Loader stream reads a Unity Catalog external location that receives hundreds of thousands of files per day. Directory listing has become slow. What does Databricks recommend?", "choices": {"A": "Switch to file notification mode with file events enabled on the external location", "B": "Enable `cloudFiles.useIncrementalListing`", "C": "Reduce `cloudFiles.maxFilesPerTrigger` to 10", "D": "Replace Auto Loader with a scheduled `spark.read` of the whole directory"}, "answer": "A", "short": "Switch to file notification mode with file events enabled on the external location.", "explanation": "Directory listing is the default mode. Databricks recommends file notification mode with **file events** for most workloads, as it's more performant and scalable, and needs no extra permissions once file events are enabled on the external location (DBR 14.3 LTS+). `cloudFiles.useIncrementalListing` is deprecated. You can switch modes across restarts and keep exactly-once processing ([file detection modes](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-detection-modes)).", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q021", "bank": "praticas", "n": 42, "domain": "data-ingestion-and-loading", "title": "Forcing a COPY INTO Reload *(2026 blueprint)*", "difficulty": "medium", "question": "After fixing a parsing bug, a data engineer truncates a Bronze table and re-runs the same `COPY INTO` statement. Zero rows are loaded. What explains this, and how should they reload the files?", "choices": {"A": "`COPY INTO` caches query results. Run `REFRESH TABLE` first", "B": "`COPY INTO` is idempotent and skips files it already loaded. Add `COPY_OPTIONS ('force' = 'true')`", "C": "The files were deleted by `COPY INTO` after the first load. Re-upload them", "D": "`COPY INTO` only loads files newer than the table's last `OPTIMIZE`"}, "answer": "B", "short": "`COPY INTO` is idempotent and skips files it already loaded. Add `COPY_OPTIONS ('force' = 'true')`.", "explanation": "\"Files in the source location that have already been loaded are skipped\", and truncating the target doesn't reset that tracking. `'force' = 'true'` disables idempotency, so the files load again ([COPY INTO reference](https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into)).", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "02-data-ingestion-and-loading-q022", "bank": "praticas", "n": 43, "domain": "data-ingestion-and-loading", "title": "Parallelizing a JDBC Read *(2026 blueprint)*", "difficulty": "medium", "question": "A notebook reads a 300-million-row PostgreSQL table with `spark.read.format(\"jdbc\")`, and the read runs for hours while most cluster cores sit idle. What change parallelizes the read?", "choices": {"A": "Set `fetchSize` to 1", "B": "Call `.repartition(64)` after `.load()`", "C": "Add `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` on an indexed numeric column", "D": "Increase `spark.sql.shuffle.partitions`"}, "answer": "C", "short": "Add `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` on an indexed numeric column.", "explanation": "A JDBC read uses one thread by default. The partitioning options split the read into parallel range queries. Repartitioning after `load()` only redistributes data that was already read serially. Shuffle partitions don't affect the read ([Query databases using JDBC](https://docs.databricks.com/aws/en/connect/external-systems/jdbc)).", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q023", "bank": "praticas", "n": 44, "domain": "data-ingestion-and-loading", "title": "Landing REST API Data *(2026 blueprint)*", "difficulty": "medium", "question": "A vendor exposes order data only through a REST API. The team wants an immutable raw copy for replay, schema-drift handling, and a nightly schedule. Which design fits?", "choices": {"A": "Store the API token in the notebook and write directly to DBFS root", "B": "Call the API from a notebook and `collect()` the results into a pandas DataFrame on the driver", "C": "Create a Lakehouse Federation connection that queries the REST API in place", "D": "Call the API from a notebook, write the raw JSON responses to a Unity Catalog volume, ingest them with Auto Loader, and schedule both tasks in one Lakeflow Job"}, "answer": "D", "short": "Call the API from a notebook, write the raw JSON responses to a Unity Catalog volume, ingest them with Auto Loader, and schedule both tasks in one Lakeflow Job.", "explanation": "Landing raw files in a governed volume keeps a replayable copy, and Auto Loader handles incremental loading and schema evolution. Lakeflow Jobs schedules and retries the tasks. The token belongs in Databricks secrets (`dbutils.secrets.get`). DBFS root is deprecated for data ([What is DBFS?](https://docs.databricks.com/aws/en/dbfs/)).", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "02-data-ingestion-and-loading-q024", "bank": "praticas", "n": 45, "domain": "data-ingestion-and-loading", "title": "Querying Nested JSON Strings *(2026 blueprint)*", "difficulty": "easy", "question": "A Bronze column `raw` holds JSON strings such as `{\"customer\": {\"id\": 42}, \"total\": \"19.99\"}`. Which Databricks SQL expression returns the customer ID?", "choices": {"A": "`raw:customer.id`", "B": "`raw.customer.id`", "C": "`get_json(raw, 'customer', 'id')`", "D": "`raw['customer']['id']::json`"}, "answer": "A", "short": "`raw:customer.id`.", "explanation": "For JSON **strings**, Databricks SQL uses `<column>:<path>`, with dot notation or brackets for nested fields and `::` for casting (for example `raw:total::double`). Dot notation without the colon works on **struct** columns, not on strings ([Query JSON strings](https://docs.databricks.com/aws/en/semi-structured/json)). For new semi-structured data, Databricks recommends the `VARIANT` type over JSON strings.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "03-data-transformation-and-modeling-q001", "bank": "praticas", "n": 46, "domain": "data-transformation-and-modeling", "title": "DELETE Syntax", "difficulty": "easy", "question": "Which code block will delete rows from the Delta table `my_table` where the `age` column value exceeds 25?", "choices": {"A": "`REMOVE FROM my_table WHERE age > 25;`", "B": "`DELETE FROM my_table WHERE age > 25;`", "C": "`DROP ROWS FROM my_table WHERE age > 25;`", "D": "`TRUNCATE my_table WHERE age > 25;`"}, "answer": "B", "short": "`DELETE FROM my_table WHERE age > 25;`", "explanation": "This standard SQL DML syntax works directly on Delta tables. Delta Lake supports full DML operations including DELETE, UPDATE, and MERGE with ACID guarantees, so the deleted rows are tracked in the transaction log and are recoverable via time travel.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": "01-databricks-intelligence-platform/04-delta-lake-fundamentals"}, {"id": "03-data-transformation-and-modeling-q002", "bank": "praticas", "n": 47, "domain": "data-transformation-and-modeling", "title": "PySpark Table Access", "difficulty": "easy", "question": "A data analyst has developed a Delta table `sales` that the entire data analysis team uses. The data engineering team prefers Python. Which command can the engineering team use to access `sales` data in PySpark?", "choices": {"A": "`spark.read.delta(\"sales\")`", "B": "`spark.load(\"sales\")`", "C": "`spark.table(\"sales\")`", "D": "`spark.sql.table(\"sales\")`"}, "answer": "C", "short": "`spark.table(\"sales\")`", "explanation": "This loads the registered Delta table into a PySpark DataFrame, allowing the engineering team to use Python and Spark transformations on the same data the analyst queries with SQL. The table is accessible because it is registered in the shared metastore.", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": null}, {"id": "03-data-transformation-and-modeling-q003", "bank": "praticas", "n": 48, "domain": "data-transformation-and-modeling", "title": "Indicating PII in Table Metadata", "difficulty": "medium", "question": "A data engineer intends to create a new table listing customers residing in France and wants to indicate the table contains PII. The incomplete SQL is shown below:\n\n```sql\nCREATE TABLE customerInFrance\n_____ AS\nSELECT id\n      ,firstName\n      ,lastName\nFROM customerLocations\nWHERE country = 'FRANCE';\n```\n\nWhich line of code correctly fills in the blank to add a table property indicating PII?", "choices": {"A": "`METADATA ('contains_pii' = 'true')`", "B": "`COMMENT 'contains_pii = true'`", "C": "`OPTIONS ('contains_pii' = 'true')`", "D": "`TBLPROPERTIES ('contains_pii' = 'true')`"}, "answer": "D", "short": "`TBLPROPERTIES ('contains_pii' = 'true')`", "explanation": "`TBLPROPERTIES` adds structured key-value metadata directly to the table definition — these are the actual \"table properties\" in Databricks SQL. `COMMENT` adds a human-readable description but is not a table property. Using `TBLPROPERTIES` to tag sensitivity classifications (e.g., PII, data classification) is the standard approach for policy-driven metadata in Databricks.", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": "07-governance-and-security/04-row-filters-column-masks-abac"}, {"id": "03-data-transformation-and-modeling-q004", "bank": "praticas", "n": 49, "domain": "data-transformation-and-modeling", "title": "Array Functions for Nested JSON", "difficulty": "easy", "question": "What benefits do the array functions from Spark SQL offer?", "choices": {"A": "The ability to work with complex, nested data ingested from JSON files", "B": "The ability to convert JSON files into Parquet format without code", "C": "The ability to enforce strict schemas on semi-structured data at write time", "D": "The ability to automatically flatten all nested structures into separate tables"}, "answer": "A", "short": "The ability to work with complex, nested data ingested from JSON files.", "explanation": "Functions like `explode`, `array_contains`, `transform`, and `filter` allow operations directly on nested array structures without flattening the entire schema first, making them essential for processing hierarchical JSON data at scale.", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "03-data-transformation-and-modeling-q005", "bank": "praticas", "n": 50, "domain": "data-transformation-and-modeling", "title": "MERGE to Prevent Duplicates", "difficulty": "easy", "question": "What commands can be utilized to insert data into a Delta table while preventing duplicate records?", "choices": {"A": "`INSERT DISTINCT`", "B": "`MERGE`", "C": "`COPY INTO`", "D": "`UPSERT`"}, "answer": "B", "short": "`MERGE`.", "explanation": "The `MERGE INTO` statement matches source records against a target table on a key condition and conditionally inserts, updates, or skips records. This is the standard upsert pattern in Delta Lake for ensuring no duplicate rows are added.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q006", "bank": "praticas", "n": 51, "domain": "data-transformation-and-modeling", "title": "UNION for Unique Records", "difficulty": "medium", "question": "A data engineering team maintains `march_transactions` (all March retail transactions) and `april_transactions` (all April retail transactions) with no overlapping records. What command creates a new table `all_transactions` containing all unique records from both?", "choices": {"A": "`CREATE TABLE all_transactions AS SELECT * FROM march_transactions INTERSECT SELECT * FROM april_transactions;`", "B": "`CREATE TABLE all_transactions AS SELECT * FROM march_transactions UNION ALL SELECT * FROM april_transactions;`", "C": "`CREATE TABLE all_transactions AS SELECT * FROM march_transactions UNION SELECT * FROM april_transactions;`", "D": "`CREATE TABLE all_transactions AS SELECT * FROM march_transactions JOIN april_transactions;`"}, "answer": "C", "short": "```sql\nCREATE TABLE all_transactions AS\nSELECT * FROM march_transactions\nUNION\nSELECT * FROM april_transactions;\n```", "explanation": "`UNION` (without `ALL`) removes duplicate rows across the combined result. Since the two tables share no overlapping records, all rows from both tables are included exactly once in the output.", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "03-data-transformation-and-modeling-q007", "bank": "praticas", "n": 52, "domain": "data-transformation-and-modeling", "title": "Python Multi-Condition Control Flow", "difficulty": "medium", "question": "A data engineer intends to run the last block of a Python program only if `day_of_week` is set to 1 and `review_period` is `True`. The incomplete code block is shown below:\n\n```python\nday_of_week = get_day_of_week()\nreview_period = check_review_period()\n\n_____\n    run_final_block()\n```\n\nWhat control flow statement should be used to complete the blank?", "choices": {"A": "`if day_of_week is 1 and review_period is True:`", "B": "`if day_of_week = 1 and review_period == \"True\":`", "C": "`if day_of_week == 1 or review_period:`", "D": "`if day_of_week == 1 and review_period:`"}, "answer": "D", "short": "`if day_of_week == 1 and review_period:`", "explanation": "In Python, `==` performs equality comparison (not assignment). A boolean variable is truthy when referenced directly — wrapping it in quotes (`\"True\"`) would compare against the string literal, not the boolean value. Using a single `=` would cause a `SyntaxError`.", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": null}, {"id": "03-data-transformation-and-modeling-q008", "bank": "praticas", "n": 53, "domain": "data-transformation-and-modeling", "title": "Persistent Cross-Session Data Entity", "difficulty": "medium", "question": "A data engineer needs a data entity built from several tables that must be accessible to other data engineers in their sessions and stored in a physical location. Which data entity should be created?", "choices": {"A": "A table (Delta or Spark SQL table)", "B": "A temporary view", "C": "A global temporary view", "D": "A Common Table Expression (CTE)"}, "answer": "A", "short": "A table (Delta or Spark SQL table).", "explanation": "Tables persist data physically at a storage location and are registered in the metastore, making them accessible across all sessions and users. Unlike temporary views (session-scoped) or views (no physical storage), tables outlive any individual session.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "03-data-transformation-and-modeling-q009", "bank": "praticas", "n": 54, "domain": "data-transformation-and-modeling", "title": "INSERT INTO a Delta Table", "difficulty": "easy", "question": "A data engineer needs to add a new record `('a1', 6, 9.4)` to the existing Delta table `my_table`. Which SQL command accomplishes this?", "choices": {"A": "`ADD ROW my_table VALUES ('a1', 6, 9.4);`", "B": "`INSERT INTO my_table VALUES ('a1', 6, 9.4);`", "C": "`APPEND INTO my_table VALUES ('a1', 6, 9.4);`", "D": "`MERGE INTO my_table VALUES ('a1', 6, 9.4);`"}, "answer": "B", "short": "`INSERT INTO my_table VALUES ('a1', 6, 9.4);`", "explanation": "`INSERT INTO ... VALUES` appends new rows to an existing Delta table without modifying existing records. Delta Lake records this as a new transaction in the log, making it reversible via time travel.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q010", "bank": "praticas", "n": 55, "domain": "data-transformation-and-modeling", "title": "CREATE OR REPLACE TABLE", "difficulty": "easy", "question": "A data architect needs to create an empty Delta table in a specified format, regardless of whether a table with that name already exists. Which SQL DDL approach accomplishes this?", "choices": {"A": "`DROP TABLE IF EXISTS table_name; CREATE TABLE table_name (...)`", "B": "`CREATE TABLE IF NOT EXISTS table_name (...)`", "C": "`CREATE OR REPLACE TABLE table_name (...column definitions...)`", "D": "`ALTER TABLE table_name REPLACE COLUMNS (...)`"}, "answer": "C", "short": "`CREATE OR REPLACE TABLE table_name (...column definitions...)`", "explanation": "This atomically drops and recreates the table if it exists, or creates it new if it does not. It avoids errors from pre-existing tables and ensures the table always reflects the latest schema definition.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "03-data-transformation-and-modeling-q011", "bank": "praticas", "n": 56, "domain": "data-transformation-and-modeling", "title": "PIVOT for Wide Format", "difficulty": "easy", "question": "Which SQL keyword can transform a table from long format to wide format?", "choices": {"A": "`UNPIVOT`", "B": "`LATERAL VIEW`", "C": "`TRANSPOSE`", "D": "`PIVOT`"}, "answer": "D", "short": "`PIVOT`.", "explanation": "The `PIVOT` clause rotates distinct row values into column headers, converting a tall/long table (one row per category) into a wide/crosstab format (one column per category). This is commonly used to reshape metrics data for reporting dashboards.", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "03-data-transformation-and-modeling-q012", "bank": "praticas", "n": 57, "domain": "data-transformation-and-modeling", "title": "Temporary View for Single-Session Use", "difficulty": "medium", "question": "A data engineer needs a relational object from two tables that will not be used by other engineers in different sessions. To minimize storage expenses, physical data should not be duplicated. Which relational object should be created?", "choices": {"A": "A temporary view", "B": "A managed Delta table", "C": "An external table", "D": "A materialized view"}, "answer": "A", "short": "A temporary view.", "explanation": "Temporary views exist only for the current Spark session, are not accessible to other users, and store no physical data — they are just a named query definition. This avoids both storage costs and data duplication while enabling SQL-based access within the session.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "03-data-transformation-and-modeling-q013", "bank": "praticas", "n": 58, "domain": "data-transformation-and-modeling", "title": "PySpark SQL Query Execution", "difficulty": "easy", "question": "A data analyst has created a query that operates on a Delta table. They seek assistance from the data engineering team to perform a set of tests to verify that the data returned by the query is accurate and clean. However, the data engineering team utilizes Python for their tests instead of SQL. Which operations can the data engineering team use in PySpark to execute the query and process the results?", "choices": {"A": "`spark.query(\"SELECT ...\")`", "B": "`spark.sql(\"SELECT ...\")`", "C": "`spark.execute(\"SELECT ...\")`", "D": "`spark.run(\"SELECT ...\")`"}, "answer": "B", "short": "`spark.sql(\"SELECT ...\")`", "explanation": "`spark.sql()` accepts a SQL query string and executes it, returning the results as a PySpark DataFrame. `spark.table(\"table_name\")` loads an entire table as a DataFrame but does not execute a specific SQL query — it is not the correct tool when the goal is to run a particular SQL statement.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "03-data-transformation-and-modeling-q014", "bank": "praticas", "n": 59, "domain": "data-transformation-and-modeling", "title": "count_if for NULL Values", "difficulty": "medium", "question": "Which command shows the count of null values in the `member_id` column?", "choices": {"A": "`SELECT count(member_id) FROM my_table WHERE member_id IS NULL;`", "B": "`SELECT sum(CASE WHEN member_id IS NULL THEN 0 ELSE 1 END) FROM my_table;`", "C": "`SELECT count_if(member_id IS NULL) FROM my_table;`", "D": "`SELECT count(NULL) FROM my_table;`"}, "answer": "C", "short": "`SELECT count_if(member_id IS NULL) FROM my_table;`", "explanation": "`count_if` counts rows that satisfy the given boolean condition. `IS NULL` evaluates to true for null values. Standard `count(member_id)` would exclude nulls, returning the opposite of what is needed.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q015", "bank": "praticas", "n": 60, "domain": "data-transformation-and-modeling", "title": "FILTER Higher-Order Function", "difficulty": "medium", "question": "A data engineer needs to implement custom logic for the `employees` array column in the `stores` table to find employees with more than 5 years of experience. The result should be a new column `exp_employees` containing only matching employees for each row. The incomplete SQL query is shown below:\n\n```sql\nSELECT store_id,\n       _____ AS exp_employees\nFROM stores\n```\n\nWhich code correctly completes the blank using the FILTER higher-order function?", "choices": {"A": "`TRANSFORM(employees, i -> i.years_exp > 5)`", "B": "`ARRAY_FILTER(employees, i -> i.years_exp > 5)`", "C": "`SELECT_FROM_ARRAY(employees, years_exp > 5)`", "D": "`FILTER(employees, i -> i.years_exp > 5)`"}, "answer": "D", "short": "`FILTER(employees, i -> i.years_exp > 5)`", "explanation": "The `FILTER` higher-order function applies a lambda predicate to each element of an array column, returning a new array containing only elements where the condition is true. The arrow syntax (`->`) defines the anonymous function.", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "03-data-transformation-and-modeling-q016", "bank": "praticas", "n": 61, "domain": "data-transformation-and-modeling", "title": "Python Variable in SQL Query", "difficulty": "easy", "question": "A data engineer has a Python variable `table_name` and wants to execute a SQL query using it in PySpark. The incomplete code block is shown below:\n\n```python\ntable_name = \"sales\"\nresult = _____(f\"SELECT * FROM {table_name}\")\n```\n\nWhich method completes the blank?", "choices": {"A": "`spark.sql`", "B": "`spark.read`", "C": "`spark.query`", "D": "`spark.execute`"}, "answer": "A", "short": "`spark.sql(f\"SELECT * FROM {table_name}\")`", "explanation": "`spark.sql()` accepts a SQL string, and Python f-strings embed variables directly into the query using `{variable_name}` syntax. This is the standard way to dynamically reference table names or other values from Python variables in SQL queries.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "03-data-transformation-and-modeling-q017", "bank": "praticas", "n": 62, "domain": "data-transformation-and-modeling", "title": "Python Function Definition", "difficulty": "easy", "question": "A data engineer new to Python needs a function that adds two integers and returns their sum. Which code block is correct?", "choices": {"A": "`function add_integers(x, y): return x + y`", "B": "`def add_integers(x, y): return x + y`", "C": "`def add_integers(x, y): yield x + y`", "D": "`def add_integers(x, y): print(x + y)`"}, "answer": "B", "short": "```python\ndef add_integers(x, y):\n    return x + y\n```", "explanation": "In Python, `def` defines a function and `return` outputs the result. Using `print` instead of `return` would output to the console but the function would return `None`, making it unusable in further computation. Using `function` (JavaScript syntax) would cause a `SyntaxError`.", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": null}, {"id": "03-data-transformation-and-modeling-q018", "bank": "praticas", "n": 63, "domain": "data-transformation-and-modeling", "title": "MERGE INTO vs INSERT INTO", "difficulty": "medium", "question": "When should a data engineer prefer the `MERGE INTO` command over the `INSERT INTO` command?", "choices": {"A": "When the target table needs to be completely overwritten with new data", "B": "When inserting data from a streaming source into a batch table", "C": "When the target table cannot contain duplicate records", "D": "When the source and target tables have different schemas"}, "answer": "C", "short": "When the target table cannot contain duplicate records.", "explanation": "`MERGE INTO` matches source records against existing rows on a key condition and conditionally inserts, updates, or skips records. `INSERT INTO` always appends all rows regardless of existing data, which would create duplicates if records already exist.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q019", "bank": "praticas", "n": 64, "domain": "data-transformation-and-modeling", "title": "GROUP BY Ordinal Referencing an Aggregate", "difficulty": "medium", "question": "What is wrong with the following SQL query?\n\n```sql\nSELECT name, count(*) FROM people GROUP BY 2\n```", "choices": {"A": "The `count(*)` function requires an alias to be used with `GROUP BY`", "B": "The query is missing a `HAVING` clause to filter the aggregated results", "C": "`GROUP BY` using a numeric ordinal position is never valid in Spark SQL", "D": "`GROUP BY 2` refers to `count(*)`, an aggregate expression, which can't be a grouping key"}, "answer": "D", "short": "`GROUP BY 2` refers to `count(*)`, an aggregate expression, which can't be a grouping key.", "explanation": "Databricks SQL does allow grouping by column position (for example `GROUP BY 1` here would group by `name`). But \"if a positional reference resolves to an aggregate expression, Databricks raises GROUP_BY_POS_AGGREGATE\". Use `GROUP BY 1` or `GROUP BY name` ([GROUP BY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-groupby)).", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "03-data-transformation-and-modeling-q020", "bank": "praticas", "n": 65, "domain": "data-transformation-and-modeling", "title": "Tool for Automated Data Quality Monitoring", "difficulty": "easy", "question": "During data ingestion, a data engineer observes that source data quality is declining. They want to automate the process of monitoring the quality level. Which tool addresses this?", "choices": {"A": "Lakeflow Declarative Pipelines (formerly DLT)", "B": "Databricks SQL Alerts with scheduled queries", "C": "Apache Airflow with custom validation DAGs", "D": "Great Expectations library integrated with Spark"}, "answer": "A", "short": "Lakeflow Declarative Pipelines (formerly DLT).", "explanation": "Lakeflow Declarative Pipelines provides built-in data quality monitoring through expectations — declarative constraints that automatically track pass/fail metrics, record violations in the event log, and optionally drop or quarantine bad records. Quality statistics are visible per-table in the pipeline UI.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q021", "bank": "praticas", "n": 66, "domain": "data-transformation-and-modeling", "title": "Lakeflow Declarative Pipelines Continuous Pipeline Behavior", "difficulty": "hard", "question": "A Lakeflow Declarative Pipelines pipeline has two streaming tables and three materialized views. It runs in Production mode with Continuous Pipeline Mode. What outcome should be expected after clicking Start if there is unprocessed data and all definitions are correct?", "choices": {"A": "Only the two streaming datasets are updated continuously; the three materialized views are updated once and then stop", "B": "All datasets are updated at set intervals until the pipeline is shut down. Compute resources are deployed for the update and terminated when the pipeline is stopped", "C": "All five datasets are updated once, and then the pipeline shuts down automatically to conserve resources", "D": "The pipeline fails because streaming and materialized view datasets cannot coexist in Continuous mode"}, "answer": "B", "short": "All datasets are updated at set intervals until the pipeline is shut down. Compute resources are deployed for the update and terminated when the pipeline is stopped.", "explanation": "In Continuous mode, the pipeline runs indefinitely — processing streaming tables as new data arrives and periodically refreshing materialized views. It does not shut down automatically; resources are released only when the pipeline is manually stopped.", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "03-data-transformation-and-modeling-q022", "bank": "praticas", "n": 67, "domain": "data-transformation-and-modeling", "title": "Lakeflow Declarative Pipelines DROP Expectation Behavior", "difficulty": "medium", "question": "A dataset established through Lakeflow Declarative Pipelines has an expectations clause with `ON VIOLATION DROP ROW`. What should occur when processing a batch of data that includes entries violating these constraints?", "choices": {"A": "Violating records are written to a separate quarantine table for manual review", "B": "The entire batch is rejected and the pipeline enters a failed state", "C": "Records that violate the expectation are dropped from the target dataset and recorded as invalid in the event log", "D": "The pipeline pauses and waits for manual approval before continuing"}, "answer": "C", "short": "Records that violate the expectation are dropped from the target dataset and recorded as invalid in the event log.", "explanation": "The pipeline continues running. Dropped record counts and violation metrics are tracked in the Lakeflow Declarative Pipelines event log and displayed per-table in the pipeline UI under data quality statistics. The `FAIL UPDATE` variant would stop the pipeline instead.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q023", "bank": "praticas", "n": 68, "domain": "data-transformation-and-modeling", "title": "CREATE STREAMING TABLE vs CREATE MATERIALIZED VIEW", "difficulty": "medium", "question": "In a Lakeflow Declarative Pipelines SQL definition, when should `CREATE OR REFRESH STREAMING TABLE` be used instead of `CREATE OR REFRESH MATERIALIZED VIEW`?", "choices": {"A": "When the table needs to support both read and write operations simultaneously", "B": "When the table must be accessible from multiple workspaces", "C": "When the table requires ACID transaction support", "D": "When data needs to be processed incrementally"}, "answer": "D", "short": "When data needs to be processed incrementally.", "explanation": "A streaming table reads append-oriented sources (Auto Loader, Kafka, `STREAM(...)` of another table) and processes only records that arrived since the last update. A materialized view stores a query result and refreshes it, incrementally when possible, otherwise by recomputing. Legacy syntax used `CREATE STREAMING LIVE TABLE` (now a streaming table) and `CREATE LIVE TABLE` (now a materialized view).", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "03-data-transformation-and-modeling-q024", "bank": "praticas", "n": 69, "domain": "data-transformation-and-modeling", "title": "Silver to Gold Streaming Query", "difficulty": "medium", "question": "Which type of Structured Streaming query represents the transition from a Silver table to a Gold table?", "choices": {"A": "A query that reads from a Silver streaming table and applies aggregations — such as `groupBy()` with `sum()`, `count()`, or `avg()` — to produce summary metrics written to a Gold table", "B": "A query that deduplicates and cleanses Bronze data before writing to a Silver table", "C": "A query that reads raw data from cloud storage and applies schema enforcement before writing to a Silver table", "D": "A query that replicates Silver data to an external data warehouse for reporting"}, "answer": "A", "short": "A query that reads from a Silver streaming table and applies aggregations — such as `groupBy()` with `sum()`, `count()`, or `avg()` — to produce summary metrics written to a Gold table.", "explanation": "Gold tables typically contain business-level aggregates. Transforming cleaned Silver data into aggregated Gold data is the defining characteristic of the Silver-to-Gold transition in medallion architecture.\n\n> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": "01-databricks-intelligence-platform/01-lakehouse-architecture"}, {"id": "03-data-transformation-and-modeling-q025", "bank": "praticas", "n": 70, "domain": "data-transformation-and-modeling", "title": "Identifying Which Lakeflow Declarative Pipelines Table Drops Records", "difficulty": "medium", "question": "A data engineer manages three tables in a Lakeflow Declarative Pipelines pipeline with expectations set to eliminate invalid records. They observe that data is being discarded at some stage. How can they identify which specific table is dropping the records?", "choices": {"A": "Query the Delta transaction log of each table to find DELETE operations", "B": "Navigate to the Lakeflow Declarative Pipelines pipeline page, click on each table, and view the data quality statistics", "C": "Run DESCRIBE HISTORY on each table to check for dropped record counts", "D": "Add explicit logging statements to each table's transformation code"}, "answer": "B", "short": "Navigate to the Lakeflow Declarative Pipelines pipeline page, click on each table, and view the data quality statistics.", "explanation": "The Lakeflow Declarative Pipelines pipeline UI shows per-table expectation metrics, including the number of records that passed, failed, or were dropped for each defined constraint. This makes it straightforward to pinpoint which table's expectation is causing record drops.", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "03-data-transformation-and-modeling-q026", "bank": "praticas", "n": 71, "domain": "data-transformation-and-modeling", "title": "Lakeflow Declarative Pipelines Pipeline Minimum Requirement", "difficulty": "easy", "question": "What needs to be specified when creating a new Lakeflow Declarative Pipelines pipeline?", "choices": {"A": "A target database and storage location", "B": "A cluster policy and node type configuration", "C": "At least one source code file or notebook that defines the datasets", "D": "An explicit schedule or cron expression"}, "answer": "C", "short": "At least one source code file or notebook that defines the datasets.", "explanation": "A pipeline must reference source code (notebooks or files) containing the dataset definitions, such as `CREATE OR REFRESH STREAMING TABLE` / `CREATE OR REFRESH MATERIALIZED VIEW` statements or `@dp.table` / `@dp.materialized_view` functions. Other settings — storage location, target database, cluster configuration — are optional and can use defaults.", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "03-data-transformation-and-modeling-q027", "bank": "praticas", "n": 72, "domain": "data-transformation-and-modeling", "title": "STREAM() Function in Lakeflow Declarative Pipelines", "difficulty": "medium", "question": "A data engineer joins an ongoing project and notices a `STREAM()` function wrapping a table reference in a Lakeflow Declarative Pipelines SQL query. What explains its inclusion?", "choices": {"A": "The `STREAM()` function applies watermarking to handle late-arriving data", "B": "The `STREAM()` function enables parallel reads from the table across multiple clusters", "C": "It converts a batch table into a temporary streaming source for the current query only", "D": "The referenced dataset is read as a streaming source (for example, a streaming table)"}, "answer": "D", "short": "The referenced dataset is read as a streaming source (for example, a streaming table).", "explanation": "In Lakeflow Declarative Pipelines, `STREAM(table_name)` indicates that the table should be read as a streaming source — consuming only new records incrementally rather than reprocessing the full table. It is required when the source is a streaming table and the consuming dataset needs to process it incrementally.", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "03-data-transformation-and-modeling-q028", "bank": "praticas", "n": 73, "domain": "data-transformation-and-modeling", "title": "Lakeflow Declarative Pipelines Migration Changes", "difficulty": "medium", "question": "A data engineer (Python, bronze/silver) and a data analyst (SQL, gold) collaborate on a medallion pipeline with a streaming source. They plan to migrate to Lakeflow Declarative Pipelines. What changes are necessary?", "choices": {"A": "No changes are required", "B": "The SQL code must be rewritten in Python because Lakeflow Declarative Pipelines only supports Python definitions", "C": "The streaming source must be converted to a batch source before migrating to Lakeflow Declarative Pipelines", "D": "The Python code must be rewritten in SQL because Lakeflow Declarative Pipelines only supports SQL definitions"}, "answer": "A", "short": "No changes are required.", "explanation": "Lakeflow Declarative Pipelines natively supports both Python and SQL within the same pipeline. It supports the medallion architecture (Bronze/Silver/Gold layers) and handles streaming sources directly. The existing language mix and multi-hop architecture can migrate to Lakeflow Declarative Pipelines without modification to the underlying logic.", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "03-data-transformation-and-modeling-q029", "bank": "praticas", "n": 74, "domain": "data-transformation-and-modeling", "title": "Persist to Memory and Disk", "difficulty": "medium", "question": "Which Spark method persists data to both memory and disk when memory is insufficient?", "choices": {"A": "`cache()` with `StorageLevel.MEMORY_ONLY`", "B": "`persist()` with `StorageLevel.MEMORY_AND_DISK`", "C": "`checkpoint()` with eager evaluation", "D": "`broadcast()` with local storage fallback"}, "answer": "B", "short": "`persist()` with `StorageLevel.MEMORY_AND_DISK`.", "explanation": "`persist()` allows specifying a `StorageLevel` such as `MEMORY_AND_DISK`, which stores partitions in memory and spills excess to disk when memory is exhausted. `cache()` is a shortcut for `persist(StorageLevel.MEMORY_ONLY)` and does not spill to disk automatically.", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables"}, {"id": "03-data-transformation-and-modeling-q030", "bank": "praticas", "n": 75, "domain": "data-transformation-and-modeling", "title": "Broadcast Join for a Small Dimension *(2026 blueprint)*", "difficulty": "medium", "question": "A 2 TB `sales` DataFrame is joined to a 15 MB `stores` DataFrame on `store_id`. The Spark UI shows a `SortMergeJoin` with a large shuffle of `sales`. Which change avoids shuffling the large side?", "choices": {"A": "`sales.repartition(1).join(stores, \"store_id\")`", "B": "`sales.crossJoin(stores).filter(\"sales.store_id = stores.store_id\")`", "C": "`sales.join(broadcast(stores), \"store_id\")`", "D": "Lower `spark.sql.shuffle.partitions` to 10"}, "answer": "C", "short": "`sales.join(broadcast(stores), \"store_id\")`.", "explanation": "`broadcast()` marks the small DataFrame for a broadcast join, which copies it to every executor so `sales` isn't shuffled. Its size (15 MB) is above the default `spark.sql.autoBroadcastJoinThreshold` of 10 MB, which is why Spark didn't broadcast it automatically. A cross join multiplies rows. One partition removes parallelism. Fewer shuffle partitions don't remove the shuffle ([SQL performance tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html)).", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "03-data-transformation-and-modeling-q031", "bank": "praticas", "n": 76, "domain": "data-transformation-and-modeling", "title": "union vs unionByName *(2026 blueprint)*", "difficulty": "medium", "question": "Two DataFrames hold the same columns in a different order: `df_a(id, name, city)` and `df_b(city, id, name)`. Which call combines them, keeping duplicate rows and matching columns correctly?", "choices": {"A": "`df_a.union(df_b)`", "B": "`df_a.join(df_b, \"id\", \"outer\")`", "C": "`df_a.union(df_b).distinct()`", "D": "`df_a.unionByName(df_b)`"}, "answer": "D", "short": "`df_a.unionByName(df_b)`.", "explanation": "`union` resolves columns **by position**, so it would put `city` values into `id`. `unionByName` resolves them **by name**. Both keep duplicates, which is SQL `UNION ALL` semantics. Add `.distinct()` for SQL `UNION` behaviour. `allowMissingColumns=True` fills columns missing from one side with nulls ([PySpark unionByName](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unionByName.html)).", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "03-data-transformation-and-modeling-q032", "bank": "praticas", "n": 77, "domain": "data-transformation-and-modeling", "title": "Splitting and Exploding Columns *(2026 blueprint)*", "difficulty": "medium", "question": "A Silver table has a `tags` string column such as `\"red,large,sale\"`. Analysts need one row per tag. Which PySpark expression produces it?", "choices": {"A": "`df.withColumn(\"tag\", F.explode(F.split(\"tags\", \",\")))`", "B": "`df.withColumn(\"tag\", F.split(\"tags\", \",\"))`", "C": "`df.withColumn(\"tag\", F.flatten(\"tags\"))`", "D": "`df.groupBy(\"tags\").agg(F.collect_list(\"tags\"))`"}, "answer": "A", "short": "`df.withColumn(\"tag\", F.explode(F.split(\"tags\", \",\")))`.", "explanation": "`split` turns the string into an array using a (regular expression) pattern. `explode` then emits one row per array element. `split` alone leaves one row with an array. `flatten` works on arrays of arrays, and `collect_list` does the opposite of what's needed ([PySpark split](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.functions.split.html)).", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "03-data-transformation-and-modeling-q033", "bank": "praticas", "n": 78, "domain": "data-transformation-and-modeling", "title": "Fast Distinct Counts on Huge Tables *(2026 blueprint)*", "difficulty": "easy", "question": "A dashboard shows the number of distinct visitors per day over billions of events. An exact `COUNT(DISTINCT visitor_id)` is too slow, and a small error is acceptable. Which function fits?", "choices": {"A": "`count_if(visitor_id IS NOT NULL)`", "B": "`approx_count_distinct(visitor_id)`", "C": "`sum(DISTINCT visitor_id)`", "D": "`collect_set(visitor_id)`"}, "answer": "B", "short": "`approx_count_distinct(visitor_id)`.", "explanation": "`approx_count_distinct` estimates the number of distinct values with HyperLogLog++. Its default maximum relative standard deviation is 5 %, and the `relativeSD` argument can tighten it. `collect_set` would build huge arrays, and the other options compute something else ([approx_count_distinct](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct)).", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "03-data-transformation-and-modeling-q034", "bank": "praticas", "n": 79, "domain": "data-transformation-and-modeling", "title": "Shuffle Partitions vs Default Parallelism *(2026 blueprint)*", "difficulty": "medium", "question": "A DataFrame `groupBy` on 40 MB of data runs 200 tiny tasks after the shuffle on classic compute. An engineer wants to tune the post-shuffle partition count and then re-measure. Which setting controls it?", "choices": {"A": "`spark.default.parallelism`", "B": "`spark.executor.memory`", "C": "`spark.sql.shuffle.partitions`", "D": "`spark.sql.autoBroadcastJoinThreshold`"}, "answer": "C", "short": "`spark.sql.shuffle.partitions`.", "explanation": "It sets the number of partitions used when shuffling data for joins or aggregations in the DataFrame and SQL engine (default 200). On Databricks, setting it to `auto` lets Spark size it from the plan and the data. `spark.default.parallelism` applies to RDD operations, memory settings size the JVMs, and the broadcast threshold controls join strategy ([AQE](https://docs.databricks.com/aws/en/optimizations/aqe), [Spark SQL tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html)).", "lesson": "03-data-transformation-and-modeling/07-spark-tuning-parameters", "related": null}, {"id": "03-data-transformation-and-modeling-q035", "bank": "praticas", "n": 80, "domain": "data-transformation-and-modeling", "title": "Choosing a Gold Object for a Busy Dashboard *(2026 blueprint)*", "difficulty": "medium", "question": "Two hundred users open a dashboard each morning that aggregates revenue by region from a large Silver table. Hourly freshness is acceptable. The team wants fast reads and doesn't want to maintain refresh code. Which Unity Catalog object should back the dashboard?", "choices": {"A": "A standard view over the Silver table", "B": "A streaming table that appends Silver rows", "C": "A temporary view created by the dashboard query", "D": "A materialized view refreshed on a schedule"}, "answer": "D", "short": "A materialized view refreshed on a schedule.", "explanation": "A materialized view stores precomputed results and refreshes them (incrementally when possible) on a schedule or when upstream data changes, so reads are cheap. A view recomputes the aggregation on every query. Temporary views are session-scoped. Streaming tables append new rows and don't recompute an aggregate ([standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)).", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "04-working-with-lakeflow-jobs-q001", "bank": "praticas", "n": 81, "domain": "working-with-lakeflow-jobs", "title": "Adding an Upstream Task to an Existing Job", "difficulty": "medium", "question": "A data engineer executes a single-task job each morning. Upon discovering an upstream data issue, they must add a new notebook to run before the original task. What is the correct approach to set up this new upstream task?", "choices": {"A": "Create a new task in the existing Job, and then add the original task as a dependency of the new task", "B": "Create a separate Job for the new notebook and schedule it to run 30 minutes before the original Job", "C": "Clone the existing Job and add the new notebook as a second task in the clone", "D": "Replace the original task's notebook with a wrapper notebook that runs both notebooks sequentially"}, "answer": "A", "short": "Create a new task in the existing Job, and then add the original task as a dependency of the new task.", "explanation": "In Databricks Jobs, task dependencies are defined by specifying which tasks a given task \"depends on.\" To insert an upstream step, the new task should have no dependencies (runs first), and the original task should be configured to depend on the new task (runs after).", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": null}, {"id": "04-working-with-lakeflow-jobs-q002", "bank": "praticas", "n": 82, "domain": "working-with-lakeflow-jobs", "title": "Limiting Query Refresh Schedule Duration", "difficulty": "medium", "question": "An engineering manager wants a query to refresh every minute for the first week after a project launch, with no compute costs after that week. What strategy ensures the query stops refreshing and generating costs beyond week one?", "choices": {"A": "Set the SQL warehouse to auto-stop after one week of total runtime", "B": "Set the query's refresh schedule to end on a specific date in the query scheduler", "C": "Manually cancel the refresh schedule at the end of the week", "D": "Create a Databricks Job to disable the query refresh after seven days"}, "answer": "B", "short": "Set the query's refresh schedule to end on a specific date in the query scheduler.", "explanation": "Databricks SQL query schedulers support an optional end date/time, allowing the refresh to automatically stop once the date is reached. No manual intervention is needed after the initial setup.", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q003", "bank": "praticas", "n": 83, "domain": "working-with-lakeflow-jobs", "title": "Programmatic Job Schedule Representation", "difficulty": "medium", "question": "A data engineer manages a complex job schedule and wants to represent and submit it to other jobs programmatically rather than manually selecting values in the Databricks scheduling form. Which tool enables this?", "choices": {"A": "Declarative Automation Bundles (formerly Databricks Asset Bundles) YAML configuration", "B": "Apache Airflow DAG definitions", "C": "Cron syntax", "D": "JSON job templates via the Databricks CLI"}, "answer": "C", "short": "Cron syntax.", "explanation": "Databricks Jobs support quartz cron expressions for scheduling. Cron strings are compact, human-readable, and can be programmatically constructed and submitted via the Jobs API or embedded in Declarative Automation Bundles (formerly Databricks Asset Bundles) YAML configuration files.", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q004", "bank": "praticas", "n": 84, "domain": "working-with-lakeflow-jobs", "title": "Scheduling a Daily SQL Query Refresh", "difficulty": "easy", "question": "An engineering manager reviews a query daily but currently reruns it manually and waits for results. What strategy guarantees the query results are refreshed daily automatically?", "choices": {"A": "Use a Lakeflow Declarative Pipelines pipeline with a daily trigger to refresh the query", "B": "Create a Databricks Job that runs the query notebook on a daily cron schedule", "C": "Set up an Apache Airflow DAG to trigger the query execution daily", "D": "Schedule the query to refresh every 1 day from the query's page in Databricks SQL"}, "answer": "D", "short": "Schedule the query to refresh every 1 day from the query's page in Databricks SQL.", "explanation": "Databricks SQL provides a built-in scheduler accessible directly from the query editor. Setting a recurring daily refresh interval ensures results are always up-to-date without manual intervention or external orchestration tools.", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q005", "bank": "praticas", "n": 85, "domain": "working-with-lakeflow-jobs", "title": "When to Use \"Depends On\" for a Job Task", "difficulty": "easy", "question": "In what situations should a data engineer choose a task in the \"Depends On\" field when creating a new Databricks Job task?", "choices": {"A": "When another task needs to successfully complete before the new task begins", "B": "When the new task should only run if a previous task has completed successfully", "C": "When the new task processes data from a different database than other tasks", "D": "When the new task needs to run on a different cluster than other tasks"}, "answer": "A", "short": "When another task needs to successfully complete before the new task begins.", "explanation": "The \"Depends On\" field establishes execution order in a Databricks Job DAG. The new task will only start after all specified upstream tasks have completed successfully. With the default Run if condition (*All succeeded*), if a dependency fails the downstream task doesn't run and is marked `Upstream failed`.", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": null}, {"id": "04-working-with-lakeflow-jobs-q006", "bank": "praticas", "n": 86, "domain": "working-with-lakeflow-jobs", "title": "Branching on New Data *(2026 blueprint)*", "difficulty": "medium", "question": "An ingestion task publishes the number of rows it loaded as a task value. The transformation tasks should run only when that number is greater than zero. Which Lakeflow Jobs feature implements this?", "choices": {"A": "A For each task over the task value", "B": "An If/else condition task comparing `{{tasks.ingest.values.rows_loaded}} > 0`, with transformations depending on its `true` outcome", "C": "A retry policy on the transformation task", "D": "Setting max concurrent runs to 0 when no data arrives"}, "answer": "B", "short": "An If/else condition task comparing `{{tasks.ingest.values.rows_loaded}} > 0`, with transformations depending on its `true` outcome.", "explanation": "The If/else task evaluates a boolean expression on two operands (task values, job parameters, literals). Downstream tasks depend on its `(true)` or `(false)` outcome. `>` performs a numeric comparison ([If/else task](https://docs.databricks.com/aws/en/jobs/if-else)).", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "04-working-with-lakeflow-jobs-q007", "bank": "praticas", "n": 87, "domain": "working-with-lakeflow-jobs", "title": "Looping Over Tables *(2026 blueprint)*", "difficulty": "medium", "question": "The same load notebook must run for 30 source tables, at most five at a time, without defining 30 tasks. Which configuration meets this?", "choices": {"A": "A single notebook task with `max_retries` set to 30", "B": "Thirty notebook tasks with no dependencies", "C": "A For each task with the table list as input, the notebook as the nested task, and concurrency set to 5", "D": "A Run Job task pointing at itself"}, "answer": "C", "short": "A For each task with the table list as input, the notebook as the nested task, and concurrency set to 5.", "explanation": "For each runs one nested task once per input element, passing `{{input}}` (or `{{input.<key>}}`). Concurrency defaults to 1, and the nested task can't itself be a For each ([For each task](https://docs.databricks.com/aws/en/jobs/for-each)).", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "04-working-with-lakeflow-jobs-q008", "bank": "praticas", "n": 88, "domain": "working-with-lakeflow-jobs", "title": "Retrying Transient Failures *(2026 blueprint)*", "difficulty": "easy", "question": "A task that calls an external API fails a few times a week with transient network errors, and succeeds when re-run minutes later. What is the built-in way to handle this?", "choices": {"A": "Increase the task timeout", "B": "Add an If/else task after it", "C": "Set the job's max concurrent runs to 2", "D": "Configure a retry policy on the task, with a retry interval"}, "answer": "D", "short": "Configure a retry policy on the task, with a retry interval.", "explanation": "Task-level retries automatically re-run a failed task after the configured interval. A timeout limits how long one attempt may run, and when both are set the timeout applies to each retry. Concurrency and branching don't retry anything ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "04-working-with-lakeflow-jobs-q009", "bank": "praticas", "n": 89, "domain": "working-with-lakeflow-jobs", "title": "Cleanup That Always Runs *(2026 blueprint)*", "difficulty": "medium", "question": "A job's final task drops temporary staging tables. It must run whether the upstream transform succeeds or fails. Which Run if condition should it use?", "choices": {"A": "All done", "B": "At least one succeeded", "C": "All succeeded", "D": "All failed"}, "answer": "A", "short": "All done.", "explanation": "*All done* runs the task after all dependencies finish, whatever their status. The default, *All succeeded*, would mark the task `Upstream failed` and skip it when the transform fails. *All failed* runs it only after failures ([Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)).", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "04-working-with-lakeflow-jobs-q010", "bank": "praticas", "n": 90, "domain": "working-with-lakeflow-jobs", "title": "Processing Files Soon After Unpredictable Drops *(2026 blueprint)*", "difficulty": "medium", "question": "A partner uploads JSON files to a Unity Catalog external location at unpredictable times: sometimes several an hour, sometimes nothing for a day. Each drop should be processed shortly after it lands, without empty runs or idle compute. Which trigger should the Lakeflow Job use?", "choices": {"A": "Scheduled trigger every 5 minutes", "B": "File arrival trigger on the external location", "C": "Continuous trigger", "D": "Manual trigger by an operator"}, "answer": "B", "short": "File arrival trigger on the external location.", "explanation": "A file arrival trigger monitors a UC external location or volume and starts a run only when new files appear. *Wait after last change* can batch bursts into one run. Polling schedules start runs that find nothing, and continuous triggers keep compute running ([file arrival triggers](https://docs.databricks.com/aws/en/jobs/file-arrival-triggers)).", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q011", "bank": "praticas", "n": 91, "domain": "working-with-lakeflow-jobs", "title": "Running When Upstream Tables Change *(2026 blueprint)*", "difficulty": "medium", "question": "A Gold build job must run after **both** `main.silver.orders` and `main.silver.customers` are updated. Those tables are maintained by two other teams' jobs, which run at varying times. Which trigger configuration fits?", "choices": {"A": "A scheduled trigger at 06:00", "B": "A table update trigger on both tables with \"Any table is updated\"", "C": "A table update trigger on both tables with \"All tables are updated\"", "D": "A file arrival trigger on the tables' storage paths"}, "answer": "C", "short": "A table update trigger on both tables with \"All tables are updated\".", "explanation": "Table update triggers start a run when monitored UC tables change. With multiple tables, *Trigger when* can be set to **All tables are updated** or **Any table is updated**. The job's Run as principal needs `SELECT` on the tables. File arrival triggers can't target managed table locations ([table update triggers](https://docs.databricks.com/aws/en/jobs/trigger-table-update)).", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q012", "bank": "praticas", "n": 92, "domain": "working-with-lakeflow-jobs", "title": "Time-Based vs Data-Driven Triggers *(2026 blueprint)*", "difficulty": "easy", "question": "A regulatory report must be published at exactly 07:00 every weekday, using whatever data has arrived by then. Which trigger fits best?", "choices": {"A": "Continuous trigger", "B": "File arrival trigger", "C": "Table update trigger", "D": "Scheduled trigger with Quartz cron `0 0 7 ? * MON-FRI`"}, "answer": "D", "short": "Scheduled trigger with Quartz cron `0 0 7 ? * MON-FRI`.", "explanation": "When the deadline, not data availability, decides when work runs, a time-based schedule is right. Quartz cron puts seconds first, and `?` goes in day-of-month when day-of-week is constrained. Data-driven triggers fit when work should follow data arrival ([schedules and triggers](https://docs.databricks.com/aws/en/jobs/triggers)).", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "04-working-with-lakeflow-jobs-q013", "bank": "praticas", "n": 93, "domain": "working-with-lakeflow-jobs", "title": "Configuring a Dashboard Task *(2026 blueprint)*", "difficulty": "easy", "question": "After a pipeline task refreshes Gold tables, an AI/BI dashboard must be refreshed in the same job. Which task configuration achieves this?", "choices": {"A": "A Dashboards task that depends on the pipeline task and uses a SQL warehouse", "B": "A notebook task that calls `display()` on the Gold tables", "C": "A For each task over the dashboard's widgets", "D": "A second job with a scheduled trigger 30 minutes later"}, "answer": "A", "short": "A Dashboards task that depends on the pipeline task and uses a SQL warehouse.", "explanation": "Lakeflow Jobs has native task types for notebooks, SQL, dashboards, and pipelines. Making the Dashboards task depend on the pipeline task guarantees the order inside one DAG. A separate job on a fixed delay can run before the data is ready ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": null}, {"id": "04-working-with-lakeflow-jobs-q014", "bank": "praticas", "n": 94, "domain": "working-with-lakeflow-jobs", "title": "Passing a Value Between Tasks *(2026 blueprint)*", "difficulty": "medium", "question": "Task `ingest` computes the latest order date. Task `report` needs that value. Which code sets it in `ingest`?", "choices": {"A": "`dbutils.widgets.text(\"max_date\", value)`", "B": "`dbutils.jobs.taskValues.set(key=\"max_date\", value=value)`", "C": "`spark.conf.set(\"max_date\", value)`", "D": "`dbutils.notebook.exit(value)` in every task"}, "answer": "B", "short": "`dbutils.jobs.taskValues.set(key=\"max_date\", value=value)`.", "explanation": "Task values pass small, JSON-serializable results (up to 48 KiB) between tasks. Downstream tasks read them with `dbutils.jobs.taskValues.get(taskKey=\"ingest\", key=\"max_date\")` or, preferably, the reference `{{tasks.ingest.values.max_date}}` in parameters ([task values](https://docs.databricks.com/aws/en/jobs/task-values)).", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "04-working-with-lakeflow-jobs-q015", "bank": "praticas", "n": 95, "domain": "working-with-lakeflow-jobs", "title": "Reading Quartz Cron *(2026 blueprint)*", "difficulty": "easy", "question": "A Lakeflow Job schedule uses the Quartz expression `0 30 2 * * ?`. When does it run?", "choices": {"A": "Every 30 minutes past 2 o'clock, every hour", "B": "At 00:30 on the 2nd of every month", "C": "At 02:30:00 every day", "D": "Every 2 minutes at second 30"}, "answer": "C", "short": "At 02:30:00 every day.", "explanation": "Quartz fields are seconds, minutes, hours, day-of-month, month, day-of-week, and an optional year. So `0 30 2 * * ?` means second 0, minute 30, hour 2, every day of every month, with no specific day-of-week ([Quartz CronTrigger tutorial](https://www.quartz-scheduler.org/documentation/quartz-2.3.0/tutorials/crontrigger.html)).", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "05-implementing-cicd-q001", "bank": "praticas", "n": 96, "domain": "implementing-cicd", "title": "Where Pull Requests Are Created", "difficulty": "easy", "question": "A data engineer works on a feature branch in a Databricks Git folder. Which step of their workflow is performed in the Git provider (for example GitHub) rather than in the Databricks Git dialog?", "choices": {"A": "Committing and pushing changes", "B": "Creating the feature branch", "C": "Pulling a teammate's latest changes", "D": "Creating and merging the pull request into the default branch"}, "answer": "D", "short": "Creating and merging the pull request into the default branch.", "explanation": "Git folders handle branch creation, switching, Commit & Push, pull, merge, rebase, and conflict resolution in the workspace UI. The docs say to \"use your Git provider's interface to create a pull request and merge it into the default branch\", where reviews and branch protections apply ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q002", "bank": "praticas", "n": 97, "domain": "implementing-cicd", "title": "Benefit of Git Folders Over Notebook Versioning", "difficulty": "medium", "question": "A data engineer must decide between the built-in versioning of Databricks Notebooks and Databricks Git folders. What is one benefit of using Git folders (formerly Repos) instead?", "choices": {"A": "Databricks Git folders support the use of multiple branches", "B": "Git folders eliminate the need for a Git provider by hosting repositories internally", "C": "Git folders provide a visual diff tool for comparing notebook cell outputs", "D": "Git folders automatically back up notebooks to cloud storage every 5 minutes"}, "answer": "A", "short": "Databricks Git folders support the use of multiple branches.", "explanation": "Built-in notebook versioning provides only a linear history of auto-saved snapshots. Git folders integrate fully with Git, enabling feature branches, pull requests, code reviews, and collaborative development workflows — essential for team-based software engineering practices.", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q003", "bank": "praticas", "n": 98, "domain": "implementing-cicd", "title": "Syncing a Git Folder With Remote Changes", "difficulty": "easy", "question": "A data engineer's colleague has pushed updates to the central Git repository. The data engineer needs to sync their Databricks Git folder with these changes. Which Git operation accomplishes this?", "choices": {"A": "Clone", "B": "Pull", "C": "Rebase", "D": "Fetch"}, "answer": "B", "short": "Pull.", "explanation": "A `git pull` fetches changes from the remote repository and merges them into the current local branch. In a Databricks Git folder, this is the **Pull** action in the Git dialog (pull also clears notebook state), keeping the local copy synchronized with the latest upstream changes.", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q004", "bank": "praticas", "n": 99, "domain": "implementing-cicd", "title": "Committing From a Git Folder *(2026 blueprint)*", "difficulty": "easy", "question": "A data engineer has edited two notebooks in a Databricks Git folder on branch `feature/dedup`. How do they get the changes to the remote repository from the workspace UI?", "choices": {"A": "Export the notebooks as DBC files and upload them to the Git provider", "B": "Run `databricks bundle deploy`", "C": "Open the Git dialog, select the changes, enter a commit message, and click Commit & Push", "D": "Click Pull, which pushes local changes automatically"}, "answer": "C", "short": "Open the Git dialog, select the changes, enter a commit message, and click Commit & Push.", "explanation": "In Git folders, the UI \"commits and pushes in a single action\", and a commit message is required. Pull brings remote changes **in**. Bundle deploy pushes to a workspace, not to Git ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q005", "bank": "praticas", "n": 100, "domain": "implementing-cicd", "title": "Creating a Feature Branch *(2026 blueprint)*", "difficulty": "easy", "question": "Before starting new work, an engineer wants a separate branch based on `main` in their Git folder. What should they do?", "choices": {"A": "Rename the `main` branch in the Git dialog", "B": "Clone the repository again into a new workspace folder", "C": "Ask an admin to create the branch with the Repos API", "D": "Use the Git dialog's Create Branch option, name the branch, and choose `main` as the base"}, "answer": "D", "short": "Use the Git dialog's Create Branch option, name the branch, and choose `main` as the base.", "explanation": "Git folders create and switch branches from the Git dialog. Switching branches can carry uncommitted changes over. It can also delete workspace assets that don't exist on the target branch, and recreate them with new IDs when you switch back ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q006", "bank": "praticas", "n": 101, "domain": "implementing-cicd", "title": "Reset in a Git Folder *(2026 blueprint)*", "difficulty": "hard", "question": "An engineer clicks **Reset** on a branch in a Git folder. What is the effect?", "choices": {"A": "It is equivalent to `git reset --hard` plus `git push --force`, so committed and uncommitted changes are lost locally and on the remote branch", "B": "Only uncommitted local changes are discarded", "C": "The branch is restored from notebook revision history", "D": "The Git folder is unlinked from the remote repository"}, "answer": "A", "short": "It is equivalent to `git reset --hard` plus `git push --force`, so committed and uncommitted changes are lost locally and on the remote branch.", "explanation": "The docs warn: \"When you reset, you lose all uncommitted and committed changes in both the local and remote version of the branch.\" Use it only when you really want to discard work ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "05-implementing-cicd-q007", "bank": "praticas", "n": 102, "domain": "implementing-cicd", "title": "Keeping a Secret Out of the Bundle *(2026 blueprint)*", "difficulty": "medium", "question": "A Declarative Automation Bundle deploys a job that needs a database password. The password must not appear in `databricks.yml`, in notebooks, or in Git. The CI system stores it as a secret. How should the bundle receive it at deploy time?", "choices": {"A": "Put the password in the variable's `default`", "B": "Declare a bundle variable with no default, and have CI export `BUNDLE_VAR_<variable_name>` from its secret store", "C": "Store it in a `passwords.txt` file in the bundle root", "D": "Hard-code it with `spark.conf.set` in the notebook"}, "answer": "B", "short": "Declare a bundle variable with no default, and have CI export `BUNDLE_VAR_<variable_name>` from its secret store.", "explanation": "Bundle variables can be set from `BUNDLE_VAR_`-prefixed environment variables, so the value never enters source control. Runtime credentials can also be read in code with `dbutils.secrets.get` ([bundle variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q008", "bank": "praticas", "n": 103, "domain": "implementing-cicd", "title": "Bundle Variable Precedence *(2026 blueprint)*", "difficulty": "hard", "question": "A bundle declares `catalog` with `default: dev`. The `prod` target sets `variables: {catalog: prod}`. In CI, the environment has `BUNDLE_VAR_catalog=staging`, and the command is `databricks bundle deploy -t prod --var=\"catalog=prod_v2\"`. Which value is used?", "choices": {"A": "`dev`", "B": "`prod`", "C": "`prod_v2`", "D": "`staging`"}, "answer": "C", "short": "`prod_v2`.", "explanation": "The CLI uses the first source that provides a value, in this order: the `--var` option, then `BUNDLE_VAR_` environment variables, then `variable-overrides.json`, then target `variables`, then the declaration's `default` ([bundle variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q009", "bank": "praticas", "n": 104, "domain": "implementing-cicd", "title": "Promoting One Codebase Across Environments *(2026 blueprint)*", "difficulty": "medium", "question": "A team wants the same job definition deployed to dev, test, and prod workspaces, each writing to a different Unity Catalog catalog. What is the bundle-native approach?", "choices": {"A": "Copy `resources/job.yml` into three folders, one per environment", "B": "Edit the job in each workspace UI after deployment", "C": "Create three Git repositories", "D": "Define `dev`, `test`, and `prod` targets with their own workspace hosts, and override a `catalog` variable per target"}, "answer": "D", "short": "Define `dev`, `test`, and `prod` targets with their own workspace hosts, and override a `catalog` variable per target.", "explanation": "Targets override top-level settings (workspace, `run_as`, variables, resource settings) per environment, so one set of resource YAML is promoted with `databricks bundle deploy -t <target>`. Manual UI edits drift from source control, and the next deploy can overwrite them ([Declarative Automation Bundles](https://docs.databricks.com/aws/en/dev-tools/bundles/)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q010", "bank": "praticas", "n": 105, "domain": "implementing-cicd", "title": "Development Mode Behaviour *(2026 blueprint)*", "difficulty": "medium", "question": "An engineer deploys a bundle with `-t dev`, where the target has `mode: development`. The deployed job never runs on its daily schedule. Why?", "choices": {"A": "Development mode pauses schedules and triggers on deployed resources, and prefixes resource names with `[dev <user>]`", "B": "Development mode deletes schedules from the YAML", "C": "Development mode requires a service principal", "D": "The `dev` target always deploys to a read-only workspace"}, "answer": "A", "short": "Development mode pauses schedules and triggers on deployed resources, and prefixes resource names with `[dev <user>]`.", "explanation": "`mode: development` also marks pipelines as `development: true` and allows concurrent runs, so engineers can iterate safely. Run the job manually with `databricks bundle run`, or deploy to a production-mode target for scheduled runs ([deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q011", "bank": "praticas", "n": 106, "domain": "implementing-cicd", "title": "Production Mode Safeguards *(2026 blueprint)*", "difficulty": "medium", "question": "Which behaviour is part of `mode: production` for a bundle target?", "choices": {"A": "It pauses all schedules after deployment", "B": "It validates the configured Git branch and that `run_as` and permissions are specified (a service principal is recommended), and it disallows cluster overrides", "C": "It prefixes every resource name with the deployer's user name", "D": "It skips YAML validation for faster deploys"}, "answer": "B", "short": "It validates the configured Git branch and that `run_as` and permissions are specified (a service principal is recommended), and it disallows cluster overrides.", "explanation": "Production mode also checks that pipelines are `development: false` and that paths aren't overridden to a specific user. The branch check can be overridden with `--force` ([deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q012", "bank": "praticas", "n": 107, "domain": "implementing-cicd", "title": "Validating Before Deploying *(2026 blueprint)*", "difficulty": "easy", "question": "In a CI pipeline, which Databricks CLI command checks that the bundle configuration is syntactically correct before anything is deployed?", "choices": {"A": "`databricks bundle sync`", "B": "`databricks bundle destroy`", "C": "`databricks bundle validate`", "D": "`databricks jobs list`"}, "answer": "C", "short": "`databricks bundle validate`.", "explanation": "`validate` checks the bundle configuration. `deploy -t <target>` deploys it, `run` runs a job or pipeline, `plan` shows the deployment plan, and `destroy` deletes previously deployed resources ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q013", "bank": "praticas", "n": 108, "domain": "implementing-cicd", "title": "Running a Bundle Job From CI *(2026 blueprint)*", "difficulty": "easy", "question": "After `databricks bundle deploy -t test`, the CI pipeline must start the bundle's `orders_job` in the test environment and wait for the result. Which command does this?", "choices": {"A": "`databricks bundle init orders_job`", "B": "`databricks bundle deploy orders_job --run`", "C": "`databricks bundle summary -t test`", "D": "`databricks bundle run orders_job -t test`"}, "answer": "D", "short": "`databricks bundle run orders_job -t test`.", "explanation": "`bundle run` runs \"a job, pipeline, app, or script\" defined in the bundle, against the selected target. `summary` lists the bundle's identity and deployed resources, and `init` creates a bundle from a template ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q014", "bank": "praticas", "n": 109, "domain": "implementing-cicd", "title": "Bringing an Existing Job Under a Bundle *(2026 blueprint)*", "difficulty": "hard", "question": "A job was built by hand in the UI. The team wants it managed by their bundle without recreating it from scratch. Which CLI commands help?", "choices": {"A": "`databricks bundle generate` to produce YAML for the existing job, then `databricks bundle deployment bind` to link the bundle resource to it", "B": "`databricks bundle destroy`, then recreate it in the UI", "C": "`databricks bundle sync`, which copies the workspace job into Git", "D": "`databricks bundle validate --import`"}, "answer": "A", "short": "`databricks bundle generate` to produce YAML for the existing job, then `databricks bundle deployment bind` to link the bundle resource to it.", "explanation": "`generate` creates bundle configuration for a resource that already exists in the workspace. `deployment bind` links a bundle-defined resource to the existing remote resource, so later deploys update it instead of creating a duplicate. `sync` is a one-way copy of local files to the workspace ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "05-implementing-cicd-q015", "bank": "praticas", "n": 110, "domain": "implementing-cicd", "title": "What a Bundle Packages *(2026 blueprint)*", "difficulty": "easy", "question": "Which set of assets can a Declarative Automation Bundle define and deploy together?", "choices": {"A": "Only notebooks", "B": "Lakeflow Jobs, Lakeflow (Declarative) Pipelines, and other workspace assets such as dashboards, alongside their source code", "C": "Only Unity Catalog grants", "D": "Only cluster policies"}, "answer": "B", "short": "Lakeflow Jobs, Lakeflow (Declarative) Pipelines, and other workspace assets such as dashboards, alongside their source code.", "explanation": "A bundle is YAML configuration (`databricks.yml` plus included resource files) and the code it references, versioned in Git and deployed per target. Newer CLI versions also support resources such as Genie Agents and Lakebase projects ([bundles release notes](https://docs.databricks.com/aws/en/release-notes/dev-tools/bundles)).", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q001", "bank": "praticas", "n": 111, "domain": "troubleshooting-monitoring-and-optimization", "title": "OPTIMIZE for File Compaction", "difficulty": "easy", "question": "A data engineer has discovered that the data files related to a Delta table are quite small. They aim to merge these small files into larger ones to enhance performance. Which keywords can be utilized to compact the small files?", "choices": {"A": "VACUUM", "B": "COMPACT", "C": "OPTIMIZE", "D": "DEFRAGMENT"}, "answer": "C", "short": "`OPTIMIZE`.", "explanation": "The `OPTIMIZE` command compacts small files in a Delta table into larger ones, improving read performance by reducing the number of files that need to be scanned. This is different from `VACUUM`, which removes old data files no longer referenced by the transaction log.", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q002", "bank": "praticas", "n": 112, "domain": "troubleshooting-monitoring-and-optimization", "title": "Webhook Alert for NULL Count", "difficulty": "medium", "question": "A data engineer uses a Databricks SQL dashboard to monitor data quality. When the count of NULL values in a query result reaches 100, the entire team should be alerted via a messaging webhook. What method accomplishes this?", "choices": {"A": "Configure a SQL warehouse event hook that triggers on query result thresholds", "B": "Add a conditional formatting rule to the dashboard visualization that sends a webhook", "C": "Create a Databricks Job that polls the query results and calls the webhook via Python", "D": "Set up an Alert with a new webhook alert destination"}, "answer": "D", "short": "Set up an Alert with a new webhook alert destination.", "explanation": "Databricks SQL Alerts monitor query results against a threshold condition and trigger notifications when the condition is met. Webhook destinations allow alerts to be sent to external messaging services (Slack, Microsoft Teams, PagerDuty) in real-time.", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q003", "bank": "praticas", "n": 113, "domain": "troubleshooting-monitoring-and-optimization", "title": "Diagnosing a Slow Job Task", "difficulty": "medium", "question": "A single Job executes two notebooks as distinct tasks. One notebook is performing slowly during the current Job run. What method can a tech lead use to diagnose the cause?", "choices": {"A": "Navigate to the Runs tab in the Jobs UI and click on the active run to review the processing notebook", "B": "Check the Databricks SQL query history for slow-running queries", "C": "Review the cluster event log for resource allocation errors", "D": "Open the Lakeflow Declarative Pipelines pipeline UI to inspect per-table processing metrics"}, "answer": "A", "short": "Navigate to the Runs tab in the Jobs UI and click on the active run to review the processing notebook.", "explanation": "Clicking into the active run opens a live view of the notebook execution, including links to the Spark UI for the current task. This allows inspection of active stages, task metrics, shuffle data, and memory usage to identify performance bottlenecks.", "lesson": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q004", "bank": "praticas", "n": 114, "domain": "troubleshooting-monitoring-and-optimization", "title": "Job Failure Email Notification", "difficulty": "easy", "question": "What approach should be taken to email the owner of a Databricks Job if it fails?", "choices": {"A": "Write a try/except block in the notebook that sends an email on failure", "B": "Set up an Alert in the Job's notification settings (Job page)", "C": "Configure an external monitoring tool to watch the Jobs API for failure status", "D": "Create a downstream task that runs only on failure and sends the email"}, "answer": "B", "short": "Set up an Alert in the Job's notification settings (Job page).", "explanation": "Databricks Jobs support email notifications for job events (failure, success, or start). The job owner's email address is added directly from the Job's \"Notifications\" section, requiring no custom code or external alerting systems.", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q005", "bank": "praticas", "n": 115, "domain": "troubleshooting-monitoring-and-optimization", "title": "Webhook Alert for Zero-Sales Stores", "difficulty": "medium", "question": "A data engineer tracks store-level records where sales equal zero. When this count exceeds zero, the entire team should be notified via a messaging webhook. What approach accomplishes this?", "choices": {"A": "Configure a Lakeflow Declarative Pipelines expectation that triggers a webhook when zero-sales records appear", "B": "Build a custom Python script that polls the query results and posts to the webhook", "C": "Set up an Alert with a new webhook alert destination", "D": "Add a dashboard filter that highlights zero-sales stores and emails the team"}, "answer": "C", "short": "Set up an Alert with a new webhook alert destination.", "explanation": "Configure the alert condition on the query result (value > 0) and point the destination to the team's webhook URL. Databricks SQL Alerts evaluate the query result on each refresh and trigger the webhook notification when the threshold condition is met.", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q006", "bank": "praticas", "n": 116, "domain": "troubleshooting-monitoring-and-optimization", "title": "Spotting a Duration Regression *(2026 blueprint)*", "difficulty": "easy", "question": "Stakeholders say a daily Lakeflow Job \"feels slower lately\". Where can the engineer compare recent run durations with the historical baseline, task by task?", "choices": {"A": "The workspace admin settings", "B": "The cluster's Environment tab in the Spark UI", "C": "`DESCRIBE HISTORY` on the output table", "D": "The job's Runs tab matrix view"}, "answer": "D", "short": "The job's Runs tab matrix view.", "explanation": "The matrix view shows one column per run, with a Run total duration row and a row per task. Bar height reflects duration, so a growing bar exposes the regression and the task responsible. History is kept for 60 days. Use `system.lakeflow` tables for longer trends ([Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q007", "bank": "praticas", "n": 117, "domain": "troubleshooting-monitoring-and-optimization", "title": "Finding the Upstream Blocker *(2026 blueprint)*", "difficulty": "medium", "question": "A job run failed. In the Graph view, three downstream tasks show **Upstream failed** and one task shows **Failed**. Where should the engineer start investigating?", "choices": {"A": "The Failed task. The Upstream failed tasks didn't run because their dependency failed", "B": "The three Upstream failed tasks, because they're the most numerous", "C": "The cluster event log of the last task in the DAG", "D": "The job's schedule"}, "answer": "A", "short": "The Failed task. The Upstream failed tasks didn't run because their dependency failed.", "explanation": "With the default Run if (*All succeeded*), a task whose dependency fails is marked `Upstream failed`. The DAG graph shows where the failure started. Fix that task, then use **Repair run** to re-run it and its dependents ([Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)).", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q008", "bank": "praticas", "n": 118, "domain": "troubleshooting-monitoring-and-optimization", "title": "Succeeded With Failures *(2026 blueprint)*", "difficulty": "medium", "question": "A job run shows the status **Succeeded with failures**. What does that mean?", "choices": {"A": "Every task failed, but the job was retried successfully", "B": "Some tasks failed, but all leaf tasks (tasks with no downstream dependencies) succeeded", "C": "The run succeeded, but notifications failed to send", "D": "The run timed out after producing output"}, "answer": "B", "short": "Some tasks failed, but all leaf tasks (tasks with no downstream dependencies) succeeded.", "explanation": "A run's outcome is determined by its leaf tasks. For example, a failed optional branch with no downstream dependents can leave the run \"Succeeded with failures\" ([Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q009", "bank": "praticas", "n": 119, "domain": "troubleshooting-monitoring-and-optimization", "title": "Fixing a Timed Out Task *(2026 blueprint)*", "difficulty": "easy", "question": "A task failed with status **Timed Out** after 45 minutes. With today's data volume it needs about 60 minutes. What should the engineer change so future runs complete?", "choices": {"A": "The compute's auto termination setting", "B": "The job's max concurrent runs", "C": "The task's timeout, raised above 60 minutes with headroom", "D": "The upstream dependency's Run if condition"}, "answer": "C", "short": "The task's timeout, raised above 60 minutes with headroom.", "explanation": "If a task doesn't finish within its configured timeout, its status is set to Timed Out. With retries configured, the timeout applies to each attempt. The run-duration *warning* threshold only raises an alert, and the other settings don't control the timeout ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q010", "bank": "praticas", "n": 120, "domain": "troubleshooting-monitoring-and-optimization", "title": "Skewed Aggregation With AQE Enabled *(2026 blueprint)*", "difficulty": "hard", "question": "A batch job does a `groupBy(\"customer_id\")` aggregation. In the Spark UI, most tasks in the longest stage finish in seconds, but one runs for 12 minutes. Its shuffle read is about 10× the median. AQE is enabled with default settings. Which change most directly reduces the runtime?", "choices": {"A": "Add more workers to the cluster", "B": "Reduce `spark.sql.shuffle.partitions`", "C": "Rely on AQE skew-join handling to split the partition", "D": "Salt the aggregation key, then aggregate the partial results in a second pass"}, "answer": "D", "short": "Salt the aggregation key, then aggregate the partial results in a second pass.", "explanation": "One hot key overloads a single task. AQE splits skewed partitions only in sort-merge and shuffle-hash **joins**, not in `groupBy` aggregations. More workers leave the giant task on one core, and fewer shuffle partitions make partitions bigger. Salting spreads the hot key across many tasks ([Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page), [AQE](https://docs.databricks.com/aws/en/optimizations/aqe)).", "lesson": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q011", "bank": "praticas", "n": 121, "domain": "troubleshooting-monitoring-and-optimization", "title": "Diagnosing Disk Spill *(2026 blueprint)*", "difficulty": "medium", "question": "A join stage shows large **Spill (Disk)** values and high peak execution memory, with no single straggler task. Which change addresses the cause?", "choices": {"A": "Set `spark.sql.shuffle.partitions` to `auto` (or more partitions), or use workers with more memory", "B": "Disable AQE", "C": "Increase `spark.default.parallelism` only", "D": "Run `VACUUM` on the input tables"}, "answer": "A", "short": "Set `spark.sql.shuffle.partitions` to `auto` (or more partitions), or use workers with more memory.", "explanation": "Spill happens when Spark runs low on execution memory during shuffles, joins, sorts, or aggregations. Smaller partitions, less data held per task, or more executor memory reduce it. `spark.default.parallelism` affects RDDs. `VACUUM` doesn't touch execution memory ([Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page)).", "lesson": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q012", "bank": "praticas", "n": 122, "domain": "troubleshooting-monitoring-and-optimization", "title": "Liquid Clustering Keys *(2026 blueprint)*", "difficulty": "medium", "question": "A team's Delta table uses Liquid Clustering on `event_date`. Query patterns change, and most queries now filter on `customer_id`. What should they do?", "choices": {"A": "Rewrite the table with `PARTITIONED BY (customer_id)`", "B": "Run `ALTER TABLE t CLUSTER BY (customer_id)`, then run `OPTIMIZE` (use `OPTIMIZE ... FULL` to recluster existing data)", "C": "Run `OPTIMIZE t ZORDER BY (customer_id)`", "D": "Drop and recreate the table, because clustering keys can't change"}, "answer": "B", "short": "Run `ALTER TABLE t CLUSTER BY (customer_id)`, then run `OPTIMIZE` (use `OPTIMIZE ... FULL` to recluster existing data).", "explanation": "Clustering keys can change at any time without an immediate rewrite. Later `OPTIMIZE` runs and writes use the new keys, and `OPTIMIZE FULL` reclusters all existing data. Clustering isn't compatible with partitioning or `ZORDER` ([liquid clustering](https://docs.databricks.com/aws/en/delta/clustering)).", "lesson": "06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q013", "bank": "praticas", "n": 123, "domain": "troubleshooting-monitoring-and-optimization", "title": "Automatic Liquid Clustering *(2026 blueprint)*", "difficulty": "medium", "question": "A team wants Databricks to choose and evolve clustering keys from actual query patterns. What do they need?", "choices": {"A": "Partitioning by every filter column", "B": "`ZORDER BY AUTO` in a nightly `OPTIMIZE` job", "C": "`CLUSTER BY AUTO` on a Unity Catalog managed table with predictive optimization enabled", "D": "A Spark configuration that enables auto clustering on external tables"}, "answer": "C", "short": "`CLUSTER BY AUTO` on a Unity Catalog managed table with predictive optimization enabled.", "explanation": "Automatic liquid clustering \"requires predictive optimization\" for key selection and clustering operations. Predictive optimization runs only on UC managed tables ([liquid clustering](https://docs.databricks.com/aws/en/delta/clustering), [predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).", "lesson": "06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q014", "bank": "praticas", "n": 124, "domain": "troubleshooting-monitoring-and-optimization", "title": "What Predictive Optimization Does *(2026 blueprint)*", "difficulty": "easy", "question": "Which statement about predictive optimization is correct?", "choices": {"A": "It runs `OPTIMIZE ... ZORDER BY` on all partitioned tables", "B": "It tunes Spark configurations for every notebook session", "C": "It applies to external tables and tables received through sharing", "D": "It runs `OPTIMIZE`, `VACUUM`, and `ANALYZE` automatically on Unity Catalog managed tables"}, "answer": "D", "short": "It runs `OPTIMIZE`, `VACUUM`, and `ANALYZE` automatically on Unity Catalog managed tables.", "explanation": "Predictive optimization runs on serverless jobs compute, applies only to UC managed tables, doesn't run `ZORDER`, and can be enabled, disabled, or inherited per catalog, schema, or table. Its history is in `system.storage.predictive_optimization_operations_history` ([predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q015", "bank": "praticas", "n": 125, "domain": "troubleshooting-monitoring-and-optimization", "title": "Cluster Fails to Start *(2026 blueprint)*", "difficulty": "medium", "question": "A classic job cluster terminates during startup with `INIT_SCRIPT_FAILURE`. What should the engineer check first?", "choices": {"A": "The init script logs, to find why the cluster-scoped script failed (path, permissions, or a failing command)", "B": "The Spark UI Stages tab", "C": "The job's max concurrent runs", "D": "The Delta transaction log of the output table"}, "answer": "A", "short": "The init script logs, to find why the cluster-scoped script failed (path, permissions, or a failing command).", "explanation": "`INIT_SCRIPT_FAILURE` means a cluster-scoped init script couldn't load or exited non-zero. The Spark UI doesn't exist yet because Spark never started. Other startup codes point to cloud capacity, quota, or subnet issues ([termination error codes](https://docs.databricks.com/aws/en/compute/troubleshooting/cluster-error-codes)).", "lesson": "06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q016", "bank": "praticas", "n": 126, "domain": "troubleshooting-monitoring-and-optimization", "title": "Library Conflict on Shared Compute *(2026 blueprint)*", "difficulty": "medium", "question": "Two notebooks on the same all-purpose cluster need different versions of a Python library. A compute-scoped install of one version breaks the other notebook. What is the recommended fix?", "choices": {"A": "Install both versions as compute-scoped libraries", "B": "Install each version with notebook-scoped `%pip install pkg==x.y` in the notebook that needs it", "C": "Install the library with a global init script", "D": "Copy the library files to DBFS root"}, "answer": "B", "short": "Install each version with notebook-scoped `%pip install pkg==x.y` in the notebook that needs it.", "explanation": "Notebook-scoped libraries take precedence over compute-scoped libraries, which take precedence over Runtime built-ins, and they apply only to that notebook session. Databricks doesn't recommend installing libraries with init scripts, and DBFS library storage is deprecated ([Install libraries](https://docs.databricks.com/aws/en/libraries/)).", "lesson": "06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q017", "bank": "praticas", "n": 127, "domain": "troubleshooting-monitoring-and-optimization", "title": "Driver Out of Memory *(2026 blueprint)*", "difficulty": "medium", "question": "A notebook crashes with a driver `OutOfMemoryError` on `pdf = spark.table(\"events\").toPandas()`, where `events` has 300 million rows. Adding workers didn't help. What is the right fix?", "choices": {"A": "Increase `spark.sql.shuffle.partitions`", "B": "Add even more workers", "C": "Aggregate or filter in Spark and collect only the small result (or write results to a table)", "D": "Enable autoscaling on the cluster"}, "answer": "C", "short": "Aggregate or filter in Spark and collect only the small result (or write results to a table).", "explanation": "`toPandas()` and `collect()` pull every row into driver memory. Workers add executor capacity, not driver memory. Raising `spark.driver.memory` at compute level is a last resort. The real fix is to keep large data distributed ([Spark configuration: driver memory](https://spark.apache.org/docs/latest/configuration.html)).", "lesson": "06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting", "related": null}, {"id": "06-troubleshooting-monitoring-and-optimization-q018", "bank": "praticas", "n": 128, "domain": "troubleshooting-monitoring-and-optimization", "title": "Job Failure Rate Across the Workspace *(2026 blueprint)*", "difficulty": "medium", "question": "A platform team wants a weekly dashboard of failure rates for every Lakeflow Job over the past 90 days. Which source fits best?", "choices": {"A": "The driver logs of the last run", "B": "Each job's matrix view, screenshotted weekly", "C": "`DESCRIBE HISTORY` on each job's output tables", "D": "The `system.lakeflow.job_run_timeline` system table"}, "answer": "D", "short": "The `system.lakeflow.job_run_timeline` system table.", "explanation": "Job run system tables record runs and their result states across the account and can be queried with SQL for dashboards. The UI keeps run history for 60 days, and system tables aren't meant for real-time alerting ([System tables](https://docs.databricks.com/aws/en/admin/system-tables/), [Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "07-governance-and-security-q001", "bank": "praticas", "n": 129, "domain": "governance-and-security", "title": "External Table Data Retention After DROP", "difficulty": "medium", "question": "A data engineer drops `my_table` with `DROP TABLE IF EXISTS my_table`. The object no longer appears in `SHOW TABLES`, but the data files still exist on the filesystem. What explains this?", "choices": {"A": "The table was an external table", "B": "The table had active streaming readers that prevented file deletion", "C": "The DROP command failed silently due to insufficient permissions", "D": "The VACUUM command needs to be run separately to remove data files"}, "answer": "A", "short": "The table was an external table.", "explanation": "When an external table is dropped, Databricks removes only the metadata entry from the metastore. The underlying data files are stored at a user-defined location and are not managed by Databricks, so they remain intact after the table is dropped.", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q002", "bank": "praticas", "n": 130, "domain": "governance-and-security", "title": "Default Schema Location in the Legacy Hive Metastore", "difficulty": "easy", "question": "In a workspace still using the legacy `hive_metastore` catalog, a data engineer has established a new database with this command:\n\n```sql\nCREATE DATABASE IF NOT EXISTS customer360;\n```\n\nWhere will the `customer360` database be situated?", "choices": {"A": "`dbfs:/user/hive/warehouse/`", "B": "`dbfs:/user/hive/warehouse/customer360.db`", "C": "`dbfs:/databricks/databases/customer360/`", "D": "`dbfs:/mnt/default/customer360.db`"}, "answer": "B", "short": "`dbfs:/user/hive/warehouse/customer360.db`", "explanation": "When a database is created without specifying a `LOCATION`, Databricks stores it in the default Hive warehouse directory at `dbfs:/user/hive/warehouse/`. A subdirectory named `<database_name>.db` is automatically created for it. Specifying only `dbfs:/user/hive/warehouse` (without the `.db` suffix) is incorrect — that is the parent warehouse directory, not the database's own location.", "lesson": "07-governance-and-security/01-unity-catalog-basics", "related": null}, {"id": "07-governance-and-security-q003", "bank": "praticas", "n": 131, "domain": "governance-and-security", "title": "DESCRIBE DATABASE Location", "difficulty": "easy", "question": "Which command retrieves the location of the `customer360` database?", "choices": {"A": "`SHOW DATABASE LOCATION customer360;`", "B": "`SELECT location FROM information_schema.databases WHERE name = 'customer360';`", "C": "`DESCRIBE DATABASE customer360;`", "D": "`LIST DATABASE customer360;`"}, "answer": "C", "short": "`DESCRIBE DATABASE customer360;`", "explanation": "This command returns database metadata including the storage location path, owner, comment, and custom properties. It is the standard way to inspect database-level information in Spark SQL and Databricks.", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q004", "bank": "praticas", "n": 132, "domain": "governance-and-security", "title": "Managed Table File Deletion After DROP", "difficulty": "medium", "question": "A data engineer drops `my_table` and observes that both data files and metadata files are deleted from the filesystem. What explains the complete deletion?", "choices": {"A": "The VACUUM command was automatically triggered after the DROP", "B": "The table was stored in a temporary storage location", "C": "The table had a retention policy set to zero days", "D": "The table was a managed table"}, "answer": "D", "short": "The table was a managed table.", "explanation": "When a managed (internal) table is dropped, Databricks deletes both the metastore entry and the underlying data files, because Databricks controls the full lifecycle of managed table data. This is the opposite behavior from external tables. In Unity Catalog, a dropped managed table can be recovered with `UNDROP TABLE` for 7 days by default, and the data files are deleted after that recovery period.", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q005", "bank": "praticas", "n": 133, "domain": "governance-and-security", "title": "Table Ownership Transfer", "difficulty": "medium", "question": "A data engineer has left the organization and no longer has access. The team must transfer ownership of the engineer's Unity Catalog tables to the new lead data engineer. Who can perform this transfer?", "choices": {"A": "A metastore admin, or the owner of the tables' parent schema (or a user with MANAGE on the tables)", "B": "Any user with SELECT privilege on the tables", "C": "The new lead data engineer, by running `ALTER TABLE ... OWNER TO` on their own", "D": "Any member of the data team with MODIFY privilege"}, "answer": "A", "short": "A metastore admin, or the owner of the tables' parent schema (or a user with MANAGE on the tables).", "explanation": "In Unity Catalog, ownership can be transferred by the current owner, a metastore admin, the owner of the container (the schema for a table), or a user with the `MANAGE` privilege on the object. `SELECT` and `MODIFY` don't allow it. Use `ALTER TABLE ... OWNER TO <principal>` or the Owner field in Catalog Explorer ([Manage privileges](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/)).", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q006", "bank": "praticas", "n": 134, "domain": "governance-and-security", "title": "GRANT ALL PRIVILEGES on a Database", "difficulty": "easy", "question": "A new data engineering team needs full privileges on the `customers` database to manage the project effectively. Which command grants all permissions?", "choices": {"A": "`GRANT FULL ACCESS ON DATABASE customers TO team;`", "B": "`GRANT ALL PRIVILEGES ON DATABASE customers TO team;`", "C": "`GRANT READ, WRITE, ADMIN ON DATABASE customers TO team;`", "D": "`GRANT MANAGE ON DATABASE customers TO team;`"}, "answer": "B", "short": "`GRANT ALL PRIVILEGES ON DATABASE customers TO team;`", "explanation": "`DATABASE` is a synonym for `SCHEMA`. `ALL PRIVILEGES` grants every applicable privilege on the schema and its objects. In Unity Catalog it does **not** include `MANAGE` (or `EXTERNAL USE SCHEMA` / `EXTERNAL USE LOCATION` / `READ METADATA`), so it isn't the same as ownership.", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q007", "bank": "praticas", "n": 135, "domain": "governance-and-security", "title": "Discovering Tables Without Reading Data", "difficulty": "medium", "question": "A newly formed data engineering team needs to discover which tables exist in the Unity Catalog catalog `customers` and view their metadata, without being able to read any data yet. Which grant fits best?", "choices": {"A": "`GRANT SELECT ON CATALOG customers TO team;`", "B": "`GRANT ALL PRIVILEGES ON CATALOG customers TO team;`", "C": "`GRANT BROWSE ON CATALOG customers TO team;`", "D": "`GRANT USAGE ON DATABASE customers TO team;`"}, "answer": "C", "short": "`GRANT BROWSE ON CATALOG customers TO team;`", "explanation": "`BROWSE` lets users discover objects and view metadata without usage privileges, and Databricks recommends granting it on catalogs. `SELECT` and `ALL PRIVILEGES` would expose data. `USAGE` is a legacy Hive metastore privilege. In Unity Catalog the usage privileges are `USE CATALOG` / `USE SCHEMA`, and they don't grant data access on their own ([UC privileges reference](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)).", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q008", "bank": "praticas", "n": 136, "domain": "governance-and-security", "title": "Where to Check Table Permissions", "difficulty": "easy", "question": "A data engineer needs to use a Delta table but is unsure whether they have the necessary permissions. Where can they check their table permissions?", "choices": {"A": "The Databricks Admin Console under User Management", "B": "The SQL warehouse's access control list", "C": "The cluster configuration page under Security settings", "D": "Catalog Explorer"}, "answer": "D", "short": "Catalog Explorer.", "explanation": "The Catalog Explorer in Databricks provides a dedicated \"Permissions\" tab for each table, listing which users and groups have access and what privilege levels are granted. It is the primary interface for inspecting and managing object-level permissions.", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q009", "bank": "praticas", "n": 137, "domain": "governance-and-security", "title": "Identifying a Table Owner", "difficulty": "easy", "question": "A data engineer requires access to `new_table` but does not know who owns it. What method can be used to identify the owner?", "choices": {"A": "Review the Owner field in the table's page in Catalog Explorer", "B": "Check the cluster logs for the user who last wrote to the table", "C": "Query the `information_schema.tables` view for the table's creator", "D": "Run `SHOW GRANT ON TABLE new_table` to list all privilege holders"}, "answer": "A", "short": "Review the Owner field in the table's page in Catalog Explorer.", "explanation": "Catalog Explorer displays the table owner in the table details panel. Any user with workspace access can view this field without needing special permissions, making it the standard way to identify who to contact for permission requests.", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q010", "bank": "praticas", "n": 138, "domain": "governance-and-security", "title": "Undoing an External-to-Managed Conversion *(2026 blueprint)*", "difficulty": "hard", "question": "A data engineer converted an external table to a Unity Catalog managed table with `ALTER TABLE ... SET MANAGED`. Two days later, the team must undo it. What should they run?", "choices": {"A": "`RESTORE TABLE ... TO VERSION AS OF` the version before the conversion", "B": "`ALTER TABLE ... UNSET MANAGED`", "C": "Drop the table and recreate it as external, because rollback isn't supported", "D": "`ALTER TABLE ... SET EXTERNAL`"}, "answer": "B", "short": "`ALTER TABLE ... UNSET MANAGED`.", "explanation": "Rollback is supported within **14 days** of conversion. `UNSET MANAGED` points the table metadata back to the original external location and preserves writes made after conversion. Streams must be restarted, and Databricks deletes the managed copy seven days after rollback. `RESTORE` restores data versions, not the table type ([Convert to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed)).", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q011", "bank": "praticas", "n": 139, "domain": "governance-and-security", "title": "Converting an External Table to Managed *(2026 blueprint)*", "difficulty": "medium", "question": "Which command converts an existing Unity Catalog external Delta table to a managed table while keeping its name, permissions, and history?", "choices": {"A": "`CREATE OR REPLACE TABLE t AS SELECT * FROM t`", "B": "`CONVERT TO DELTA t`", "C": "`ALTER TABLE t SET MANAGED` on Databricks Runtime 17.3 LTS+ or serverless", "D": "`ALTER TABLE t SET LOCATION NULL`"}, "answer": "C", "short": "`ALTER TABLE t SET MANAGED` on Databricks Runtime 17.3 LTS+ or serverless.", "explanation": "The conversion copies data and the transaction log to managed storage, then switches metadata, with only brief writer downtime. It keeps the name, settings, permissions, views, and history. You must own the table, and existing streams must be restarted afterwards ([Convert to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed)).", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q012", "bank": "praticas", "n": 140, "domain": "governance-and-security", "title": "Recovering a Dropped Managed Table *(2026 blueprint)*", "difficulty": "easy", "question": "A Unity Catalog managed table was dropped by mistake yesterday. What can the team do?", "choices": {"A": "Nothing, because managed-table data is deleted immediately", "B": "Recreate it with `CREATE TABLE ... LOCATION` pointing at the old path", "C": "Run `RESTORE TABLE` on the dropped name", "D": "Run `UNDROP TABLE` within the recovery period (7 days by default)"}, "answer": "D", "short": "Run `UNDROP TABLE` within the recovery period (7 days by default).", "explanation": "Dropped managed tables can be recovered with `UNDROP TABLE` for 7 days by default, and the data files are deleted when the recovery period expires. Dropping an external table removes only metadata, and its files stay in cloud storage ([UC managed tables](https://docs.databricks.com/aws/en/tables/managed)).", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "07-governance-and-security-q013", "bank": "praticas", "n": 141, "domain": "governance-and-security", "title": "DENY in Unity Catalog *(2026 blueprint)*", "difficulty": "hard", "question": "An admin runs `DENY SELECT ON TABLE prod.gold.revenue TO contractors` in a Unity Catalog catalog, and the statement fails. Which statement is correct?", "choices": {"A": "The classic `DENY` statement applies only to the legacy `hive_metastore` catalog. In Unity Catalog, remove access by revoking (or not granting) `SELECT`, and use filters, masks, or ABAC for partial access", "B": "The syntax is wrong. It should be `DENY SELECT TO contractors ON prod.gold.revenue`", "C": "`DENY` works only on schemas, not tables", "D": "`DENY` requires a metastore admin, and a workspace admin can't run it"}, "answer": "A", "short": "The classic `DENY` statement applies only to the legacy `hive_metastore` catalog. In Unity Catalog, remove access by revoking (or not granting) `SELECT`, and use filters, masks, or ABAC for partial access.", "explanation": "The DENY reference states it \"is not supported by Unity Catalog\". Unity Catalog's deny mechanism is the ABAC DENY policy (Beta), which currently denies only `MANAGE ACCESS CONTROL` ([DENY](https://docs.databricks.com/aws/en/sql/language-manual/security-deny), [ABAC DENY policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies)).", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q014", "bank": "praticas", "n": 142, "domain": "governance-and-security", "title": "Minimum Privileges for One Table *(2026 blueprint)*", "difficulty": "medium", "question": "The `auditors` group must query only `prod.finance.ledger`, not the other tables in `prod.finance`. Which grants are required?", "choices": {"A": "`SELECT` on the table only", "B": "`USE CATALOG` on `prod`, `USE SCHEMA` on `prod.finance`, and `SELECT` on `prod.finance.ledger`", "C": "`SELECT` on schema `prod.finance`", "D": "`ALL PRIVILEGES` on catalog `prod`"}, "answer": "B", "short": "`USE CATALOG` on `prod`, `USE SCHEMA` on `prod.finance`, and `SELECT` on `prod.finance.ledger`.", "explanation": "The usage privileges are required to reach objects inside a catalog or schema, but they don't grant data access by themselves. A schema-level `SELECT` would be inherited by every current and future table in the schema, which is too broad here ([UC privileges](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)).", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "07-governance-and-security-q015", "bank": "praticas", "n": 143, "domain": "governance-and-security", "title": "Masking a Column by Group *(2026 blueprint)*", "difficulty": "medium", "question": "Only members of `finance_team` may see full values in `credit_card_number`. Everyone else should see a masked value, and everyone queries the same table. What should be implemented?", "choices": {"A": "`DENY SELECT` on the column for everyone except `finance_team`", "B": "A separate copy of the table per group", "C": "A column mask function using `is_account_group_member('finance_team')`, attached with `ALTER TABLE ... ALTER COLUMN credit_card_number SET MASK`", "D": "Cloud IAM permissions on the column"}, "answer": "C", "short": "A column mask function using `is_account_group_member('finance_team')`, attached with `ALTER TABLE ... ALTER COLUMN credit_card_number SET MASK`.", "explanation": "A column mask is a SQL UDF that receives the value and returns either the original or a masked value, evaluated per query. Its return type must match the column type. Copies drift, and `DENY` isn't a Unity Catalog column-level mechanism ([row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)).", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "07-governance-and-security-q016", "bank": "praticas", "n": 144, "domain": "governance-and-security", "title": "Row-Level Security *(2026 blueprint)*", "difficulty": "medium", "question": "Regional sales managers must see only the rows of `main.silver.orders` for their own region. Which implementation fits?", "choices": {"A": "`REVOKE SELECT` from all managers", "B": "A column mask on `region`", "C": "Partition the table by region and grant `SELECT` per partition", "D": "A row filter UDF returning `BOOLEAN` that checks group membership against `region`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER fn ON (region)`"}, "answer": "D", "short": "A row filter UDF returning `BOOLEAN` that checks group membership against `region`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER fn ON (region)`.", "explanation": "Rows for which the row filter returns `FALSE` are excluded from results. Masks change column values, not row visibility, and Unity Catalog doesn't grant privileges per partition ([row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)).", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "07-governance-and-security-q017", "bank": "praticas", "n": 145, "domain": "governance-and-security", "title": "Masking PII Across Many Tables *(2026 blueprint)*", "difficulty": "hard", "question": "A privacy team must mask every email column in all tables of the `main.silver` schema, including tables created later. Table owners must not be able to remove the masking. What should they use?", "choices": {"A": "A Unity Catalog ABAC column mask policy on the schema, matching columns tagged with a governed tag such as `pii = email`", "B": "A column mask set separately on each table by its owner", "C": "A dynamic view per table", "D": "An ABAC DENY policy on `SELECT`"}, "answer": "A", "short": "A Unity Catalog ABAC column mask policy on the schema, matching columns tagged with a governed tag such as `pii = email`.", "explanation": "ABAC policies (`CREATE POLICY ... COLUMN MASK ... FOR TABLES MATCH COLUMNS has_tag_value('pii','email')`) attach at catalog, schema, or table level and apply automatically to objects with matching governed tags. Because higher-level admins define them, table owners can't override or remove them. DENY policies currently deny only `MANAGE ACCESS CONTROL` ([ABAC](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/), [ABAC policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/policies)).", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "data-engineer-associate-mock-1-q001", "bank": "simulado-1", "n": 1, "domain": "databricks-intelligence-platform", "title": "A data engineering team is evaluating whether to migrate their existing data warehouse…", "difficulty": "medium", "question": "A data engineering team is evaluating whether to migrate their existing data warehouse to a Databricks Lakehouse. The primary concern is maintaining ACID guarantees for concurrent reads and writes on large tables. Which Databricks technology directly addresses this requirement?", "choices": {"A": "Apache Parquet file format with schema enforcement", "B": "Unity Catalog with row-level security", "C": "Databricks SQL Serverless warehouses", "D": "Delta Lake with transaction log (`_delta_log`)"}, "answer": "D", "short": "Delta Lake provides ACID transactions through its transaction log (`_delta_log`), which records every operation as an atomic commit. This enables concurrent readers and writers without data corruption. Parquet alone has no transaction support, Serverless warehouses are a compute option, and Unity Catalog handles governance — not storage-level ACID.", "explanation": "", "lesson": "01-databricks-intelligence-platform/04-delta-lake-fundamentals", "related": null}, {"id": "data-engineer-associate-mock-1-q002", "bank": "simulado-1", "n": 2, "domain": "databricks-intelligence-platform", "title": "An engineer is setting up a new Databricks workspace and needs to run interactive…", "difficulty": "medium", "question": "An engineer is setting up a new Databricks workspace and needs to run interactive notebooks for development while also running scheduled production jobs. Which cluster type should they use for each workload?", "choices": {"A": "All-purpose clusters for both — they are more flexible", "B": "Job clusters for both — they are cheaper and auto-terminate", "C": "All-purpose clusters for interactive notebooks; job clusters for scheduled production jobs", "D": "SQL warehouses for notebooks; job clusters for scheduled jobs"}, "answer": "C", "short": "All-purpose clusters support interactive, multi-user notebook sessions and persist between runs. Job clusters are created specifically for a single job run and terminate automatically upon completion, making them more cost-effective for production pipelines. SQL warehouses are optimized for SQL queries, not general notebook workloads.", "explanation": "", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "data-engineer-associate-mock-1-q003", "bank": "simulado-1", "n": 3, "domain": "databricks-intelligence-platform", "title": "A data engineer needs to query data as it existed 7 days ago from a Delta table named…", "difficulty": "medium", "question": "A data engineer needs to query data as it existed 7 days ago from a Delta table named `transactions`. Which command correctly retrieves this historical snapshot?", "choices": {"A": "`SELECT * FROM transactions WHERE _commit_timestamp >= date_sub(current_date(), 7)`", "B": "`SELECT * FROM transactions VERSION AS OF 7`", "C": "`SELECT * FROM transactions TIMESTAMP AS OF date_sub(current_date(), 7)`", "D": "`RESTORE TABLE transactions TO TIMESTAMP AS OF date_sub(current_date(), 7)`"}, "answer": "C", "short": "Delta Lake time travel using `TIMESTAMP AS OF` queries the table state at a specific point in time. `VERSION AS OF 7` queries version number 7 (the 8th commit), not 7 days ago. `RESTORE TABLE` permanently restores the table to a previous state rather than just reading it. `_commit_timestamp` is not a valid time travel filter syntax.", "explanation": "", "lesson": "01-databricks-intelligence-platform/05-time-travel-versioning", "related": null}, {"id": "data-engineer-associate-mock-1-q004", "bank": "simulado-1", "n": 4, "domain": "data-ingestion-and-loading", "title": "A SQL analyst runs this statement every morning: On Tuesday a vendor re-uploads…", "difficulty": "medium", "question": "A SQL analyst runs this statement every morning:\n\n```sql\nCOPY INTO main.bronze.orders\nFROM '/Volumes/main/raw/landing/orders'\nFILEFORMAT = CSV\nFORMAT_OPTIONS ('header' = 'true');\n```\n\nOn Tuesday a vendor re-uploads Monday's file, `orders_0901.csv`, with corrected values under the same name. Tuesday's run loads 0 rows. What explains this, and how can the analyst load the corrected file?", "choices": {"A": "`COPY INTO` is idempotent and skips files it has already loaded, even if they were modified. Re-run it with `FILES = ('orders_0901.csv')` and `COPY_OPTIONS ('force' = 'true')`", "B": "`COPY INTO` only reads files written after the table's latest commit. Run `OPTIMIZE` on the table first", "C": "The corrected file failed schema validation. Add `VALIDATE ALL` to load it", "D": "`COPY INTO` needs a checkpoint location to track files. Add one with `COPY_OPTIONS`"}, "answer": "A", "short": "`COPY INTO` is retriable and idempotent: files in the source location that were already loaded are skipped on later runs, even if they changed after loading.", "explanation": "Setting `'force' = 'true'` turns idempotency off and reloads files whether or not they were loaded before. Listing just that file with `FILES` keeps the reload from duplicating every other file. `VALIDATE` only checks data without loading it, so it can't load anything. A checkpoint location belongs to Auto Loader and Structured Streaming, not `COPY INTO`, which tracks loaded files internally.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-1-q005", "bank": "simulado-1", "n": 5, "domain": "data-ingestion-and-loading", "title": "A data engineer configures Auto Loader to ingest CSV files from an S3 bucket. The…", "difficulty": "medium", "question": "A data engineer configures Auto Loader to ingest CSV files from an S3 bucket. The pipeline runs every hour. What happens if 5 new files arrive between runs?", "choices": {"A": "Auto Loader automatically detects and processes all 5 new files in the next trigger", "B": "Only the first file is processed; subsequent files are queued for the next run", "C": "Auto Loader processes files only when triggered manually", "D": "Auto Loader fails if more than 1 file arrives between runs"}, "answer": "A", "short": "Auto Loader uses cloud storage notifications or directory listing combined with a checkpoint to track which files have been processed. On the next trigger, it automatically detects all new, unprocessed files and ingests them. This checkpointing mechanism ensures exactly-once processing without manual intervention or file tracking.", "explanation": "", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-1-q006", "bank": "simulado-1", "n": 6, "domain": "data-ingestion-and-loading", "title": "A team must ingest Salesforce objects into Unity Catalog tables incrementally, with as…", "difficulty": "easy", "question": "A team must ingest Salesforce objects into Unity Catalog tables incrementally, with as little custom code as possible. Which option does Databricks recommend?", "choices": {"A": "A notebook that calls the Salesforce REST API, scheduled with Lakeflow Jobs", "B": "Auto Loader pointed at the Salesforce instance URL", "C": "A Lakeflow Connect managed connector, which creates an ingestion pipeline that writes streaming tables", "D": "A Lakehouse Federation foreign catalog, queried by every downstream job"}, "answer": "C", "short": "SaaS applications such as Salesforce map to a Lakeflow Connect **managed connector**: no code, incremental, serverless, and governed by Unity Catalog.", "explanation": "Databricks recommends starting with the most managed layer and moving down only when it can't meet the requirement. A hand-written REST notebook is the fallback for sources without a connector. Auto Loader reads files in cloud storage, not a SaaS API. Federation queries a source in place without ingesting it, and the requirement here is to land the data in Unity Catalog tables.", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "data-engineer-associate-mock-1-q007", "bank": "simulado-1", "n": 7, "domain": "data-ingestion-and-loading", "title": "A streaming job reads from a Kafka topic and writes to a Delta table. The engineer…", "difficulty": "medium", "question": "A streaming job reads from a Kafka topic and writes to a Delta table. The engineer wants the job to process all currently available data and then stop automatically. Which trigger type should they configure?", "choices": {"A": "`trigger(processingTime=\"0 seconds\")` for continuous mode", "B": "`trigger(availableNow=True)` to process all available data then stop", "C": "`trigger(continuous=\"10 seconds\")` for low-latency micro-batch processing", "D": "No trigger configuration — streaming jobs stop automatically when the source is empty"}, "answer": "B", "short": "`trigger(availableNow=True)` (Spark 3.3+) or `trigger(once=True)` processes all currently available data in the stream source and then terminates the query. This is ideal for scheduled batch-style streaming jobs. `processingTime=\"0 seconds\"` runs as fast as possible but never stops. Streaming jobs do not stop automatically without explicit trigger configuration.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "data-engineer-associate-mock-1-q008", "bank": "simulado-1", "n": 8, "domain": "data-ingestion-and-loading", "title": "A notebook reads a 200-million-row PostgreSQL table with spark.read.format(\"jdbc\"),…", "difficulty": "medium", "question": "A notebook reads a 200-million-row PostgreSQL table with `spark.read.format(\"jdbc\")`, setting only `url`, `dbtable`, `user`, and `password`. The Spark UI shows the read running as a single task while the other cores sit idle. Which change parallelizes the read?", "choices": {"A": "Raise `fetchSize` to 1,000,000 rows", "B": "Call `.repartition(64)` right after `.load()`", "C": "Switch from `spark.read` to `spark.readStream`", "D": "Set `partitionColumn` (an indexed numeric column), `lowerBound`, `upperBound`, and `numPartitions`"}, "answer": "D", "short": "A JDBC read uses one thread by default. `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` split the key range into parallel queries against the database.", "explanation": "`fetchSize` only sets how many rows come back per network round trip, and a very large value can cause out-of-memory errors. `repartition` runs after the single-threaded read has finished, so the read itself stays serial. The JDBC source isn't a streaming source, so `readStream` doesn't help.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "data-engineer-associate-mock-1-q009", "bank": "simulado-1", "n": 9, "domain": "data-ingestion-and-loading", "title": "A data engineer notices that a Delta streaming job fails with StreamingQueryException:…", "difficulty": "hard", "question": "A data engineer notices that a Delta streaming job fails with `StreamingQueryException: Detected a data update in the source table`. What caused this error?", "choices": {"A": "The source Delta table had `OPTIMIZE` run on it while the stream was reading", "B": "The source Delta table had rows `UPDATE`d or `DELETE`d, which is not supported by default streaming reads", "C": "The streaming job ran out of memory due to large state size", "D": "The checkpoint directory was deleted, causing the stream to restart"}, "answer": "B", "short": "By default, Delta streaming reads assume an append-only source. If the source table has `UPDATE`, `DELETE`, or `MERGE` operations on existing rows, the stream throws this exception. To handle such sources, use `.option(\"skipChangeCommits\", \"true\")` (recommended on DBR 12.2 LTS+; it replaces the legacy `ignoreChanges`), or switch to Change Data Feed for CDC-aware streaming.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "data-engineer-associate-mock-1-q010", "bank": "simulado-1", "n": 10, "domain": "data-ingestion-and-loading", "title": "An Auto Loader stream feeds a Bronze table whose schema downstream teams rely on, so…", "difficulty": "medium", "question": "An Auto Loader stream feeds a Bronze table whose schema downstream teams rely on, so it must not change. The vendor sometimes adds new JSON fields. The stream must keep running when that happens, and the unexpected values must not be lost. Which `cloudFiles.schemaEvolutionMode` fits?", "choices": {"A": "`addNewColumns`", "B": "`failOnNewColumns`", "C": "`none`, with no rescued data column configured", "D": "`rescue`"}, "answer": "D", "short": "In `rescue` mode the schema never evolves and the stream doesn't fail. Values for unknown columns go into the `_rescued_data` column, so nothing is lost.", "explanation": "`addNewColumns` changes the schema, and it stops the stream with `UnknownFieldException` before picking up the new column on restart. `failOnNewColumns` stops the stream and keeps it failed until someone updates the schema. `none` ignores new columns, and without a rescued data column their values are dropped.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-1-q011", "bank": "simulado-1", "n": 11, "domain": "data-ingestion-and-loading", "title": "A business user sends a data engineer a 40 MB CSV file. The engineer wants it in Unity…", "difficulty": "easy", "question": "A business user sends a data engineer a 40 MB CSV file. The engineer wants it in Unity Catalog quickly, with no code, as a governed file that other teams can later load with `read_files` or `COPY INTO`. Which path fits?", "choices": {"A": "**New → Add or upload data → Upload files to a volume**, which needs `WRITE VOLUME` on the target volume", "B": "Mount a cloud storage bucket to DBFS and copy the file there", "C": "Configure a Lakeflow Connect managed connector for the file", "D": "Publish the file to a Kafka topic and read it with Structured Streaming"}, "answer": "A", "short": "The **Add or upload data** UI can upload local files into a Unity Catalog volume (`/Volumes/<catalog>/<schema>/<volume>/...`). It needs `WRITE VOLUME` on the volume and `USE CATALOG` and `USE SCHEMA` on its parents, and UI uploads accept up to 5 GB per file. Once the file is in a volume, `read_files`, `COPY INTO`, or Auto Loader can load it.", "explanation": "DBFS mounts are deprecated in favor of Unity Catalog volumes and external locations. Managed connectors are for SaaS applications and databases. A Kafka topic is a streaming source for events, not a way to land one file.", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "data-engineer-associate-mock-1-q012", "bank": "simulado-1", "n": 12, "domain": "data-ingestion-and-loading", "title": "A Bronze table has a STRING column named raw that holds JSON documents such as…", "difficulty": "medium", "question": "A Bronze table has a `STRING` column named `raw` that holds JSON documents such as `{\"customer\": {\"id\": 42}, \"line_items\": [{\"sku\": \"A1\"}, {\"sku\": \"B7\"}]}`. Which Databricks SQL expression returns the first item's SKU (`A1`)?", "choices": {"A": "`raw:line_items[0].sku`", "B": "`raw.line_items[0].sku`", "C": "`raw:line_items[1].sku`", "D": "`explode(raw.line_items)`"}, "answer": "A", "short": "When a column holds JSON **strings**, Databricks SQL extracts fields with the `:` path syntax, and array indexes are 0-based, so `raw:line_items[0].sku` returns `A1`.", "explanation": "Dot notation works on `STRUCT` columns, not on a plain string. Index `[1]` returns the second element (`B7`). `explode` turns an array into rows and can't run on a string field reference like this. For new tables, Databricks recommends the `VARIANT` type over JSON strings.", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": "03-data-transformation-and-modeling/04-advanced-transformations"}, {"id": "data-engineer-associate-mock-1-q013", "bank": "simulado-1", "n": 13, "domain": "data-transformation-and-modeling", "title": "A data engineer runs the following SQL command. What is the result?", "difficulty": "easy", "question": "A data engineer runs the following SQL command. What is the result?\n\n```sql\nCREATE OR REPLACE TABLE sales_summary AS\nSELECT region, SUM(amount) AS total_sales\nFROM transactions\nGROUP BY region;\n```", "choices": {"A": "Creates a new table only if it does not already exist", "B": "Creates a temporary view of the aggregated results", "C": "Appends aggregated results to the existing table", "D": "Creates a new table or replaces the entire table if it already exists"}, "answer": "D", "short": "`CREATE OR REPLACE TABLE ... AS SELECT` (CRAS) creates a new table with the query results. If a table with that name already exists, it is completely replaced (dropped and recreated). Use `CREATE TABLE IF NOT EXISTS` to skip creation when the table exists, or `INSERT INTO` to append rows.", "explanation": "", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "data-engineer-associate-mock-1-q014", "bank": "simulado-1", "n": 14, "domain": "data-transformation-and-modeling", "title": "A Databricks SQL query must return all rows from the orders table and only the…", "difficulty": "easy", "question": "A Databricks SQL query must return all rows from the `orders` table and only the matching rows from the `customers` table. Which JOIN type accomplishes this?", "choices": {"A": "INNER JOIN", "B": "RIGHT JOIN", "C": "LEFT JOIN", "D": "CROSS JOIN"}, "answer": "C", "short": "A LEFT JOIN returns all rows from the left table (`orders`) and matched rows from the right table (`customers`). Unmatched rows from `customers` appear as NULL. INNER JOIN returns only matched rows from both tables. RIGHT JOIN returns all rows from `customers` and matched rows from `orders` — the inverse of what is needed.", "explanation": "", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "data-engineer-associate-mock-1-q015", "bank": "simulado-1", "n": 15, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to find the top 3 highest-selling products within each product…", "difficulty": "medium", "question": "A data engineer needs to find the top 3 highest-selling products within each product category. Which SQL feature is most appropriate?", "choices": {"A": "GROUP BY with HAVING clause", "B": "Correlated subquery with LIMIT", "C": "Window function with `RANK() OVER (PARTITION BY category ORDER BY sales DESC)`", "D": "PIVOT table with category as columns"}, "answer": "C", "short": "Window functions with `RANK()` or `ROW_NUMBER()` partitioned by category and ordered by sales descending assign a rank to each product within its category. Filtering `WHERE rank <= 3` returns the top 3 per category. `GROUP BY` with `HAVING` can't retrieve individual rows within groups. Subqueries with `LIMIT` don't partition by category.", "explanation": "", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "data-engineer-associate-mock-1-q016", "bank": "simulado-1", "n": 16, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to apply a custom Python function to a column in a large Spark…", "difficulty": "medium", "question": "A data engineer needs to apply a custom Python function to a column in a large Spark DataFrame. The function uses a third-party library not available as a built-in Spark function. What is the recommended approach?", "choices": {"A": "Use `df.apply()` to apply the function row by row", "B": "Register the function as a Spark UDF with `spark.udf.register()` or `udf()`", "C": "Export the DataFrame to Pandas, apply the function, then convert back", "D": "Use `df.withColumn()` with a Python lambda directly without registration"}, "answer": "B", "short": "Spark UDFs (User-Defined Functions) allow custom Python logic to be applied to DataFrame columns in a distributed manner. They must be registered before use. Exporting to Pandas loses distributed processing and will fail on large datasets. `withColumn()` with a lambda doesn't work — Spark columns require Spark expressions or registered UDFs.", "explanation": "", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": null}, {"id": "data-engineer-associate-mock-1-q017", "bank": "simulado-1", "n": 17, "domain": "data-transformation-and-modeling", "title": "A data engineer uses explode() on a column containing arrays. What does this function do?", "difficulty": "easy", "question": "A data engineer uses `explode()` on a column containing arrays. What does this function do?", "choices": {"A": "Converts an array column into multiple rows, one row per array element", "B": "Removes all NULL values from array columns", "C": "Flattens nested structs into separate columns", "D": "Converts an array column into a string by joining elements"}, "answer": "A", "short": "`explode()` takes an array (or map) column and generates one new row per element, duplicating all other column values. This is the standard way to \"unnest\" array data in Spark. `flatten()` flattens nested arrays. Struct flattening uses `col(\"field.*\")`. `array_join()` converts an array to a string.", "explanation": "", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "data-engineer-associate-mock-1-q018", "bank": "simulado-1", "n": 18, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to combine two DataFrames that have the same schema, keeping all…", "difficulty": "easy", "question": "A data engineer needs to combine two DataFrames that have the same schema, keeping all rows from both including duplicates. Which operation should they use?", "choices": {"A": "`df1.join(df2, how=\"full\")`", "B": "`df1.union(df2)`", "C": "`df1.intersect(df2)`", "D": "`df1.merge(df2)`"}, "answer": "B", "short": "`union()` appends all rows from `df2` to `df1`, preserving duplicates. It requires both DataFrames to have the same schema (same column count and order). `join()` combines rows based on a key condition. `intersect()` returns only rows present in both DataFrames. Spark DataFrames don't have a `merge()` method.", "explanation": "", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "data-engineer-associate-mock-1-q019", "bank": "simulado-1", "n": 19, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to pivot sales data so that each product category becomes a…", "difficulty": "easy", "question": "A data engineer needs to pivot sales data so that each product category becomes a separate column showing total sales. Which SQL keyword accomplishes this?", "choices": {"A": "UNPIVOT", "B": "CROSSTAB", "C": "PIVOT", "D": "TRANSPOSE"}, "answer": "C", "short": "`PIVOT` in Databricks SQL rotates rows into columns. You specify the pivot column (categories) and the aggregation (SUM of sales). `UNPIVOT` does the reverse — converts columns to rows. `CROSSTAB` is not a standard SQL keyword in Databricks. `TRANSPOSE` is not a SQL operation.", "explanation": "", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "data-engineer-associate-mock-1-q020", "bank": "simulado-1", "n": 20, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to upsert records into a Delta table: update existing customer…", "difficulty": "medium", "question": "A data engineer needs to upsert records into a Delta table: update existing customer records when `customer_id` matches, and insert new records when there is no match. Which clause correctly completes the MERGE statement?\n\n```sql\nMERGE INTO customers AS target\nUSING updates AS source\nON target.customer_id = source.customer_id\nWHEN MATCHED THEN\n  UPDATE SET target.name = source.name, target.email = source.email\nWHEN NOT MATCHED THEN\n  ___________\n```", "choices": {"A": "`INSERT VALUES (source.customer_id, source.name, source.email)`", "B": "`INSERT INTO customers SELECT * FROM source`", "C": "`INSERT (customer_id, name, email) VALUES (source.customer_id, source.name, source.email)`", "D": "`INSERT * FROM source`"}, "answer": "C", "short": "The correct MERGE `WHEN NOT MATCHED` syntax is `INSERT (column_list) VALUES (source.column_list)`. The column list explicitly names the target columns, and the VALUES clause provides the source values. Option A is missing the column list. Options B and D are not valid MERGE syntax.", "explanation": "", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "data-engineer-associate-mock-1-q021", "bank": "simulado-1", "n": 21, "domain": "data-transformation-and-modeling", "title": "A data engineer uses the medallion architecture. Which layer is responsible for…", "difficulty": "easy", "question": "A data engineer uses the medallion architecture. Which layer is responsible for enforcing data quality rules, deduplication, and applying business logic transformations?", "choices": {"A": "Bronze layer — stores raw, unmodified ingested data", "B": "Silver layer — stores cleaned, filtered, and enriched data with quality checks applied", "C": "Gold layer — stores aggregate KPIs and metrics for reporting", "D": "The medallion architecture has no dedicated quality enforcement layer"}, "answer": "B", "short": "The Silver layer is where data quality enforcement, deduplication, schema normalization, and business logic transformations occur. Bronze stores raw data as-is for auditability and reprocessing. Gold stores aggregated, business-ready data optimized for analytics and BI reporting.", "explanation": "", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "data-engineer-associate-mock-1-q022", "bank": "simulado-1", "n": 22, "domain": "data-transformation-and-modeling", "title": "A DLT pipeline has an EXPECT constraint: EXPECT (amount > 0) ON VIOLATION DROP ROW. A…", "difficulty": "medium", "question": "A DLT pipeline has an `EXPECT` constraint: `EXPECT (amount > 0) ON VIOLATION DROP ROW`. A batch of 1,000 records arrives and 50 have `amount <= 0`. What happens?", "choices": {"A": "The entire batch fails and no records are written", "B": "All 1,000 records are written, and the 50 violating records are flagged in the event log", "C": "The 50 violating records are dropped and 950 valid records are written to the table", "D": "The pipeline pauses and waits for manual intervention to resolve the violations"}, "answer": "C", "short": "`ON VIOLATION DROP ROW` instructs DLT to discard rows that fail the expectation and continue processing valid rows. Violation counts are tracked in the DLT event log. `ON VIOLATION FAIL UPDATE` would fail the pipeline on any violation. `ON VIOLATION WARN` (the default with no modifier) writes all rows but logs violations without dropping any.", "explanation": "", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "data-engineer-associate-mock-1-q023", "bank": "simulado-1", "n": 23, "domain": "working-with-lakeflow-jobs", "title": "A data engineer needs to run a notebook that performs interactive EDA (exploratory…", "difficulty": "medium", "question": "A data engineer needs to run a notebook that performs interactive EDA (exploratory data analysis) with visualizations, then automatically hand off to a scheduled production pipeline. Which Databricks features best match these two phases respectively?", "choices": {"A": "All-purpose cluster for EDA; DLT pipeline for production", "B": "Job cluster for EDA; all-purpose cluster for production", "C": "SQL warehouse for EDA; serverless compute for production", "D": "All-purpose cluster for EDA; job cluster with Lakeflow Jobs for production"}, "answer": "D", "short": "All-purpose clusters support interactive notebook sessions ideal for EDA with visualizations and iterative development. Lakeflow Jobs with job clusters provide automated, scheduled, cost-efficient execution for production pipelines. Job clusters terminate after the job completes, reducing cost. SQL warehouses are optimized for SQL queries, not general notebook EDA.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": "01-databricks-intelligence-platform/03-compute-clusters"}, {"id": "data-engineer-associate-mock-1-q024", "bank": "simulado-1", "n": 24, "domain": "working-with-lakeflow-jobs", "title": "A partner drops files into a Unity Catalog volume at unpredictable times, from zero to…", "difficulty": "medium", "question": "A partner drops files into a Unity Catalog volume at unpredictable times, from zero to several drops a day. The team wants each drop processed within minutes and doesn't want runs that find no new data. Which Lakeflow Jobs trigger fits best?", "choices": {"A": "A scheduled trigger that runs every 5 minutes", "B": "A continuous trigger", "C": "A file arrival trigger on the volume, with Auto Loader in the job to process only the new files", "D": "A table update trigger on the Bronze table that the job writes to"}, "answer": "C", "short": "A file arrival trigger monitors a Unity Catalog external location or volume and starts a run when new files land. It checks for new files about every minute, on a best-effort basis. Inside the job, Auto Loader processes exactly the new files.", "explanation": "A 5-minute schedule starts many runs that find no data. A continuous trigger keeps a run active all the time. A table update trigger fires when a monitored table changes, but here the Bronze table is the job's own output, so it can't tell the job that new files have arrived.", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "data-engineer-associate-mock-1-q025", "bank": "simulado-1", "n": 25, "domain": "working-with-lakeflow-jobs", "title": "A data engineer is designing a Lakeflow Job with three tasks: ingest → transform →…", "difficulty": "medium", "question": "A data engineer is designing a Lakeflow Job with three tasks: `ingest → transform → report`. The `report` task must only run if `transform` succeeds. How should task dependencies be configured?", "choices": {"A": "Use a single-task job with all logic in one notebook to avoid dependency issues", "B": "Set `transform` and `report` to run in parallel to reduce total execution time", "C": "Use separate jobs for each task and chain them with external orchestration", "D": "Configure `transform` as a dependency of `report` using the `depends_on` task setting"}, "answer": "D", "short": "Lakeflow Jobs supports multi-task jobs with explicit task dependencies via `depends_on`. When `transform` fails, downstream tasks (`report`) don't run and are marked `Upstream failed` (default Run if: *All succeeded*). Running tasks in parallel would not enforce the required sequential dependency. Separate jobs with external orchestration adds unnecessary complexity.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": null}, {"id": "data-engineer-associate-mock-1-q026", "bank": "simulado-1", "n": 26, "domain": "working-with-lakeflow-jobs", "title": "A Lakeflow Job must run the same load_table notebook for 40 source tables, passing a…", "difficulty": "medium", "question": "A Lakeflow Job must run the same `load_table` notebook for 40 source tables, passing a different table name each time, with up to 5 loads running at once. What is the documented way to build this?", "choices": {"A": "Add 40 notebook tasks, one per table, each with a hard-coded table name", "B": "Add an If/else condition task that checks the table name", "C": "Add a Run Job task that triggers the job again for each table", "D": "Add a For each task over a JSON array of table names, with the notebook as its nested task and concurrency set to 5"}, "answer": "D", "short": "The **For each** task runs one nested task once per element of an input array. Each iteration reads its value with `{{input}}` (or `{{input.<key>}}` for objects), and **concurrency** sets how many iterations run in parallel. It defaults to 1.", "explanation": "Forty copied tasks work, but every change has to be repeated 40 times. If/else branches on a condition. It doesn't loop. A Run Job task triggers another job as a step, which isn't a loop over inputs.", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-1-q027", "bank": "simulado-1", "n": 27, "domain": "working-with-lakeflow-jobs", "title": "A production job fails intermittently due to transient cloud API errors. What built-in…", "difficulty": "medium", "question": "A production job fails intermittently due to transient cloud API errors. What built-in Lakeflow Jobs feature can automatically retry failed tasks without manual intervention?", "choices": {"A": "Task timeout configuration — the task retries when it exceeds the timeout", "B": "Per-task retry policy with configurable maximum retries and retry interval", "C": "Workflow-level SLA notifications that page the on-call engineer", "D": "Databricks auto-recovers all failed tasks by default with no configuration needed"}, "answer": "B", "short": "Lakeflow Jobs allows configuring a retry policy per task, specifying the maximum number of retry attempts and the interval between retries. This handles transient failures automatically. Timeout configuration controls how long a task runs before being killed, not whether it retries. Auto-recovery is not enabled by default.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-1-q028", "bank": "simulado-1", "n": 28, "domain": "working-with-lakeflow-jobs", "title": "The last task of a job, cleanup, drops staging tables. It depends on the transform…", "difficulty": "medium", "question": "The last task of a job, `cleanup`, drops staging tables. It depends on the `transform` task and uses the default dependency settings. Whenever `transform` fails, `cleanup` is skipped and marked `Upstream failed`. Which setting makes `cleanup` run whatever happens upstream?", "choices": {"A": "Set `cleanup`'s **Run if** condition to **All done**", "B": "Add a retry policy to `transform`", "C": "Set `cleanup`'s **Run if** condition to **At least one succeeded**", "D": "Raise the timeout on `cleanup`"}, "answer": "A", "short": "**All done** runs a task once all its dependencies have finished, whatever their outcome, which is the documented choice for cleanup tasks. The default, **All succeeded**, marks the task `Upstream failed` when a dependency fails.", "explanation": "**At least one succeeded** still skips `cleanup` here, because its only dependency failed. Retries make `transform` more likely to succeed, but `cleanup` is still skipped if every attempt fails. A timeout limits how long a task runs. It doesn't decide whether the task starts.", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-1-q029", "bank": "simulado-1", "n": 29, "domain": "working-with-lakeflow-jobs", "title": "A data engineer configures a Lakeflow Job with a schedule of 0 0 8 ? (Quartz cron…", "difficulty": "medium", "question": "A data engineer configures a Lakeflow Job with a schedule of `0 0 8 * * ?` (Quartz cron format). When does this job run?", "choices": {"A": "Every 8 minutes", "B": "Every hour at minute 8", "C": "At 8:00 AM every day", "D": "At 8:00 AM on the 8th of every month"}, "answer": "C", "short": "In Quartz cron format, fields are: second minute hour day-of-month month day-of-week. So `0 0 8 * * ?` means second=0, minute=0, hour=8, every day, every month. This fires at exactly 8:00:00 AM daily. `0 8 * * * ?` would run every hour at minute 8. `0 0 0 8 * ?` would run at midnight on the 8th of each month.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "data-engineer-associate-mock-1-q030", "bank": "simulado-1", "n": 30, "domain": "implementing-cicd", "title": "An engineer deploys a bundle with databricks bundle deploy -t dev. The dev target sets…", "difficulty": "easy", "question": "An engineer deploys a bundle with `databricks bundle deploy -t dev`. The `dev` target sets `mode: development`. The deployed job has a daily schedule in its YAML, but the schedule never fires. Why?", "choices": {"A": "Development mode pauses schedules and triggers on deployed resources", "B": "Bundles can't deploy job schedules. Schedules must be added in the Jobs UI", "C": "Scheduled jobs deployed from a bundle must run as a service principal", "D": "The schedule fires only after the bundle is also deployed to the `prod` target"}, "answer": "A", "short": "`mode: development` pauses schedules and triggers on the resources it deploys. It also prefixes their names with `[dev <user>]`, so personal copies don't run on their own or clash with shared ones.", "explanation": "Run the job with `databricks bundle run`, or unpause it explicitly in dev. Bundles do deploy schedules (`schedule.quartz_cron_expression` in the job YAML), and in `mode: production` they stay active. A service principal is recommended for production deployments, but it isn't why a dev schedule is paused.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-1-q031", "bank": "simulado-1", "n": 31, "domain": "implementing-cicd", "title": "An engineer has committed and pushed the branch feature/orders-dedup from a Databricks…", "difficulty": "easy", "question": "An engineer has committed and pushed the branch `feature/orders-dedup` from a Databricks Git folder. The team requires a review before any change is merged into `main`. Where is the pull request opened, reviewed, and merged?", "choices": {"A": "In the Git folder, with **Merge** from the Git dialog's kebab menu", "B": "In the notebook's revision history", "C": "By running `databricks bundle deploy -t prod`", "D": "In the Git provider's interface, such as GitHub, GitLab, or Azure DevOps"}, "answer": "D", "short": "Git folders handle branches, commits, pushes, and pulls in the workspace. The Databricks docs say to use your Git provider's interface to create a pull request and merge it into the default branch, where branch protection and reviews are enforced.", "explanation": "Merging locally from the Git dialog skips the review the team requires. Notebook revision history has no branches or pull requests. Deploying a bundle releases code. It doesn't review or merge it.", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "data-engineer-associate-mock-1-q032", "bank": "simulado-1", "n": 32, "domain": "implementing-cicd", "title": "A bundle needs a source database password at deploy time. A reviewer finds the…", "difficulty": "medium", "question": "A bundle needs a source database password at deploy time. A reviewer finds the password set as the `default` of a variable in `databricks.yml`. What is the recommended fix?", "choices": {"A": "Base64-encode the password before saving it as the default", "B": "Move the password under `targets.prod.variables` so it only applies to production", "C": "Store the password in a notebook widget's default value instead", "D": "Remove the default, rotate the password, and have the CI runner export `BUNDLE_VAR_db_password` from its secret store"}, "answer": "D", "short": "Secrets never belong in bundle YAML or notebooks, because both are committed to Git. Declare the variable with no default and let CI supply it as the `BUNDLE_VAR_<name>` environment variable from its secret store, so the value never touches the repository. A password that was committed should also be rotated.", "explanation": "Base64 is an encoding, not encryption. A target-level value and a widget default are both still in Git. At run time, notebooks can read credentials with `dbutils.secrets.get`.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-1-q033", "bank": "simulado-1", "n": 33, "domain": "implementing-cicd", "title": "A team's GitHub Actions workflow should fail a pull request check when the bundle…", "difficulty": "medium", "question": "A team's GitHub Actions workflow should fail a pull request check when the bundle configuration is malformed, without deploying anything. Which command should the workflow run?", "choices": {"A": "`databricks bundle validate`", "B": "`databricks bundle summary`", "C": "`databricks bundle destroy`", "D": "`databricks bundle generate`"}, "answer": "A", "short": "`databricks bundle validate` checks that the bundle configuration files are syntactically correct, which makes it the standard first step of a CI pipeline before `deploy -t <target>`.", "explanation": "`summary` lists the bundle's identity and already deployed resources. `destroy` deletes previously deployed jobs, pipelines, and artifacts. `generate` writes bundle YAML for a resource that already exists in the workspace.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-1-q034", "bank": "simulado-1", "n": 34, "domain": "implementing-cicd", "title": "Two engineers work on the same feature branch, each in their own Git folder. Engineer…", "difficulty": "medium", "question": "Two engineers work on the same feature branch, each in their own Git folder. Engineer B has pushed new commits. Engineer A has no local changes and wants B's commits in their Git folder. Which Git folder operation should A use?", "choices": {"A": "**Pull**", "B": "**Reset**", "C": "**Rebase**", "D": "**Commit & Push**"}, "answer": "A", "short": "**Pull** updates the Git folder's notebooks and files to the remote version. It also clears notebook state, so cells need to be re-run.", "explanation": "**Reset** is the equivalent of `git reset --hard` plus `git push --force`, and it discards both uncommitted and committed changes on the local and the remote branch. **Rebase** ends with a force push that rewrites history for collaborators. **Commit & Push** sends local changes to the remote, and there aren't any here.", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "data-engineer-associate-mock-1-q035", "bank": "simulado-1", "n": 35, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer writes a SQL query joining three large tables. The query is slow and…", "difficulty": "hard", "question": "A data engineer writes a SQL query joining three large tables. The query is slow and the Spark UI shows excessive shuffle volume. Which optimization should they apply first?", "choices": {"A": "Increase the number of shuffle partitions with `spark.sql.shuffle.partitions`", "B": "Use broadcast join hints for small dimension tables: `/*+ BROADCAST(dim) */`", "C": "Convert all joins to CROSS JOINs for performance", "D": "Add more worker nodes to the cluster"}, "answer": "B", "short": "If one or more tables are small enough to fit in memory (~200MB or less), a broadcast join eliminates the shuffle entirely by sending the small table to every executor. This is the most impactful optimization for join-heavy queries. Increasing shuffle partitions only changes partition count, not the total shuffle volume. Adding nodes doesn't eliminate the shuffle.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables", "related": "03-data-transformation-and-modeling/03-joins-aggregations"}, {"id": "data-engineer-associate-mock-1-q036", "bank": "simulado-1", "n": 36, "domain": "troubleshooting-monitoring-and-optimization", "title": "A Delta table has accumulated many small Parquet files over several months of…", "difficulty": "easy", "question": "A Delta table has accumulated many small Parquet files over several months of streaming ingestion. A data engineer runs `OPTIMIZE` on the table. What is the primary effect?", "choices": {"A": "Rewrites small Parquet files into larger, more efficient files to improve read performance", "B": "Deletes files marked for deletion by previous VACUUM operations", "C": "Recalculates column statistics and updates the transaction log", "D": "Converts the table from Parquet format to a different columnar format"}, "answer": "A", "short": "`OPTIMIZE` compacts small files into larger files (typically targeting 1GB) to reduce the overhead of reading many small files and improve scan efficiency. It does not delete files — `VACUUM` handles that. Statistics updates are a secondary benefit. Delta Lake always uses Parquet as its underlying storage format.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "data-engineer-associate-mock-1-q037", "bank": "simulado-1", "n": 37, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer runs VACUUM transactions RETAIN 168 HOURS. What is the effect on time…", "difficulty": "medium", "question": "A data engineer runs `VACUUM transactions RETAIN 168 HOURS`. What is the effect on time travel capabilities?", "choices": {"A": "No effect — VACUUM only removes duplicated data, not historical versions", "B": "Historical data files older than 168 hours (7 days) are permanently deleted and time travel to those versions is no longer possible", "C": "Delta Lake automatically creates a backup before running VACUUM", "D": "VACUUM retains exactly 168 versions of the table, not based on time"}, "answer": "B", "short": "`VACUUM` removes data files no longer referenced by the transaction log that are older than the retention period. Once vacuumed, time travel queries to those older versions fail because the underlying Parquet files are deleted. The default retention is 7 days (168 hours). Delta Lake does not automatically create backups before VACUUM.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "data-engineer-associate-mock-1-q038", "bank": "simulado-1", "n": 38, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer wants to Z-ORDER a Delta table by the customer_id column to improve…", "difficulty": "medium", "question": "A data engineer wants to Z-ORDER a Delta table by the `customer_id` column to improve query performance. When does Z-ORDER provide the most benefit?", "choices": {"A": "When queries always perform full table scans without any filters", "B": "Z-ORDER provides no benefit on Delta tables; use partitioning for all performance needs", "C": "When the table has fewer than 10 files and is already compact", "D": "When queries frequently filter on `customer_id`, enabling Delta's data skipping to skip entire files"}, "answer": "D", "short": "Z-ORDER co-locates related values within the same set of files, enabling Delta Lake's data skipping to skip entire files that don't contain queried `customer_id` values. This is most beneficial for high-cardinality columns frequently used in `WHERE` clauses. If queries always scan the full table, or the table is very small, Z-ORDER provides no benefit.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "data-engineer-associate-mock-1-q039", "bank": "simulado-1", "n": 39, "domain": "governance-and-security", "title": "An analyst needs to access data stored in an external S3 bucket from a Databricks…", "difficulty": "medium", "question": "An analyst needs to access data stored in an external S3 bucket from a Databricks cluster without hardcoding credentials in notebooks. Which approach is most appropriate?", "choices": {"A": "Store credentials in a notebook cell marked as hidden", "B": "Use Databricks Secrets with `dbutils.secrets.get()` to retrieve credentials at runtime", "C": "Export credentials as environment variables in the cluster init script", "D": "Pass credentials as job parameters in the Lakeflow Jobs UI"}, "answer": "B", "short": "Databricks Secrets provides a secure vault for storing sensitive values. `dbutils.secrets.get()` retrieves them at runtime and the values are never shown in logs or notebook output. Hardcoding in notebooks or init scripts exposes credentials in version control and logs. Job parameters are visible in the UI and logs.", "explanation": "", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion"}, {"id": "data-engineer-associate-mock-1-q040", "bank": "simulado-1", "n": 40, "domain": "governance-and-security", "title": "Members of the emea_sales group must see only the EMEA rows of main.silver.orders, and…", "difficulty": "medium", "question": "Members of the `emea_sales` group must see only the EMEA rows of `main.silver.orders`, and members of `admins` must see every row. Which Unity Catalog implementation fits?", "choices": {"A": "A SQL UDF that returns `BOOLEAN` using `is_account_group_member()`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER <function> ON (region)`", "B": "A column mask on the `region` column that returns `NULL` for non-EMEA values", "C": "`DENY SELECT ON TABLE main.silver.orders TO emea_sales`", "D": "A separate copy of the table for each region, with `SELECT` granted per group"}, "answer": "A", "short": "A **row filter** is a SQL UDF that returns `BOOLEAN` for each row. For example, `is_account_group_member('admins') OR (is_account_group_member('emea_sales') AND region = 'EMEA')`, attached with `SET ROW FILTER ... ON (region)`. Unity Catalog applies it to every query on the table.", "explanation": "A column mask changes the values in a column but returns every row. The classic `DENY` statement works only on the legacy Hive metastore, and it would hide the whole table anyway. Per-region copies duplicate data and drift out of sync.", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "data-engineer-associate-mock-1-q041", "bank": "simulado-1", "n": 41, "domain": "governance-and-security", "title": "A data engineer needs to grant a user access to query a specific table in Unity…", "difficulty": "hard", "question": "A data engineer needs to grant a user access to query a specific table in Unity Catalog without giving access to the entire schema. What is the minimum set of privileges required?", "choices": {"A": "`GRANT SELECT ON TABLE catalog.schema.table TO user` only", "B": "`GRANT SELECT ON SCHEMA catalog.schema TO user` only", "C": "`USE CATALOG` on the catalog + `USE SCHEMA` on the schema + `SELECT` on the table", "D": "`GRANT ALL PRIVILEGES ON TABLE catalog.schema.table TO user`"}, "answer": "C", "short": "Unity Catalog uses hierarchical privilege inheritance. To query a table, a user needs: `USE CATALOG` on the parent catalog, `USE SCHEMA` on the parent schema, and `SELECT` on the specific table. Without the `USE` privileges at each level, the user cannot navigate to the table even if `SELECT` is granted on the table itself. Granting `ALL PRIVILEGES` is overly permissive.", "explanation": "", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "data-engineer-associate-mock-1-q042", "bank": "simulado-1", "n": 42, "domain": "governance-and-security", "title": "A team registered the external Delta table main.bronze.vendor_feed over an existing…", "difficulty": "medium", "question": "A team registered the external Delta table `main.bronze.vendor_feed` over an existing cloud storage path. Nothing writes to that path directly any more, and the team now wants Unity Catalog to own the table's storage, without changing its name, permissions, or history. Ten days after the change, they may still need to undo it. Which approach fits?", "choices": {"A": "Drop the external table and re-create it as a managed table with `CREATE TABLE ... AS SELECT`", "B": "Run `RESTORE TABLE main.bronze.vendor_feed TO VERSION AS OF 0`, which restores the table as managed", "C": "Run `DEEP CLONE` into a new managed table and swap the names", "D": "Run `ALTER TABLE main.bronze.vendor_feed SET MANAGED`, and roll back with `ALTER TABLE ... UNSET MANAGED` within 14 days if needed"}, "answer": "D", "short": "`ALTER TABLE ... SET MANAGED` converts an external Delta table to a managed table in place. It keeps the name, settings, permissions, views, and table history, and needs Databricks Runtime 17.3 LTS+ or serverless and ownership of the table. `UNSET MANAGED` points the table back to its original external location, and it is available for 14 days after the conversion.", "explanation": "Dropping and re-creating, or cloning and swapping names, produces a new table that loses its grants and history. `RESTORE` restores data versions, not the table type. Existing read and write streams fail after the conversion and need a restart.", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "data-engineer-associate-mock-1-q043", "bank": "simulado-1", "n": 43, "domain": "governance-and-security", "title": "In a Unity Catalog-enabled workspace, an engineer runs DENY SELECT ON TABLE…", "difficulty": "hard", "question": "In a Unity Catalog-enabled workspace, an engineer runs `DENY SELECT ON TABLE prod.gold.revenue TO contractors`, and the statement fails. Contractors must not read the table. What is the correct approach?", "choices": {"A": "Run the same `DENY` statement as the table owner, because `DENY` requires ownership", "B": "`REVOKE SELECT ON TABLE prod.gold.revenue FROM contractors` (and from any groups that give them access), or don't grant it at all", "C": "Apply the `DENY` at the catalog level instead, so it is inherited by the table", "D": "Run `ALTER TABLE prod.gold.revenue SET DENY SELECT FOR contractors`"}, "answer": "B", "short": "The classic `DENY` statement is a legacy Hive metastore feature. In Unity Catalog, read access comes from `SELECT` granted on the table or inherited from a parent catalog or schema, directly or through a group, so you remove access with `REVOKE`, including from the groups the contractors belong to, or by never granting it. Partial access is handled with row filters, column masks, or ABAC policies.", "explanation": "Unity Catalog's only deny mechanism is the ABAC DENY policy (Beta), which currently covers just `MANAGE ACCESS CONTROL`, not `SELECT`. `SET DENY` is not valid syntax.", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "data-engineer-associate-mock-1-q044", "bank": "simulado-1", "n": 44, "domain": "governance-and-security", "title": "A data engineering team creates Unity Catalog external tables pointing to existing…", "difficulty": "hard", "question": "A data engineering team creates Unity Catalog external tables pointing to existing data in S3. Which Unity Catalog objects must be configured, and in what order?", "choices": {"A": "Storage Credential only — it automatically creates External Locations for referenced paths", "B": "External Location only — it includes embedded credential configuration", "C": "Catalog first, then Schema, then External Location", "D": "Storage Credential first (defines the IAM identity), then External Location (maps the cloud path to the credential)"}, "answer": "D", "short": "Configuring external storage access in Unity Catalog requires two objects in order: (1) a **Storage Credential** that holds the IAM role or service principal identity with cloud storage permissions, and (2) an **External Location** that maps a specific cloud storage path (e.g., `s3://bucket/prefix`) to that credential. External tables can then reference paths within registered External Locations.", "explanation": "", "lesson": "07-governance-and-security/01-unity-catalog-basics", "related": null}, {"id": "data-engineer-associate-mock-1-q045", "bank": "simulado-1", "n": 45, "domain": "governance-and-security", "title": "A data engineer wants to audit who accessed a specific Unity Catalog table and when.…", "difficulty": "medium", "question": "A data engineer wants to audit who accessed a specific Unity Catalog table and when. Which Databricks feature provides this capability?", "choices": {"A": "Delta Lake transaction log (`_delta_log`) — records all read and write operations", "B": "Databricks system tables (`system.access.audit`) — captures access events including table reads", "C": "Unity Catalog lineage graph — shows data flow but not individual user access events", "D": "Spark UI history server — stores query history with user attribution"}, "answer": "B", "short": "Databricks system tables include audit logs in `system.access.audit` that record who accessed what resources and when. The Delta transaction log records write operations (inserts, updates, deletes) but not reads. Lineage shows data flow between datasets. The Spark UI history tracks queries but is not designed for security auditing and has limited retention.", "explanation": "", "lesson": "07-governance-and-security/01-unity-catalog-basics", "related": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables"}, {"id": "data-engineer-associate-mock-2-q001", "bank": "simulado-2", "n": 1, "domain": "databricks-intelligence-platform", "title": "An analyst notices that a Databricks SQL warehouse is taking 3 minutes to run the…", "difficulty": "medium", "question": "An analyst notices that a Databricks SQL warehouse is taking 3 minutes to run the first query of the day but subsequent queries run in seconds. What is the most likely cause?", "choices": {"A": "The warehouse has a cold start delay because the compute nodes were terminated during the idle period", "B": "The warehouse is running out of memory after the first query", "C": "The first query always runs as a dry run without caching", "D": "The SQL optimizer is recomputing all table statistics for the first query"}, "answer": "A", "short": "SQL warehouses auto-stop after an idle period (defaults: 10 minutes for serverless, 45 minutes for pro and classic) to save cost. When a new query arrives, a stopped pro or classic warehouse must start again, which takes about 4 minutes. Serverless SQL warehouses start in about 2–6 seconds. Subsequent queries run fast because the cluster is already running.", "explanation": "", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "data-engineer-associate-mock-2-q002", "bank": "simulado-2", "n": 2, "domain": "databricks-intelligence-platform", "title": "A data engineer accidentally ran DELETE FROM customers WHERE 1=1 which deleted all…", "difficulty": "medium", "question": "A data engineer accidentally ran `DELETE FROM customers WHERE 1=1` which deleted all rows. The table is named `customers` in Delta format. How can they recover the data?", "choices": {"A": "`INSERT INTO customers SELECT * FROM customers VERSION AS OF previous_version`", "B": "`RESTORE TABLE customers TO VERSION AS OF previous_version`", "C": "Contact Databricks Support — deleted data cannot be recovered from Delta tables", "D": "Rerun the original data ingestion pipeline to recreate the data"}, "answer": "B", "short": "`RESTORE TABLE ... TO VERSION AS OF` (or `TIMESTAMP AS OF`) is the correct command to restore a Delta table to a previous version. It is an atomic operation that restores the table by re-referencing the old data files. This works as long as `VACUUM` has not deleted the files for that version. Option A creates a new table rather than restoring in-place.", "explanation": "", "lesson": "01-databricks-intelligence-platform/05-time-travel-versioning", "related": null}, {"id": "data-engineer-associate-mock-2-q003", "bank": "simulado-2", "n": 3, "domain": "databricks-intelligence-platform", "title": "A team runs a nightly ETL notebook on a shared all-purpose cluster that stays up all…", "difficulty": "medium", "question": "A team runs a nightly ETL notebook on a shared all-purpose cluster that stays up all day. Nobody watches the run, and the notebook needs no R, GPU, or custom init script. The team wants to cut cost and follow Databricks guidance for unattended production work. Which compute should the scheduled job use?", "choices": {"A": "The same all-purpose cluster, with auto termination turned off so it is always ready", "B": "A Pro SQL warehouse sized to the notebook's data volume", "C": "A single-node all-purpose cluster dedicated to the job", "D": "Serverless compute for jobs, or a jobs compute cluster that is created for each run and terminated afterwards"}, "answer": "D", "short": "For a nightly ETL notebook with no one watching, Databricks points to **serverless jobs** or **jobs compute**. Jobs compute is created for the run and terminated at the end, so you pay only while it runs, at the separate jobs price. Serverless bills DBUs for the work done with idle time minimized.", "explanation": "All-purpose compute is meant for interactive use and keeps billing while idle until auto termination, so turning auto termination off makes the cost worse. A SQL warehouse runs SQL for BI and ad hoc queries, not a general notebook job. Single-node compute suits small data and single-machine libraries, and it is still all-purpose compute.", "lesson": "01-databricks-intelligence-platform/03-compute-clusters", "related": null}, {"id": "data-engineer-associate-mock-2-q004", "bank": "simulado-2", "n": 4, "domain": "data-ingestion-and-loading", "title": "A data engineer must choose between COPY INTO and Auto Loader for ingesting files from…", "difficulty": "medium", "question": "A data engineer must choose between COPY INTO and Auto Loader for ingesting files from cloud storage. Which statement correctly describes when to use each?", "choices": {"A": "COPY INTO is for structured files; Auto Loader is for unstructured files", "B": "Auto Loader is deprecated; COPY INTO is the only recommended approach", "C": "COPY INTO is idempotent and suits smaller, known file sets; Auto Loader suits continuous, large-scale ingestion with automatic file tracking", "D": "Both are equivalent — the choice is purely based on personal preference"}, "answer": "C", "short": "COPY INTO is a SQL command that idempotently loads files into a Delta table (skipping already-loaded files) — suitable for smaller or periodic batch loads from a known set of files. Auto Loader uses checkpointing and cloud notifications to efficiently handle millions of files continuously at scale, making it the recommended approach for streaming ingestion pipelines.", "explanation": "", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-2-q005", "bank": "simulado-2", "n": 5, "domain": "data-ingestion-and-loading", "title": "An Auto Loader stream ingests JSON files with cloudFiles.schemaLocation set and no…", "difficulty": "easy", "question": "An Auto Loader stream ingests JSON files with `cloudFiles.schemaLocation` set and no other schema options. Every column in the Bronze table, including `amount` and `event_ts`, ends up as `STRING`. What explains this?", "choices": {"A": "For JSON, CSV, and XML, Auto Loader infers columns as strings unless `cloudFiles.inferColumnTypes` is `true` or `cloudFiles.schemaHints` sets the types", "B": "Auto Loader always writes `STRING` columns to Bronze tables, and types are applied only in Silver", "C": "The schema location is corrupt, so Auto Loader fell back to strings", "D": "JSON files can't carry numeric or timestamp values, so strings are the only option"}, "answer": "A", "short": "When Auto Loader infers a schema for JSON, CSV, or XML, it reads every column as a string by default. Setting `cloudFiles.inferColumnTypes` to `true` infers real types, and `cloudFiles.schemaHints` (SQL DDL such as `amount DECIMAL(10,2)`) overrides or adds specific types.", "explanation": "Avro and Parquet carry their types in the files, so they don't need this option. Nothing forces Bronze columns to be strings, and the behavior here is the documented default, not a fallback after an error.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-2-q006", "bank": "simulado-2", "n": 6, "domain": "data-ingestion-and-loading", "title": "A data engineer writes df = spark.read.format(\"delta\").load(\"/path/to/table\"). What is…", "difficulty": "medium", "question": "A data engineer writes `df = spark.read.format(\"delta\").load(\"/path/to/table\")`. What is the difference if they use `spark.readStream` instead of `spark.read`?", "choices": {"A": "`readStream` reads the entire table into memory at once; `read` reads in chunks", "B": "`readStream` automatically converts the Delta table to a Kafka stream", "C": "There is no difference — both return identical DataFrames", "D": "`readStream` returns a streaming DataFrame that only processes new files/rows added since the last checkpoint"}, "answer": "D", "short": "`spark.readStream.format(\"delta\").load(path)` creates a streaming DataFrame that treats the Delta table as a streaming source. It processes only new data (rows appended after the checkpoint) in each micro-batch. `spark.read` returns a static (batch) DataFrame representing the full table at the time of reading. The two APIs have fundamentally different execution semantics.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "data-engineer-associate-mock-2-q007", "bank": "simulado-2", "n": 7, "domain": "data-ingestion-and-loading", "title": "A data engineer configures Auto Loader with cloudFiles.schemaEvolutionMode =…", "difficulty": "medium", "question": "A data engineer configures Auto Loader with `cloudFiles.schemaEvolutionMode = \"addNewColumns\"`. A new column appears in incoming JSON files. What happens?", "choices": {"A": "The stream fails and can't restart until the schema is manually updated", "B": "The new column is silently ignored and not written to the Delta table", "C": "The stream stops with an `UnknownFieldException` after recording the new column. When restarted, it adds the column to the schema and continues", "D": "Auto Loader quarantines files with new columns for manual review"}, "answer": "C", "short": "With `addNewColumns` (the default when no schema is provided), Auto Loader stops the stream with `UnknownFieldException`, saves the evolved schema, and picks up the new column on restart. That's why Databricks recommends running these streams in Lakeflow Jobs with retries. `failOnNewColumns` is the mode that stays failed until the schema is fixed, and `rescue` puts unexpected columns into `_rescued_data` ([schema evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)).", "explanation": "", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-2-q008", "bank": "simulado-2", "n": 8, "domain": "data-ingestion-and-loading", "title": "A data engineer sets a watermark on a streaming query: withWatermark(\"event_time\", \"10…", "difficulty": "hard", "question": "A data engineer sets a watermark on a streaming query: `withWatermark(\"event_time\", \"10 minutes\")`. What is the purpose of this watermark?", "choices": {"A": "Defines the maximum tolerated lateness for event-time-based aggregations, allowing late data up to 10 minutes after the window closes", "B": "Ensures that data older than 10 minutes is deleted from the Delta table", "C": "Buffers all incoming data for exactly 10 minutes before writing to the sink", "D": "Limits the streaming query to process at most 10 minutes of historical data"}, "answer": "A", "short": "Watermarks in Spark Structured Streaming define how late data can arrive and still be included in aggregations. A 10-minute watermark means data with an event_time up to 10 minutes behind the current watermark is included; older data is dropped. This allows Spark to bound the state size by eventually discarding old windows.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": "03-data-transformation-and-modeling/04-advanced-transformations"}, {"id": "data-engineer-associate-mock-2-q009", "bank": "simulado-2", "n": 9, "domain": "data-ingestion-and-loading", "title": "An Auto Loader stream reads a landing directory that holds millions of files. Each…", "difficulty": "medium", "question": "An Auto Loader stream reads a landing directory that holds millions of files. Each micro-batch spends most of its time listing the directory. Which change does Databricks recommend for most workloads?", "choices": {"A": "Set `cloudFiles.useIncrementalListing` to `true`", "B": "Raise `cloudFiles.maxFilesPerTrigger` to 100,000", "C": "Replace Auto Loader with a scheduled `COPY INTO`", "D": "Use file notification mode with file events enabled on the Unity Catalog external location"}, "answer": "D", "short": "Directory listing, the default mode, lists the input directory on every micro-batch, which gets slow as the directory grows. Databricks recommends **file notification with file events**, enabled on the Unity Catalog external location, as more performant and scalable. You can switch modes across stream restarts and keep exactly-once processing.", "explanation": "`cloudFiles.useIncrementalListing` is deprecated. `maxFilesPerTrigger` caps how many files each micro-batch takes, but discovery still has to list the directory. `COPY INTO` is meant for modest, known file sets, not millions of files.", "lesson": "02-data-ingestion-and-loading/02-copy-into-and-auto-loader", "related": null}, {"id": "data-engineer-associate-mock-2-q010", "bank": "simulado-2", "n": 10, "domain": "data-ingestion-and-loading", "title": "A data engineer compares two streaming trigger settings: trigger(processingTime=\"1…", "difficulty": "medium", "question": "A data engineer compares two streaming trigger settings: `trigger(processingTime=\"1 minute\")` and `trigger(availableNow=True)`. Which scenario is best suited for each?", "choices": {"A": "`processingTime` for one-time batch runs; `availableNow` for continuous low-latency streams", "B": "`processingTime` for continuous micro-batch streaming on a 1-minute interval; `availableNow` for scheduled jobs that process all pending data then stop", "C": "Both are equivalent — the difference is only in the polling interval", "D": "`processingTime` is deprecated; use `availableNow` for all streaming jobs"}, "answer": "B", "short": "`trigger(processingTime=\"1 minute\")` runs micro-batches on a fixed 1-minute interval indefinitely — suitable for continuous, near-real-time streaming. `trigger(availableNow=True)` processes all currently available data and terminates — suitable for scheduled pipeline runs where a streaming source needs batch-style processing. Neither is deprecated.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": null}, {"id": "data-engineer-associate-mock-2-q011", "bank": "simulado-2", "n": 11, "domain": "data-ingestion-and-loading", "title": "A data engineer has a CSV directory and wants to convert it to a managed Delta table…", "difficulty": "medium", "question": "A data engineer has a CSV directory and wants to convert it to a managed Delta table in Unity Catalog. Which approach creates a properly managed Delta table?", "choices": {"A": "`CONVERT TO DELTA parquet.'/path/to/csv/'` — converts any format to Delta", "B": "Delta tables can only be created from Parquet format; CSV must first be converted to Parquet", "C": "`ALTER TABLE csv_table SET TYPE DELTA`", "D": "`CREATE TABLE catalog.schema.table USING DELTA AS SELECT * FROM csv.'/path/'`"}, "answer": "D", "short": "`CREATE TABLE ... USING DELTA AS SELECT * FROM csv.'/path/'` reads the CSV files and creates a new managed Delta table with the query results. `CONVERT TO DELTA` works only on Parquet-formatted directories (not CSV). `ALTER TABLE SET TYPE` is not valid Databricks SQL syntax. Delta tables can be created from any format via CTAS.", "explanation": "", "lesson": "02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion", "related": "03-data-transformation-and-modeling/01-spark-sql-fundamentals"}, {"id": "data-engineer-associate-mock-2-q012", "bank": "simulado-2", "n": 12, "domain": "data-ingestion-and-loading", "title": "A team sets up a Lakeflow Connect managed connector for continuous change data capture…", "difficulty": "medium", "question": "A team sets up a Lakeflow Connect managed connector for continuous change data capture from SQL Server. Which component runs continuously in its own job and stages the change data before it is written to the destination?", "choices": {"A": "The Unity Catalog connection", "B": "The destination streaming tables", "C": "The ingestion gateway", "D": "The ingestion pipeline"}, "answer": "C", "short": "Database connectors add an **ingestion gateway**. It runs as a continuous task in its own job and stages change data for continuous change capture.", "explanation": "The **connection** is a Unity Catalog securable that stores the source's authentication details. The **ingestion pipeline** reads the staged changes and writes them to the destination, and the destination tables are **streaming tables** in the catalog and schema you pick.", "lesson": "02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect", "related": null}, {"id": "data-engineer-associate-mock-2-q013", "bank": "simulado-2", "n": 13, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to replace all data in a partition of a Delta table with new…", "difficulty": "medium", "question": "A data engineer needs to replace all data in a partition of a Delta table with new data, without affecting other partitions. Which SQL command accomplishes this?", "choices": {"A": "`DELETE FROM table WHERE partition_col = 'value'` followed by `INSERT INTO`", "B": "`INSERT OVERWRITE table PARTITION (partition_col = 'value') SELECT ...`", "C": "`TRUNCATE TABLE table` then `INSERT INTO table SELECT ...`", "D": "`CREATE OR REPLACE TABLE table AS SELECT ...`"}, "answer": "B", "short": "`INSERT OVERWRITE ... PARTITION (...)` replaces data in the specified partition atomically while leaving other partitions untouched. `TRUNCATE TABLE` removes all data from all partitions. `CREATE OR REPLACE TABLE` replaces the entire table. The `DELETE` + `INSERT` approach works but is not atomic — `INSERT OVERWRITE` is preferred for partition replacement.", "explanation": "", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "data-engineer-associate-mock-2-q014", "bank": "simulado-2", "n": 14, "domain": "data-transformation-and-modeling", "title": "A data engineer has a column price stored as STRING type and needs to cast it to…", "difficulty": "easy", "question": "A data engineer has a column `price` stored as `STRING` type and needs to cast it to `DOUBLE` for calculations. Which SQL expression correctly performs this conversion?", "choices": {"A": "`CONVERT(price, DOUBLE)`", "B": "`price::DOUBLE`", "C": "`CAST(price AS DOUBLE)`", "D": "`TO_DOUBLE(price)`"}, "answer": "C", "short": "`CAST(column AS type)` is the standard SQL syntax for type conversion in Databricks SQL and Spark SQL. Databricks also supports the shorthand `column::type` (PostgreSQL-style). `CONVERT()` is valid in some SQL dialects but not Databricks SQL. `TO_DOUBLE()` is not a Databricks function.", "explanation": "", "lesson": "03-data-transformation-and-modeling/01-spark-sql-fundamentals", "related": null}, {"id": "data-engineer-associate-mock-2-q015", "bank": "simulado-2", "n": 15, "domain": "data-transformation-and-modeling", "title": "A data engineer writes SELECT FROM orders WHERE discount IS NOT NULL AND discount !=…", "difficulty": "medium", "question": "A data engineer writes `SELECT * FROM orders WHERE discount IS NOT NULL AND discount != 0`. A row with `discount = NULL` — will it be returned?", "choices": {"A": "Yes — `IS NOT NULL` matches NULL values", "B": "Yes — `discount != 0` returns all non-zero values including NULL", "C": "No — `IS NOT NULL` excludes NULL values; rows with NULL discount are filtered out", "D": "A SQL error occurs because you cannot compare NULL with `!=`"}, "answer": "C", "short": "`IS NOT NULL` filters out rows where the column contains NULL. Since both conditions are joined with `AND`, a row with `NULL` discount fails the `IS NOT NULL` check and is excluded. In SQL, `NULL != 0` evaluates to NULL (not TRUE), so NULL values are also excluded by the `!=` comparison — but `IS NOT NULL` already removes them first.", "explanation": "", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "data-engineer-associate-mock-2-q016", "bank": "simulado-2", "n": 16, "domain": "data-transformation-and-modeling", "title": "A data engineer writes Delta table data using…", "difficulty": "medium", "question": "A data engineer writes Delta table data using `df.write.format(\"delta\").mode(\"append\").save(path)`. What happens if the path already contains a Delta table with a different schema?", "choices": {"A": "The write succeeds and merges the schemas automatically", "B": "The new data is silently dropped and the existing table is unchanged", "C": "The existing table is overwritten with the new schema", "D": "The write fails with a `AnalysisException` due to schema mismatch unless `mergeSchema` is enabled"}, "answer": "D", "short": "Delta Lake enforces schema consistency by default. Appending data with a different schema throws an `AnalysisException`. To allow schema evolution during appends, enable `.option(\"mergeSchema\", \"true\")` which adds new columns from the source. Overwriting behavior requires `.mode(\"overwrite\")`, not `\"append\"`.", "explanation": "", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": "01-databricks-intelligence-platform/04-delta-lake-fundamentals"}, {"id": "data-engineer-associate-mock-2-q017", "bank": "simulado-2", "n": 17, "domain": "data-transformation-and-modeling", "title": "A data engineer queries a table with millions of rows and needs to know the count of…", "difficulty": "easy", "question": "A data engineer queries a table with millions of rows and needs to know the count of distinct values in a column. Which function returns this?", "choices": {"A": "`COUNT(DISTINCT column)`", "B": "`COUNT(column)`", "C": "`SUM(DISTINCT column)`", "D": "`APPROX_COUNT_DISTINCT(column)`"}, "answer": "A", "short": "`COUNT(DISTINCT column)` returns the exact number of distinct non-NULL values in the column. `COUNT(column)` counts non-NULL rows including duplicates. `SUM(DISTINCT column)` sums distinct numeric values, not counts. `APPROX_COUNT_DISTINCT()` uses HyperLogLog for an approximate count — faster for very large datasets but not exact.", "explanation": "", "lesson": "03-data-transformation-and-modeling/03-joins-aggregations", "related": null}, {"id": "data-engineer-associate-mock-2-q018", "bank": "simulado-2", "n": 18, "domain": "data-transformation-and-modeling", "title": "A data engineer uses collect_list() and collect_set() in a GROUP BY aggregation. What…", "difficulty": "medium", "question": "A data engineer uses `collect_list()` and `collect_set()` in a GROUP BY aggregation. What is the difference between these two functions?", "choices": {"A": "`collect_list` returns a sorted array; `collect_set` returns an unsorted array", "B": "`collect_list` preserves duplicates in the array; `collect_set` returns only distinct values", "C": "`collect_set` works on numeric types only; `collect_list` works on any type", "D": "Both functions are identical — the names are aliases for the same behavior"}, "answer": "B", "short": "`collect_list(col)` aggregates all values into an array including duplicates, preserving order. `collect_set(col)` aggregates into an array of unique values, with no guaranteed ordering. Use `collect_list` when duplicates and order matter; use `collect_set` when you only need distinct values.", "explanation": "", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "data-engineer-associate-mock-2-q019", "bank": "simulado-2", "n": 19, "domain": "data-transformation-and-modeling", "title": "A data engineer receives a DataFrame with a column containing nested arrays of arrays…", "difficulty": "medium", "question": "A data engineer receives a DataFrame with a column containing nested arrays of arrays (e.g., `[[1,2],[3,4]]`). Which function flattens this into a single-level array (e.g., `[1,2,3,4]`)?", "choices": {"A": "`explode()`", "B": "`transform()`", "C": "`array_join()`", "D": "`flatten()`"}, "answer": "D", "short": "`flatten(array_of_arrays)` converts a nested array (array of arrays) into a single flat array by concatenating the inner arrays. `explode()` creates one row per element — it doesn't flatten, it unnests. `array_join()` converts an array to a string. `transform()` applies a lambda to each element, producing an array of the same depth.", "explanation": "", "lesson": "03-data-transformation-and-modeling/04-advanced-transformations", "related": null}, {"id": "data-engineer-associate-mock-2-q020", "bank": "simulado-2", "n": 20, "domain": "data-transformation-and-modeling", "title": "A data engineer needs to delete records from a Delta table where a customer opted out,…", "difficulty": "hard", "question": "A data engineer needs to delete records from a Delta table where a customer opted out, and also update other customers' status in the same operation. Which SQL command handles both in a single atomic operation?", "choices": {"A": "Run `DELETE` and `UPDATE` as separate transactions in sequence", "B": "`TRUNCATE TABLE customers` then reinsert only the retained records", "C": "`MERGE INTO customers USING opt_outs ON ... WHEN MATCHED AND condition THEN DELETE WHEN MATCHED AND other_condition THEN UPDATE SET ...`", "D": "Use a Python loop to delete and update records one by one"}, "answer": "C", "short": "Delta Lake's `MERGE` statement supports multiple `WHEN MATCHED` clauses with different conditions — one can trigger `DELETE` and another can trigger `UPDATE SET`. This executes atomically in a single pass over the data. Running `DELETE` and `UPDATE` as separate transactions is correct but not atomic as a combined unit. `TRUNCATE` and reinsert is expensive and error-prone.", "explanation": "", "lesson": "03-data-transformation-and-modeling/02-dataframe-operations", "related": "04-working-with-lakeflow-jobs/03-control-flow"}, {"id": "data-engineer-associate-mock-2-q021", "bank": "simulado-2", "n": 21, "domain": "data-transformation-and-modeling", "title": "A DLT pipeline runs a full refresh. How does a full refresh differ from a standard…", "difficulty": "medium", "question": "A DLT pipeline runs a full refresh. How does a full refresh differ from a standard pipeline update?", "choices": {"A": "A full refresh only processes files added in the last 24 hours", "B": "A full refresh truncates all materialized tables and recomputes them from scratch using all source data", "C": "A full refresh updates only the tables with failed expectations from the previous run", "D": "A full refresh is identical to a standard update — the terminology is interchangeable"}, "answer": "B", "short": "A full refresh in Delta Live Tables drops all data in the pipeline's materialized tables and recomputes everything from the original sources. This is useful after fixing pipeline logic or recovering from data corruption. A standard update (incremental) processes only new data since the last checkpoint. Full refreshes are more expensive since they reprocess all historical data.", "explanation": "", "lesson": "03-data-transformation-and-modeling/06-gold-layer-objects", "related": null}, {"id": "data-engineer-associate-mock-2-q022", "bank": "simulado-2", "n": 22, "domain": "data-transformation-and-modeling", "title": "A DLT pipeline has an EXPECT constraint with no ON VIOLATION modifier. A record fails…", "difficulty": "medium", "question": "A DLT pipeline has an `EXPECT` constraint with no `ON VIOLATION` modifier. A record fails the constraint. What is the default behavior?", "choices": {"A": "The pipeline fails and stops processing", "B": "The violating record is dropped silently", "C": "The violating record is written to the output table and the violation is logged in the event log as a warning", "D": "The violating record is written to a quarantine table for review"}, "answer": "C", "short": "The default behavior of `EXPECT` without an `ON VIOLATION` modifier is `WARN` — all records (including violating ones) are written to the output table, and the number of violations is tracked in the DLT event log as metrics. To drop records, use `ON VIOLATION DROP ROW`. To fail the pipeline, use `ON VIOLATION FAIL UPDATE`.", "explanation": "", "lesson": "03-data-transformation-and-modeling/05-data-cleaning-and-quality", "related": null}, {"id": "data-engineer-associate-mock-2-q023", "bank": "simulado-2", "n": 23, "domain": "working-with-lakeflow-jobs", "title": "A data engineer uses dbutils.widgets.text(\"start_date\", \"2024-01-01\") in a notebook.…", "difficulty": "medium", "question": "A data engineer uses `dbutils.widgets.text(\"start_date\", \"2024-01-01\")` in a notebook. What is the purpose of this widget?", "choices": {"A": "Displays a text message at the top of the notebook output", "B": "Logs the value `\"2024-01-01\"` to the Databricks audit trail", "C": "Creates a permanent database variable that persists across cluster restarts", "D": "Creates a parameterized input that can be overridden when running the notebook as a job"}, "answer": "D", "short": "`dbutils.widgets` creates interactive input controls (text boxes, dropdowns, etc.) in the notebook UI. When the notebook is run as a Lakeflow Job, the widget value can be overridden via job parameters or the `notebookParams` API. This makes notebooks parameterizable and reusable across different date ranges or environments.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": "01-databricks-intelligence-platform/02-databricks-workspace"}, {"id": "data-engineer-associate-mock-2-q024", "bank": "simulado-2", "n": 24, "domain": "working-with-lakeflow-jobs", "title": "In a Lakeflow Job, the ingest task publishes the number of new rows with…", "difficulty": "medium", "question": "In a Lakeflow Job, the `ingest` task publishes the number of new rows with `dbutils.jobs.taskValues.set(key=\"rows_loaded\", value=rows)`. The `transform` task should run only when `rows_loaded` is greater than 0, and a `notify_no_data` task should run otherwise. How should the job be built?", "choices": {"A": "Add an If/else condition task after `ingest` that compares `{{tasks.ingest.values.rows_loaded}}` `>` `0`. Make `transform` depend on its `(true)` outcome and `notify_no_data` on its `(false)` outcome", "B": "Make both tasks depend on `ingest`, and have `transform` exit early in code when no rows were loaded", "C": "Use a For each task over `rows_loaded`", "D": "Set `notify_no_data`'s **Run if** to **At least one failed**, and make `ingest` fail when no rows are loaded"}, "answer": "A", "short": "The **If/else condition** task branches a job on a boolean expression. Operands can be literals, job parameters, or task values such as `{{tasks.ingest.values.rows_loaded}}`, and downstream tasks depend on its `(true)` or `(false)` outcome. `>` compares numbers, while `==` and `!=` compare strings.", "explanation": "An early exit in code still starts `transform` and hides the branch from the job graph. For each loops over an array of inputs. It doesn't branch. Making a task fail on purpose to drive control flow turns a normal empty day into a failed run.", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-2-q025", "bank": "simulado-2", "n": 25, "domain": "working-with-lakeflow-jobs", "title": "A data engineer uses dbutils.notebook.run(\"./child_notebook\", timeout_seconds=300,…", "difficulty": "medium", "question": "A data engineer uses `dbutils.notebook.run(\"./child_notebook\", timeout_seconds=300, arguments={\"date\": \"2024-01-15\"})`. What does this accomplish?", "choices": {"A": "Runs the child notebook synchronously in the current cluster, passing the date argument as a widget value", "B": "Runs the child notebook asynchronously in a separate Databricks job", "C": "Schedules the child notebook to run at the specified timeout in 300 seconds", "D": "Creates a permanent link between the parent and child notebook that runs on every commit"}, "answer": "A", "short": "`dbutils.notebook.run()` executes another notebook synchronously on the current cluster with a timeout. The `arguments` dictionary sets widget values in the child notebook. It blocks until the child completes or times out. Unlike `%run`, the child notebook runs in an isolated scope and its variables are not imported into the parent.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": "01-databricks-intelligence-platform/02-databricks-workspace"}, {"id": "data-engineer-associate-mock-2-q026", "bank": "simulado-2", "n": 26, "domain": "working-with-lakeflow-jobs", "title": "A data engineer uses task values to pass a dynamically computed date from Task A to…", "difficulty": "medium", "question": "A data engineer uses task values to pass a dynamically computed date from Task A to Task B in a multi-task Lakeflow Job. Which `dbutils` functions are used to set and retrieve the value?", "choices": {"A": "`dbutils.jobs.set(\"key\", value)` in Task A; `dbutils.jobs.get(\"key\")` in Task B", "B": "`dbutils.jobs.taskValues.set(key=\"key\", value=value)` in Task A; `dbutils.jobs.taskValues.get(taskKey=\"task_a\", key=\"key\")` in Task B", "C": "`dbutils.widgets.set(\"key\", value)` in Task A; `dbutils.widgets.get(\"key\")` in Task B", "D": "Write the value to DBFS in Task A; read from DBFS in Task B"}, "answer": "B", "short": "`dbutils.jobs.taskValues.set(key=..., value=...)` publishes a value from the current task. Downstream tasks read it with `dbutils.jobs.taskValues.get(taskKey=..., key=...)`, or reference it as `{{tasks.<task>.values.<key>}}` ([task values](https://docs.databricks.com/aws/en/jobs/task-values)). Widgets are for parameterizing notebooks, not passing values between tasks. DBFS would work but is an anti-pattern compared to the built-in task values API.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-2-q027", "bank": "simulado-2", "n": 27, "domain": "working-with-lakeflow-jobs", "title": "A Gold job reads main.silver.orders, which Team A refreshes, and…", "difficulty": "medium", "question": "A Gold job reads `main.silver.orders`, which Team A refreshes, and `main.silver.customers`, which Team B refreshes. Both teams finish at different, unpredictable times. The Gold job should run once both tables have been refreshed, with no polling. Which trigger fits?", "choices": {"A": "A scheduled trigger at 06:00 every day", "B": "A table update trigger on both tables with **Any table is updated**", "C": "A file arrival trigger on the Silver schema's storage location", "D": "A table update trigger on both tables with **All tables are updated**"}, "answer": "D", "short": "A **table update trigger** starts a run when monitored Unity Catalog tables change, with no compute running in between. When it monitors several tables, **All tables are updated** waits until every one of them has changed, which suits a job that needs every input fresh.", "explanation": "**Any table is updated** would start after the first team finishes, with the other input still stale. A fixed 06:00 schedule can run before either team is done. File arrival triggers watch for new files in a volume or external location, not table refreshes. The job's **Run as** principal needs `SELECT` on each table, plus `USE CATALOG` and `USE SCHEMA`, or the trigger can't evaluate.", "lesson": "04-working-with-lakeflow-jobs/02-scheduling-triggers", "related": null}, {"id": "data-engineer-associate-mock-2-q028", "bank": "simulado-2", "n": 28, "domain": "working-with-lakeflow-jobs", "title": "A production Lakeflow Job runs a task that occasionally takes much longer than usual…", "difficulty": "medium", "question": "A production Lakeflow Job runs a task that occasionally takes much longer than usual due to data volume spikes. To prevent the job from running indefinitely, which configuration should the engineer set?", "choices": {"A": "Retry policy with maximum retries set to 1", "B": "Task timeout — the maximum time in seconds a task is allowed to run before it is cancelled", "C": "Cluster autotermination minutes on the job cluster", "D": "Maximum concurrent runs set to 1"}, "answer": "B", "short": "Task timeout defines the maximum wall-clock time a task is allowed to run before Databricks automatically cancels it and marks the task as failed. This prevents runaway jobs from consuming resources indefinitely. Retry policy controls what happens after failure. Autotermination applies to idle clusters, not running tasks. Max concurrent runs controls parallel job instances.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/03-control-flow", "related": null}, {"id": "data-engineer-associate-mock-2-q029", "bank": "simulado-2", "n": 29, "domain": "working-with-lakeflow-jobs", "title": "A Lakeflow Job multi-task job has tasks A → B → C (sequential dependency). Task B…", "difficulty": "medium", "question": "A Lakeflow Job multi-task job has tasks A → B → C (sequential dependency). Task B fails. What is the default behavior for Task C?", "choices": {"A": "Task C runs anyway, using the last successful output from Task B", "B": "Task C doesn't run and is marked `Upstream failed` because its dependency failed", "C": "Task C waits indefinitely for Task B to be manually retried", "D": "The entire job reruns from Task A automatically"}, "answer": "B", "short": "When an upstream task fails in a Lakeflow Job, downstream tasks with the default Run if condition (*All succeeded*) are marked `Upstream failed`. Databricks does not run dependent tasks if their dependencies failed. If the job has retry configured, the failed task is retried first. Task C is not retried or rerun automatically.", "explanation": "", "lesson": "04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks", "related": null}, {"id": "data-engineer-associate-mock-2-q030", "bank": "simulado-2", "n": 30, "domain": "implementing-cicd", "title": "A data engineer wants to version control notebooks using Git and collaborate with…", "difficulty": "easy", "question": "A data engineer wants to version control notebooks using Git and collaborate with teammates via pull requests. Which Databricks feature supports this workflow?", "choices": {"A": "Databricks Archives — export notebooks to ZIP format for external storage", "B": "Lakeflow Jobs — tracks job run history as a proxy for code versions", "C": "Databricks File System — stores notebook files in DBFS with version history", "D": "Databricks Git folders (formerly Repos) — connects workspace folders to a remote Git repository"}, "answer": "D", "short": "Databricks Git folders (formerly Repos) integrates workspace folders directly with remote Git repositories (GitHub, GitLab, Azure DevOps, etc.). Engineers can commit, push, pull, create branches, and collaborate via pull requests without leaving the Databricks interface. DBFS does not provide version control. Workflows tracks job runs, not code changes.", "explanation": "", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "data-engineer-associate-mock-2-q031", "bank": "simulado-2", "n": 31, "domain": "implementing-cicd", "title": "A bundle declares the variable catalog with default: dev, and the prod target sets…", "difficulty": "hard", "question": "A bundle declares the variable `catalog` with `default: dev`, and the `prod` target sets `variables.catalog: prod`. The CI runner exports `BUNDLE_VAR_catalog=staging` and then runs `databricks bundle deploy -t prod` with no `--var` option. Which value does `${var.catalog}` resolve to?", "choices": {"A": "`staging`", "B": "`prod`", "C": "`dev`", "D": "The deploy fails because the variable is defined in two places"}, "answer": "A", "short": "Bundle variables are resolved at deploy time, in this order of precedence: the `--var` CLI option, then the `BUNDLE_VAR_<name>` environment variable, then `.databricks/bundle/<target>/variable-overrides.json`, then the value under the target, and last the top-level `default`.", "explanation": "No `--var` was passed, so the environment variable wins over the target-level `prod` value. This is a common reason a target's value seems to be ignored. Defining a value in several places is normal, and precedence decides which one is used.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-2-q032", "bank": "simulado-2", "n": 32, "domain": "implementing-cicd", "title": "A CI step runs databricks bundle deploy with no -t option. The bundle defines dev,…", "difficulty": "easy", "question": "A CI step runs `databricks bundle deploy` with no `-t` option. The bundle defines `dev`, `test`, and `prod` targets, and the code ends up in the dev workspace instead of prod. Why?", "choices": {"A": "Without `-t`, the bundle deploys to the target marked `default: true`", "B": "Without `-t`, the bundle deploys to every target in alphabetical order", "C": "`databricks bundle deploy` always deploys to dev, and prod requires `databricks bundle run`", "D": "The CI runner's service principal can access only the dev workspace"}, "answer": "A", "short": "When no target is given, the CLI uses the target marked `default: true`, which is usually `dev`. CI pipelines should always pass `-t <target>` explicitly.", "explanation": "A deploy goes to one target, not to all of them. `deploy` works for any target, and `run` starts a deployed job, pipeline, app, or script. Nothing in the scenario points to a permission problem: the deploy succeeded, just to the wrong target.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-2-q033", "bank": "simulado-2", "n": 33, "domain": "implementing-cicd", "title": "Which behavior applies to a bundle target set to mode: production?", "difficulty": "medium", "question": "Which behavior applies to a bundle target set to `mode: production`?", "choices": {"A": "Resource names get a `[dev <user>]` prefix, and schedules and triggers are paused", "B": "Clusters can be overridden with `--cluster-id` so production runs can reuse a developer's cluster", "C": "Validations check `run_as` and permissions, reject cluster overrides, and require the Git branch to match the target's configured branch", "D": "The deployment lock is disabled so several pipelines can deploy at once"}, "answer": "C", "short": "`mode: production` adds safety checks: it validates `run_as`, `permissions`, and that paths aren't user-specific, doesn't allow a `cluster_id` override, and requires the Git branch to match the target's configured branch (`--force` overrides that check). A service principal is the recommended identity.", "explanation": "The name prefix, paused schedules, and allowed cluster overrides all belong to `mode: development`. The deployment lock is enabled in production mode and disabled in development mode.", "lesson": "05-implementing-cicd/02-declarative-automation-bundles", "related": null}, {"id": "data-engineer-associate-mock-2-q034", "bank": "simulado-2", "n": 34, "domain": "implementing-cicd", "title": "A production Lakeflow Job points at a notebook inside an engineer's personal Git…", "difficulty": "medium", "question": "A production Lakeflow Job points at a notebook inside an engineer's personal Git folder. After the engineer switches to a branch that doesn't contain the notebook and then switches back, the job fails because the notebook now has a new ID. What is the recommended practice?", "choices": {"A": "Pin the job to the notebook's old URL", "B": "Forbid branch switching in that Git folder", "C": "Have every engineer share one Git folder for production", "D": "Have CI deploy a bundle from the merged `main` branch to the production workspace, run as a service principal"}, "answer": "D", "short": "Switching branches can delete workspace assets that the new branch doesn't contain. Switching back recreates them with new IDs and URLs, so any job that points at a personal Git folder is fragile.", "explanation": "Production jobs should run from a bundle that CI deploys from the merged branch, using a service principal. The old URL no longer exists. Blocking branch switches defeats the purpose of Git folders, and the docs advise against sharing one Git folder between people.", "lesson": "05-implementing-cicd/01-git-folders", "related": null}, {"id": "data-engineer-associate-mock-2-q035", "bank": "simulado-2", "n": 35, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer examines the Spark UI after a job completes and sees one task taking…", "difficulty": "hard", "question": "A data engineer examines the Spark UI after a job completes and sees one task taking 10× longer than all other tasks. What does this indicate?", "choices": {"A": "The cluster ran out of memory and had to spill to disk", "B": "The Photon engine failed to accelerate that specific task", "C": "A data skew problem — one partition contains significantly more data than others", "D": "Network latency caused a delay in fetching data from cloud storage"}, "answer": "C", "short": "A single slow task (stragglers) in the Spark UI typically indicates data skew — one partition has significantly more rows than others, causing one executor to do disproportionately more work. Solutions include salting keys, using `skewHint`, or repartitioning. Memory spill shows in the Spark UI as shuffle spill metrics, not as a single slow task.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables", "related": null}, {"id": "data-engineer-associate-mock-2-q036", "bank": "simulado-2", "n": 36, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer runs OPTIMIZE transactions ZORDER BY (customer_id, transaction_date).…", "difficulty": "hard", "question": "A data engineer runs `OPTIMIZE transactions ZORDER BY (customer_id, transaction_date)`. How does Z-ORDER with multiple columns differ from Z-ORDER with a single column?", "choices": {"A": "Z-ORDER with multiple columns is invalid — only one column is allowed", "B": "Z-ORDER with multiple columns co-locates data that shares similar values across all specified columns, optimizing queries filtering on any combination of those columns", "C": "Z-ORDER applies the first column's ordering first; the second column only applies within ties", "D": "Each column is independently Z-ORDERed in separate file groups"}, "answer": "B", "short": "Z-ORDER with multiple columns uses a space-filling curve to interleave the sort dimensions, co-locating rows that are similar in all specified columns simultaneously. This enables data skipping for queries filtering on `customer_id`, `transaction_date`, or both together. Option C describes a lexicographic sort, which is not how Z-ORDER works.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/03-delta-optimization", "related": null}, {"id": "data-engineer-associate-mock-2-q037", "bank": "simulado-2", "n": 37, "domain": "troubleshooting-monitoring-and-optimization", "title": "A data engineer wants to receive an email when a Lakeflow Job fails. Where is this…", "difficulty": "easy", "question": "A data engineer wants to receive an email when a Lakeflow Job fails. Where is this configured?", "choices": {"A": "In the cluster configuration under \"Termination Notifications\"", "B": "In the Databricks workspace admin settings under \"Global Notifications\"", "C": "Through a separate alerting notebook that monitors job status via the Jobs API", "D": "In the job's \"Notifications\" settings, where email addresses can be added for failure, success, or start events"}, "answer": "D", "short": "Lakeflow Jobs has a built-in \"Notifications\" section in the job configuration where you can specify email addresses to notify on job start, job success, job failure, and task failure events. This is configured per-job, not globally. A separate monitoring notebook is an alternative but unnecessary when built-in notifications are available.", "explanation": "", "lesson": "06-troubleshooting-monitoring-and-optimization/01-job-monitoring", "related": null}, {"id": "data-engineer-associate-mock-2-q038", "bank": "simulado-2", "n": 38, "domain": "troubleshooting-monitoring-and-optimization", "title": "A report notebook runs pdf = spark.table(\"main.silver.events\").toPandas() on a…", "difficulty": "hard", "question": "A report notebook runs `pdf = spark.table(\"main.silver.events\").toPandas()` on a 200-million-row table. The run fails with `java.lang.OutOfMemoryError` on the driver, and the notebook detaches. The engineer doubles the number of workers, and the error comes back. What is the right fix?", "choices": {"A": "Double the number of workers again, until the cluster has enough total memory", "B": "Keep the data distributed: aggregate or filter in Spark and collect only the small result (or write the output to a table), raising `spark.driver.memory` only if still needed", "C": "Raise `spark.sql.shuffle.partitions` so each partition is smaller", "D": "Enable autoscaling so Databricks adds workers when memory runs low"}, "answer": "B", "short": "A driver OOM usually comes from pulling data to the driver with `collect()` or `toPandas()`. Workers don't add driver memory, so more workers or autoscaling can't fix it. Aggregate in Spark first, for example `groupBy(\"event_type\").count().toPandas()`, or write results to a table and use `display()` or `limit()`.", "explanation": "More shuffle partitions help executor OOM and spill from oversized partitions, not a driver that is holding the whole table. Raising `spark.driver.memory` at the compute level is a last resort when the result really must live on the driver.", "lesson": "06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting", "related": null}, {"id": "data-engineer-associate-mock-2-q039", "bank": "simulado-2", "n": 39, "domain": "governance-and-security", "title": "A data engineer needs to store a small reference file that will be accessed by Spark…", "difficulty": "easy", "question": "A data engineer needs to store a small reference file that will be accessed by Spark jobs in a Databricks workspace. The file must be governed by Unity Catalog and accessible from any Unity Catalog-enabled compute without mount configuration. Which storage location is most appropriate?", "choices": {"A": "Cloud object storage (S3/ADLS) with manual mount configuration per cluster", "B": "DBFS root, which is mounted on every cluster automatically", "C": "Local disk of the driver node — fastest access for small files", "D": "A Unity Catalog volume, referenced by a path such as `/Volumes/main/ref/files/lookup.csv`"}, "answer": "D", "short": "Unity Catalog volumes govern non-tabular files with UC privileges (`READ VOLUME` / `WRITE VOLUME`) and are reachable from UC-enabled compute through `/Volumes/...` paths. DBFS root and mounts are deprecated, and Databricks recommends UC volumes, external locations, or workspace files instead ([What is DBFS?](https://docs.databricks.com/aws/en/dbfs/)). Local driver disk is ephemeral and not shared with other nodes.", "explanation": "", "lesson": "07-governance-and-security/01-unity-catalog-basics", "related": null}, {"id": "data-engineer-associate-mock-2-q040", "bank": "simulado-2", "n": 40, "domain": "governance-and-security", "title": "A company migrates from an existing Hive metastore to Unity Catalog. What is the key…", "difficulty": "medium", "question": "A company migrates from an existing Hive metastore to Unity Catalog. What is the key advantage of Unity Catalog over the workspace-level Hive metastore?", "choices": {"A": "Unity Catalog provides centralized governance, fine-grained access control, and data lineage across multiple workspaces", "B": "Unity Catalog stores data in a different file format for better performance", "C": "Unity Catalog eliminates the need for any access control configuration", "D": "Unity Catalog is faster because it uses an in-memory metadata cache"}, "answer": "A", "short": "Unity Catalog provides a centralized governance layer that spans multiple Databricks workspaces and accounts. It offers fine-grained table, column, and row-level security, automated data lineage tracking, and audit logs — none of which are available in the per-workspace Hive metastore. The metastore stores metadata; performance depends on the underlying data files.", "explanation": "", "lesson": "07-governance-and-security/01-unity-catalog-basics", "related": null}, {"id": "data-engineer-associate-mock-2-q041", "bank": "simulado-2", "n": 41, "domain": "governance-and-security", "title": "A data engineer creates a new Delta table in Unity Catalog using CREATE TABLE…", "difficulty": "easy", "question": "A data engineer creates a new Delta table in Unity Catalog using `CREATE TABLE catalog.schema.table`. Who automatically becomes the table owner?", "choices": {"A": "The workspace admin who configured Unity Catalog", "B": "The metastore admin", "C": "The user who created the table (the current session's identity)", "D": "Ownership is not assigned until explicitly set with `ALTER TABLE ... OWNER TO`"}, "answer": "C", "short": "In Unity Catalog, the user who creates an object (table, schema, catalog) automatically becomes its owner. Owners have full control over the object, including the ability to grant privileges to others and transfer ownership. Ownership can be transferred using `ALTER TABLE ... OWNER TO new_owner`.", "explanation": "", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}, {"id": "data-engineer-associate-mock-2-q042", "bank": "simulado-2", "n": 42, "domain": "governance-and-security", "title": "A data engineer needs to restrict certain users from seeing the full value of a ssn…", "difficulty": "medium", "question": "A data engineer needs to restrict certain users from seeing the full value of a `ssn` (social security number) column, showing only the last 4 digits instead. Which Unity Catalog feature implements this?", "choices": {"A": "Row-level security policy with a `WHERE` clause filter", "B": "Column masking policy that replaces the column value with a masked version based on user identity", "C": "Dynamic view with `CASE WHEN current_user() = 'admin' THEN ssn ELSE NULL END`", "D": "Remove the column from the table and create a separate table for privileged users"}, "answer": "B", "short": "Unity Catalog column masking policies apply a transformation function to a column's value based on the requesting user's identity or group membership. For example, showing only `'***-**-' || RIGHT(ssn, 4)` to non-privileged users while showing the full value to authorized users. Dynamic views (option C) also work but require maintaining a separate view object. Column masking is the purpose-built Unity Catalog feature.", "explanation": "", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "data-engineer-associate-mock-2-q043", "bank": "simulado-2", "n": 43, "domain": "governance-and-security", "title": "Hundreds of tables across the schema main.silver have email columns tagged with the…", "difficulty": "hard", "question": "Hundreds of tables across the schema `main.silver` have email columns tagged with the governed tag `pii = email`, and new tables are added every week. The governance team wants every tagged email column masked for the `analysts` group, now and in future tables, using one definition that table owners can't remove. What should they create?", "choices": {"A": "An ABAC policy created with `CREATE POLICY ... ON SCHEMA main.silver COLUMN MASK <function> TO analysts FOR TABLES MATCH COLUMNS has_tag_value('pii', 'email')`", "B": "A dynamic view over each table that hides the email column", "C": "A column mask on each email column, applied with `ALTER TABLE ... ALTER COLUMN ... SET MASK`", "D": "A row filter on each table that returns `FALSE` for the `analysts` group"}, "answer": "A", "short": "**ABAC policies** evaluate governed tags. One policy attached to a catalog or schema masks every matching column in current and future tables, and because higher-level admins define it, table owners can't override or remove it. ABAC needs Databricks Runtime 16.4+ or serverless compute.", "explanation": "Per-column masks and dynamic views have to be repeated for every new table, and owners can change them. A row filter removes whole rows instead of masking a column.", "lesson": "07-governance-and-security/04-row-filters-column-masks-abac", "related": null}, {"id": "data-engineer-associate-mock-2-q044", "bank": "simulado-2", "n": 44, "domain": "governance-and-security", "title": "A data engineer creates an external table in Unity Catalog pointing to an S3 path.…", "difficulty": "medium", "question": "A data engineer creates an external table in Unity Catalog pointing to an S3 path. What happens to the underlying data files when the table is dropped with `DROP TABLE`?", "choices": {"A": "The data files are deleted along with the table metadata", "B": "The data files are moved to a Unity Catalog-managed trash location for 30 days", "C": "The data files are retained in cloud storage; only the table metadata (catalog registration) is removed", "D": "`DROP TABLE` fails on external tables — you must use `DROP EXTERNAL TABLE`"}, "answer": "C", "short": "External tables in Unity Catalog (and Databricks in general) only store metadata — the table definition pointing to an external cloud storage location. When dropped, only the metadata registration is removed. The underlying data files in S3 or ADLS are untouched. This is the key difference from managed tables, where dropping the table also deletes the data files.", "explanation": "", "lesson": "07-governance-and-security/02-managed-and-external-tables", "related": null}, {"id": "data-engineer-associate-mock-2-q045", "bank": "simulado-2", "n": 45, "domain": "governance-and-security", "title": "A data engineer queries SELECT FROM system.access.audit LIMIT 100 and sees events with…", "difficulty": "medium", "question": "A data engineer queries `SELECT * FROM system.access.audit LIMIT 100` and sees events with `actionName = 'getTable'`. What do these events represent?", "choices": {"A": "Metadata queries where a user read the table's schema or properties", "B": "Full table scans where all rows were returned to the user", "C": "Table creation events logged when a new table is registered", "D": "Failed access attempts where permission was denied"}, "answer": "A", "short": "In Databricks audit logs, `getTable` action events are recorded when a user reads a table's metadata (schema, properties, statistics) — this includes actions like `DESCRIBE TABLE` or when a BI tool queries the catalog for table info. Full data reads are logged as `commandSubmit`/`commandFinish` events. Permission denials are recorded as separate audit events with error details.", "explanation": "", "lesson": "07-governance-and-security/03-access-control-permissions", "related": null}]};
